-- Explicit private worker profile. No canonical migration or historical pin changes.
CREATE SCHEMA zasp_authorization80_worker AUTHORIZATION zasp_discovery_authority;
REVOKE ALL ON SCHEMA zasp_authorization80_worker FROM PUBLIC;
CREATE TABLE zasp_authorization80_worker.registration(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),checksum text NOT NULL,fingerprint text NOT NULL);
CREATE TABLE zasp_authorization80_worker.predecessor_functions(signature text PRIMARY KEY,definition text NOT NULL,owner_name text NOT NULL,acl text NOT NULL);
CREATE TABLE zasp_authorization80_worker.predecessor_views(signature text PRIMARY KEY,definition text NOT NULL);
CREATE TABLE zasp_authorization80_worker.verifiers(purpose text PRIMARY KEY CHECK(purpose IN('worker-forward','captured-compensation')),version text NOT NULL CHECK(version~'^[a-f0-9]{64}$'),key bytea NOT NULL CHECK(octet_length(key)=32));
CREATE TABLE zasp_authorization80_worker.associations(
 organization_id text NOT NULL,workspace_id text NOT NULL,environment_id text NOT NULL,run_id text NOT NULL,
 principal_id text NOT NULL,grantor_id text NOT NULL,definition_id text NOT NULL,definition_version bigint NOT NULL,
 finding_id text NOT NULL,source_digest text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(organization_id,workspace_id,environment_id,run_id));
CREATE TABLE zasp_authorization80_worker.revocations(
 organization_id text NOT NULL,workspace_id text NOT NULL,environment_id text NOT NULL,run_id text NOT NULL,
 revoked_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(organization_id,workspace_id,environment_id,run_id),
 FOREIGN KEY(organization_id,workspace_id,environment_id,run_id) REFERENCES zasp_authorization80_worker.associations);
CREATE TABLE zasp_authorization80_worker.run_state(
 organization_id text NOT NULL,workspace_id text NOT NULL,environment_id text NOT NULL,run_id text NOT NULL,
 definition_id text NOT NULL,definition_version bigint NOT NULL,state text NOT NULL,run_version bigint NOT NULL,present boolean NOT NULL,
 PRIMARY KEY(organization_id,workspace_id,environment_id,run_id),
 FOREIGN KEY(organization_id,workspace_id,environment_id,run_id) REFERENCES zasp_authorization80_worker.associations);

DO $tables$ DECLARE n text;BEGIN
 FOREACH n IN ARRAY ARRAY['registration','predecessor_functions','predecessor_views','verifiers','associations','revocations','run_state'] LOOP
  EXECUTE format('ALTER TABLE zasp_authorization80_worker.%I OWNER TO zasp_discovery_authority',n);
  EXECUTE format('ALTER TABLE zasp_authorization80_worker.%I ENABLE ROW LEVEL SECURITY',n);
  EXECUTE format('ALTER TABLE zasp_authorization80_worker.%I FORCE ROW LEVEL SECURITY',n);
  EXECUTE format('CREATE POLICY authority ON zasp_authorization80_worker.%I TO zasp_discovery_authority USING(true) WITH CHECK(true)',n);
  IF n NOT IN('verifiers','run_state') THEN EXECUTE format('CREATE TRIGGER immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON zasp_authorization80_worker.%I FOR EACH STATEMENT EXECUTE FUNCTION zasp_temporal67.immutable()',n);END IF;
 END LOOP;
END $tables$;

-- Save only identities this stage changes. Full predecessor78 readiness was
-- checked by the installer before these bytes were read.
INSERT INTO zasp_authorization80_worker.predecessor_functions
 SELECT oid::regprocedure::text,pg_get_functiondef(oid),proowner::regrole::text,COALESCE(proacl::text,'') FROM pg_proc
 WHERE oid IN('zasp_temporal78.apply(jsonb)'::regprocedure,'zasp_temporal78.cleanup(jsonb)'::regprocedure,'zasp_temporal78.plan(jsonb)'::regprocedure,'zasp_temporal78.planning_state(jsonb)'::regprocedure,'zasp_temporal78.serialize_revocation()'::regprocedure,'zasp_temporal78.fingerprint()'::regprocedure,'zasp_authorization79.fingerprint()'::regprocedure);
INSERT INTO zasp_authorization80_worker.predecessor_views SELECT oid::regclass::text,pg_get_viewdef(oid) FROM pg_class WHERE oid IN('zasp_authorization79.members'::regclass,'zasp_authorization79.current_grants'::regclass,'zasp_authorization79.resources'::regclass);
INSERT INTO zasp_authorization80_worker.predecessor_functions
 SELECT oid::regprocedure::text,pg_get_functiondef(oid),proowner::regrole::text,COALESCE(proacl::text,'') FROM pg_proc
 WHERE oid IN('zasp_temporal74.plan(jsonb)'::regprocedure,'zasp_temporal74.planning_state(jsonb)'::regprocedure,'zasp_temporal74.serialize_revocation()'::regprocedure,'zasp_temporal76.executor74_fingerprint()'::regprocedure,'zasp_authorization79.pending(integer)'::regprocedure,'zasp_authorization79.snapshot(text)'::regprocedure,'zasp_authorization80_temporal.projected_domain()'::regprocedure,'zasp_authorization80_temporal.fingerprint()'::regprocedure);

INSERT INTO zasp_authorization80_worker.predecessor_functions
 SELECT oid::regprocedure::text,pg_get_functiondef(oid),proowner::regrole::text,COALESCE(proacl::text,'') FROM pg_proc
 WHERE oid IN('zasp_temporal74.effect(jsonb)'::regprocedure,'zasp_temporal74.linked(jsonb)'::regprocedure,'zasp_temporal74.test_state(jsonb)'::regprocedure,'zasp_temporal74.invocation(jsonb)'::regprocedure);

INSERT INTO zasp_authorization80_worker.predecessor_functions
 SELECT oid::regprocedure::text,pg_get_functiondef(oid),proowner::regrole::text,COALESCE(proacl::text,'') FROM pg_proc
 WHERE oid IN('zasp_temporal74.test_validate_output(text,text,text,text,text,jsonb,bytea,jsonb,bytea)'::regprocedure,'zasp_temporal74.test_settle(jsonb)'::regprocedure);

INSERT INTO zasp_authorization80_worker.predecessor_functions
 SELECT oid::regprocedure::text,pg_get_functiondef(oid),proowner::regrole::text,COALESCE(proacl::text,'') FROM pg_proc
 WHERE oid='zasp_authorization80_temporal.projected68()'::regprocedure;

-- Historical audit bytes remain immutable. Re-render only proven equal
-- timestamp instants in the expected row, then retain the original full JSON
-- comparison. Unknown fields, missing fields and all non-time values still
-- participate in that comparison.
CREATE FUNCTION zasp_authorization80_worker.planner_receipt_row(captured jsonb,actual jsonb,kind text) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog,public AS $receipt_row$
DECLARE names text[];name text;rendered jsonb:=actual;pattern text:='^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,6})?[+-][0-9]{2}:[0-9]{2}$';
BEGIN
 IF jsonb_typeof(captured) IS DISTINCT FROM 'object' OR jsonb_typeof(actual) IS DISTINCT FROM 'object' THEN RETURN NULL;END IF;
 names:=CASE kind WHEN 'job' THEN ARRAY['budget_started_at','budget_deadline_at'] WHEN 'reservation' THEN ARRAY['reserved_at','settled_at','released_at'] ELSE NULL END;
 IF names IS NULL THEN RETURN NULL;END IF;
 FOREACH name IN ARRAY names LOOP
  IF (captured?name) IS DISTINCT FROM(actual?name) THEN RETURN NULL;END IF;
  IF NOT(actual?name) THEN CONTINUE;END IF;
  IF actual->name='null'::jsonb THEN
   IF captured->name IS DISTINCT FROM 'null'::jsonb THEN RETURN NULL;END IF;
  ELSE
   IF jsonb_typeof(captured->name) IS DISTINCT FROM 'string' OR jsonb_typeof(actual->name) IS DISTINCT FROM 'string'
    OR NOT(captured->>name ~ pattern) OR NOT(actual->>name ~ pattern)
    OR (captured->>name)::timestamptz IS DISTINCT FROM(actual->>name)::timestamptz THEN RETURN NULL;END IF;
   rendered:=jsonb_set(rendered,ARRAY[name],captured->name);
  END IF;
 END LOOP;
 RETURN rendered;
EXCEPTION WHEN data_exception THEN RETURN NULL;
END $receipt_row$;

-- Transient signed facts need one representation across pooled sessions.
-- This hashes the complete job, normalizing only its two typed timestamp
-- columns. Context/provider strings and every other field stay unchanged.
CREATE FUNCTION zasp_authorization80_worker.planner_job_digest(j jsonb) RETURNS text LANGUAGE sql STABLE SET search_path=pg_catalog,public SET timezone='UTC' AS $job_digest$
 SELECT encode(digest(convert_to(COALESCE((j||jsonb_build_object('budget_started_at',(j->>'budget_started_at')::timestamptz,'budget_deadline_at',(j->>'budget_deadline_at')::timestamptz))::text,'null'),'UTF8'),'sha256'),'hex')
$job_digest$;

-- Capture original function identities before modifying any consumer. The
-- installer has already verified the exact predecessor graph. Its projections
-- preserve those identities while the worker catalog hashes live replacements.
INSERT INTO zasp_authorization80_worker.predecessor_functions
 SELECT p.oid::regprocedure::text,pg_get_functiondef(p.oid),p.proowner::regrole::text,COALESCE(p.proacl::text,'') FROM pg_proc p
 WHERE p.oid=ANY(ARRAY[
 'zasp_temporal68.planning_terminal_valid(text,text,text,text)'::regprocedure,'zasp_temporal68.late_usage_valid(text,text,text,text)'::regprocedure,
 'zasp_temporal74.planning_terminal_valid(text,text,text,text)'::regprocedure,'zasp_temporal74.late_usage_valid(text,text,text,text)'::regprocedure,
 'zasp_temporal78.planning_terminal_valid(text,text,text,text)'::regprocedure,'zasp_temporal78.late_usage_valid(text,text,text,text)'::regprocedure]);
DO $portable_validators$ DECLARE source record;d text;needle text;replacement text;namespace text;kind text;BEGIN
 FOREACH namespace IN ARRAY ARRAY['zasp_temporal68','zasp_temporal74','zasp_temporal78'] LOOP
  FOREACH kind IN ARRAY ARRAY['planning_terminal_valid','late_usage_valid'] LOOP
   SELECT * INTO STRICT source FROM zasp_authorization80_worker.predecessor_functions WHERE signature=namespace||'.'||kind||'(text,text,text,text)';
   IF source.owner_name<>'zasp_discovery_authority' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='planner receipt predecessor owner changed';END IF;
   d:=source.definition;
   needle:='to_jsonb(j)';
   IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='planner job receipt predecessor changed';END IF;
   d:=replace(d,needle,$job$zasp_authorization80_worker.planner_receipt_row(a.body->'job',to_jsonb(j),'job')$job$);
   IF kind='planning_terminal_valid' THEN
    needle:='to_jsonb(p)';
    IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='planner reservation receipt predecessor changed';END IF;
    d:=replace(d,needle,$reservation$zasp_authorization80_worker.planner_receipt_row(a.body->'reservation',to_jsonb(p),'reservation')$reservation$);
    -- jsonb_build_object coerces SQL NULL to JSON null. A rejected helper
    -- result must never become equal to a malformed captured null row.
    needle:=' AND a.body=jsonb_build_object(';
    IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='planner terminal body predecessor changed';END IF;
    d:=replace(d,needle,$guard$ AND zasp_authorization80_worker.planner_receipt_row(a.body->'job',to_jsonb(j),'job') IS NOT NULL
  AND (p.run_id IS NULL OR zasp_authorization80_worker.planner_receipt_row(a.body->'reservation',to_jsonb(p),'reservation') IS NOT NULL)
  AND a.body=jsonb_build_object($guard$);
   ELSE
    needle:=$original$to_jsonb(p)-ARRAY['settled_at','output_digest','prompt_tokens','completion_tokens','total_tokens','cost_nano_credits']$original$;
    replacement:=$original$zasp_authorization80_worker.planner_receipt_row(original-ARRAY['settled_at','output_digest','prompt_tokens','completion_tokens','total_tokens','cost_nano_credits'],to_jsonb(p)-ARRAY['settled_at','output_digest','prompt_tokens','completion_tokens','total_tokens','cost_nano_credits'],'reservation')$original$;
    IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='planner original charge receipt predecessor changed';END IF;
    d:=replace(d,needle,replacement);
    needle:=$later$l.body->'reservation'=to_jsonb(p)$later$;
    IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='planner later charge receipt predecessor changed';END IF;
    d:=replace(d,needle,$later$l.body->'reservation'=zasp_authorization80_worker.planner_receipt_row(l.body->'reservation',to_jsonb(p),'reservation')$later$);
   END IF;
   EXECUTE d;
  END LOOP;
 END LOOP;
END $portable_validators$;


INSERT INTO zasp_authorization80_worker.predecessor_functions
 SELECT oid::regprocedure::text,pg_get_functiondef(oid),proowner::regrole::text,COALESCE(proacl::text,'') FROM pg_proc
 WHERE oid IN('zasp_temporal74.inspect(jsonb)'::regprocedure,'zasp_temporal74.cleanup(jsonb)'::regprocedure);

-- Current runtime consumer module. The composing installer verifies the full
-- predecessor before reading source and binds the retained catalog handoff.
-- Source15 gives this table only authority-owned access and its one authority
-- policy. Reject inherited drift before registering the live permission facts.
-- Hold the table lock through registration so concurrent DDL cannot replace the
-- admitted baseline between this check and the catalog pin.
DO $stage_baseline$
BEGIN
 LOCK TABLE public.zasp_runtime_stage_work IN ACCESS EXCLUSIVE MODE;
 IF NOT EXISTS(
  SELECT 1 FROM pg_class c WHERE c.oid='public.zasp_runtime_stage_work'::regclass
  AND c.relkind='r' AND c.relowner='zasp_discovery_authority'::regrole
  AND c.relrowsecurity AND c.relforcerowsecurity
  AND NOT EXISTS(SELECT 1 FROM aclexplode(COALESCE(c.relacl,acldefault('r',c.relowner))) a WHERE a.grantee<>c.relowner OR a.grantor<>c.relowner)
  AND NOT EXISTS(SELECT 1 FROM pg_attribute a CROSS JOIN LATERAL aclexplode(a.attacl) p WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped AND(p.grantee<>c.relowner OR p.grantor<>c.relowner))
  AND (SELECT count(*)=1 FROM pg_policy p WHERE p.polrelid=c.oid)
  AND EXISTS(SELECT 1 FROM pg_policy p WHERE p.polrelid=c.oid
   AND p.polname='zasp_runtime_stage_work_authority' AND p.polpermissive AND p.polcmd='*'
   AND p.polroles=ARRAY['zasp_discovery_authority'::regrole::oid]
   AND pg_get_expr(p.polqual,p.polrelid)='true' AND pg_get_expr(p.polwithcheck,p.polrelid)='true')
 ) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime stage permission baseline rejected';END IF;
END $stage_baseline$;
CREATE SCHEMA zasp_authorization80_runtime AUTHORIZATION zasp_discovery_authority;
REVOKE ALL ON SCHEMA zasp_authorization80_runtime FROM PUBLIC;
CREATE TABLE zasp_authorization80_runtime.registration(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),checksum text NOT NULL,fingerprint text NOT NULL);
CREATE TABLE zasp_authorization80_runtime.predecessor_functions(signature text PRIMARY KEY,definition text NOT NULL,owner_name text NOT NULL,acl text NOT NULL);
DO $tables$ DECLARE n text;BEGIN
 FOREACH n IN ARRAY ARRAY['registration','predecessor_functions'] LOOP
  EXECUTE format('ALTER TABLE zasp_authorization80_runtime.%I OWNER TO zasp_discovery_authority',n);
  EXECUTE format('ALTER TABLE zasp_authorization80_runtime.%I ENABLE ROW LEVEL SECURITY',n);
  EXECUTE format('ALTER TABLE zasp_authorization80_runtime.%I FORCE ROW LEVEL SECURITY',n);
  EXECUTE format('CREATE POLICY authority ON zasp_authorization80_runtime.%I TO zasp_discovery_authority USING(true) WITH CHECK(true)',n);
  EXECUTE format('CREATE TRIGGER immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON zasp_authorization80_runtime.%I FOR EACH STATEMENT EXECUTE FUNCTION zasp_temporal67.immutable()',n);
 END LOOP;
END $tables$;


CREATE FUNCTION zasp_authorization80_worker.fingerprint() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $fingerprint$
 WITH facts(v) AS(
 SELECT concat_ws('|','schema',nspowner::regrole::text,nspacl::text) FROM pg_namespace WHERE nspname='zasp_authorization80_worker'
 UNION ALL SELECT concat_ws('|','function',p.oid::regprocedure::text,p.proowner::regrole::text,p.proacl::text,pg_get_functiondef(p.oid)) FROM pg_proc p WHERE p.pronamespace='zasp_authorization80_worker'::regnamespace OR p.oid IN(SELECT signature::regprocedure FROM zasp_authorization80_worker.predecessor_functions)
 UNION ALL SELECT concat_ws('|','table',c.relname,c.relkind,c.relowner::regrole::text,c.relacl::text,c.relrowsecurity,c.relforcerowsecurity) FROM pg_class c WHERE c.relnamespace='zasp_authorization80_worker'::regnamespace
 UNION ALL SELECT concat_ws('|','column',c.relname,a.attnum,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attacl::text,pg_get_expr(d.adbin,d.adrelid)) FROM pg_class c JOIN pg_attribute a ON a.attrelid=c.oid LEFT JOIN pg_attrdef d ON(d.adrelid,d.adnum)=(a.attrelid,a.attnum) WHERE c.relnamespace='zasp_authorization80_worker'::regnamespace AND a.attnum>0 AND NOT a.attisdropped
 UNION ALL SELECT concat_ws('|','constraint',c.relname,k.conname,pg_get_constraintdef(k.oid),k.convalidated) FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid WHERE c.relnamespace='zasp_authorization80_worker'::regnamespace
 UNION ALL SELECT concat_ws('|','policy',p.polrelid::regclass::text,p.polname,p.polpermissive,p.polcmd,p.polroles::regrole[]::text,pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid)) FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid WHERE c.relnamespace='zasp_authorization80_worker'::regnamespace
 UNION ALL SELECT concat_ws('|','trigger',t.tgrelid::regclass::text,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid)) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE NOT t.tgisinternal AND c.relnamespace='zasp_authorization80_worker'::regnamespace
 UNION ALL SELECT concat_ws('|','saved',signature,definition,owner_name,acl) FROM zasp_authorization80_worker.predecessor_functions
 UNION ALL SELECT concat_ws('|','saved-view',signature,definition) FROM zasp_authorization80_worker.predecessor_views
 UNION ALL SELECT 'runtime-catalog|'||(
 WITH facts(v) AS(
 SELECT concat_ws('|','schema',nspname,nspowner::regrole::text,nspacl::text) FROM pg_namespace WHERE nspname='zasp_authorization80_runtime'
 UNION ALL SELECT concat_ws('|','function',p.oid::regprocedure::text,p.proowner::regrole::text,p.proacl::text,pg_get_functiondef(p.oid)) FROM pg_proc p WHERE p.pronamespace='zasp_authorization80_runtime'::regnamespace OR p.oid IN(SELECT to_regprocedure(signature) FROM zasp_authorization80_runtime.predecessor_functions WHERE signature LIKE '%guard()') OR p.oid='public.zasp_runtime_finish_session_projection(text,text,text,text,bigint,text,text,integer,bytea,text,text,bytea,text,text,bytea,text,integer,bytea)'::regprocedure
 UNION ALL SELECT concat_ws('|','table',c.relname,c.relkind,c.relowner::regrole::text,c.relacl::text,c.relrowsecurity,c.relforcerowsecurity) FROM pg_class c WHERE c.relnamespace='zasp_authorization80_runtime'::regnamespace
 UNION ALL SELECT concat_ws('|','column',c.relname,a.attnum,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attacl::text,pg_get_expr(d.adbin,d.adrelid)) FROM pg_class c JOIN pg_attribute a ON a.attrelid=c.oid LEFT JOIN pg_attrdef d ON(d.adrelid,d.adnum)=(a.attrelid,a.attnum) WHERE c.relnamespace='zasp_authorization80_runtime'::regnamespace AND a.attnum>0 AND NOT a.attisdropped
 UNION ALL SELECT concat_ws('|','constraint',c.relname,k.conname,pg_get_constraintdef(k.oid),k.convalidated) FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid WHERE c.relnamespace='zasp_authorization80_runtime'::regnamespace
 UNION ALL SELECT concat_ws('|','index',c.relname,pg_get_indexdef(i.indexrelid),i.indisvalid,i.indisready,i.indislive) FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid WHERE c.relnamespace='zasp_authorization80_runtime'::regnamespace
 UNION ALL SELECT concat_ws('|','policy',p.polrelid::regclass::text,p.polname,p.polpermissive,p.polcmd,p.polroles::regrole[]::text,pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid)) FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid WHERE c.relnamespace='zasp_authorization80_runtime'::regnamespace
 UNION ALL SELECT concat_ws('|','trigger',t.tgrelid::regclass::text,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid)) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE NOT t.tgisinternal AND(c.relnamespace='zasp_authorization80_runtime'::regnamespace OR t.tgfoid IN(SELECT to_regprocedure(signature) FROM zasp_authorization80_runtime.predecessor_functions WHERE signature LIKE '%guard()'))
 UNION ALL SELECT concat_ws('|','stage-insert-trigger',t.tgrelid::regclass::text,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid),pg_get_functiondef(p.oid),p.proowner::regrole::text,p.proacl::text) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE t.tgrelid='public.zasp_runtime_stage_work'::regclass AND t.tgname='zasp_authorization80_runtime_stage_insert'
 UNION ALL SELECT concat_ws('|','stage-table',c.oid::regclass::text,c.relkind,c.relowner::regrole::text,c.relacl::text,c.relrowsecurity,c.relforcerowsecurity) FROM pg_class c WHERE c.oid='public.zasp_runtime_stage_work'::regclass
 UNION ALL SELECT concat_ws('|','stage-column-acl',a.attnum,a.attname,a.attacl::text) FROM pg_attribute a WHERE a.attrelid='public.zasp_runtime_stage_work'::regclass AND a.attnum>0 AND NOT a.attisdropped
 UNION ALL SELECT concat_ws('|','stage-policy',p.polname,p.polpermissive,p.polcmd,p.polroles::regrole[]::text,pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid)) FROM pg_policy p WHERE p.polrelid='public.zasp_runtime_stage_work'::regclass
 UNION ALL SELECT concat_ws('|','saved',signature,definition,owner_name,acl) FROM zasp_authorization80_runtime.predecessor_functions
 ) SELECT encode(digest(convert_to(string_agg(v,E'\n' ORDER BY v),'UTF8'),'sha256'),'hex') FROM facts

 )
 UNION ALL SELECT concat_ws('|','runtime-registration',singleton,checksum,fingerprint) FROM zasp_authorization80_runtime.registration
 UNION ALL SELECT concat_ws('|','runtime-stage-insert-trigger',t.tgrelid::regclass::text,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid),pg_get_functiondef(p.oid),p.proowner::regrole::text,p.proacl::text) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE t.tgrelid='public.zasp_runtime_stage_work'::regclass AND t.tgname='zasp_authorization80_runtime_stage_insert'
 UNION ALL SELECT concat_ws('|','runtime-source-trigger',t.tgrelid::regclass::text,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid),pg_get_functiondef(p.oid),p.proowner::regrole::text,p.proacl::text) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE t.tgrelid IN('public.zasp_gateway_devices'::regclass,'public.zasp_gateway_credentials'::regclass,'public.zasp_runtime_session_summaries'::regclass,'public.zasp_runtime_gateway_events'::regclass,'zasp_temporal77.runtime_evaluations'::regclass,'zasp_temporal77.source_events'::regclass) AND t.tgname IN('zasp_authorization80_worker_runtime_capture','zasp_authorization80_worker_runtime_no_truncate')
 UNION ALL SELECT concat_ws('|','changed-view',c.oid::regclass::text,c.relowner::regrole::text,c.relacl::text,pg_get_viewdef(c.oid)) FROM pg_class c WHERE c.oid IN(SELECT signature::regclass FROM zasp_authorization80_worker.predecessor_views)
 UNION ALL SELECT concat_ws('|','private-view',c.oid::regclass::text,pg_get_viewdef(c.oid)) FROM pg_class c WHERE c.relnamespace='zasp_authorization80_worker'::regnamespace AND c.relkind='v'
 UNION ALL SELECT concat_ws('|','run-capture-trigger',t.tgname,t.tgenabled,pg_get_triggerdef(t.oid)) FROM pg_trigger t WHERE t.tgrelid='public.zasp_security_agent_runs'::regclass AND t.tgname IN('zasp_authorization80_worker_run_capture','zasp_authorization80_worker_no_truncate')
 UNION ALL SELECT concat_ws('|','source-capture-trigger',t.tgrelid::regclass::text,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid)) FROM pg_trigger t WHERE t.tgrelid IN('public.zasp_risk_findings'::regclass,'public.zasp_security_agent_definitions'::regclass) AND t.tgname='zasp_authorization80_worker_source_capture'
