CREATE FUNCTION zasp_authorization80_worker.capture_grant_revocation(o text,w text,e text,d text,v bigint) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $grant_capture$
 INSERT INTO zasp_authorization80_worker.revocations(organization_id,workspace_id,environment_id,run_id)
 SELECT organization_id,workspace_id,environment_id,run_id FROM zasp_authorization80_worker.associations WHERE(organization_id,workspace_id,environment_id,definition_id,definition_version)=(o,w,e,d,v) ON CONFLICT DO NOTHING
$grant_capture$;

CREATE VIEW zasp_authorization80_worker.active_associations AS
 SELECT a.* FROM zasp_authorization80_worker.associations a JOIN zasp_authorization80_worker.run_state r USING(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version)
 JOIN public.zasp_security_agent_definitions d ON(d.organization_id,d.workspace_id,d.environment_id,d.definition_id,d.version)=(a.organization_id,a.workspace_id,a.environment_id,a.definition_id,a.definition_version)
 JOIN public.zasp_identity_memberships m ON(m.organization_id,m.principal_id)=(a.organization_id,a.grantor_id)
 WHERE r.present AND r.state IN('queued','planning','waiting_approval','running','verifying') AND m.active AND d.deleted_at IS NULL AND d.activation IN('supervised','autonomous') AND d.body->'enabled'='true'::jsonb
 AND NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.revocations v WHERE(v.organization_id,v.workspace_id,v.environment_id,v.run_id)=(a.organization_id,a.workspace_id,a.environment_id,a.run_id))
 AND NOT EXISTS(SELECT 1 FROM zasp_temporal78.grant_revocations v WHERE(v.organization_id,v.workspace_id,v.environment_id,v.definition_id,v.definition_version)=(a.organization_id,a.workspace_id,a.environment_id,a.definition_id,a.definition_version));
ALTER VIEW zasp_authorization80_worker.active_associations OWNER TO zasp_discovery_authority;
DO $views$ DECLARE d text;BEGIN
 SELECT definition INTO STRICT d FROM zasp_authorization80_worker.predecessor_views WHERE signature='zasp_authorization79.members';
 EXECUTE 'CREATE OR REPLACE VIEW zasp_authorization79.members AS '||rtrim(d,E';\n ')||' UNION SELECT organization_id,''service''::text,principal_id,''''::text FROM zasp_authorization80_worker.active_associations';
 SELECT definition INTO STRICT d FROM zasp_authorization80_worker.predecessor_views WHERE signature='zasp_authorization79.current_grants';
 EXECUTE 'CREATE OR REPLACE VIEW zasp_authorization79.current_grants AS '||rtrim(d,E';\n ')||$grant$ UNION SELECT a.organization_id,a.workspace_id,a.environment_id,t.kind,t.id,'service'::text,a.principal_id,t.permission,a.run_id FROM zasp_authorization80_worker.active_associations a CROSS JOIN LATERAL(VALUES('finding'::text,a.finding_id,'manage_findings'::text),('finding',a.finding_id,'view'),('security_agent',a.definition_id,'manage_workflows'),('security_agent_run',a.run_id,'manage_workflows')) t(kind,id,permission)$grant$;
 SELECT definition INTO STRICT d FROM zasp_authorization80_worker.predecessor_views WHERE signature='zasp_authorization79.resources';
 EXECUTE 'CREATE OR REPLACE VIEW zasp_authorization79.resources AS '||rtrim(d,E';\n ')||' UNION SELECT organization_id,workspace_id,environment_id,''security_agent_run''::text,run_id FROM zasp_authorization80_worker.run_state WHERE present';
END $views$;


-- The native owner supplies the canonical source and request digest. No body,
-- context or provider response is copied into metadata or the signed proof.
CREATE FUNCTION zasp_authorization80_worker.planning78_source(phase text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $planning_source$
DECLARE x zasp_temporal78.run_owners%ROWTYPE;j zasp_temporal78.planning_jobs%ROWTYPE;reference_value jsonb;f jsonb;compensation boolean:=phase IN('reconcile','late_usage','recovery');
BEGIN
 IF phase IS NULL OR phase NOT IN('state','load','prepare','start','result','settle','artifacts','admit','reconcile','late_usage','recovery') OR octet_length(q::text)>524288
 OR phase='state' AND NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version'])
 OR phase<>'state' AND(q->>'operation' IS DISTINCT FROM phase OR NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','operation']||CASE WHEN phase IN('load','recovery') THEN ARRAY[]::text[] ELSE ARRAY['payload'] END)) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker planning request rejected';END IF;
 SELECT * INTO x FROM zasp_temporal78.run_owners WHERE(organization_id,workspace_id,environment_id,run_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id') AND to_jsonb(definition_version)=q->'definition_version';
 IF x.run_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker planning owner changed';END IF;
 reference_value:=jsonb_build_object('organization_id',x.organization_id,'workspace_id',x.workspace_id,'environment_id',x.environment_id,'run_id',x.run_id,'definition_version',x.definition_version,'input_digest',x.input_digest);
 IF compensation THEN reference_value:=reference_value||jsonb_build_object('reason','workflow_failed');END IF;
 f:=zasp_authorization80_worker.finding_source(CASE WHEN compensation THEN 'finding.cleanup' ELSE 'finding.planning' END,reference_value);
 SELECT * INTO j FROM zasp_temporal78.planning_jobs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id) FOR SHARE;
 IF compensation AND(j.run_id IS NULL OR j.state NOT IN('loaded','prepared','started','completed','settled','artifacts','needs_human')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker captured planning unavailable';END IF;
 RETURN f||jsonb_build_object('planning_phase',phase,'request_digest',encode(digest(convert_to(q::text,'UTF8'),'sha256'),'hex'),'job_digest',zasp_authorization80_worker.planner_job_digest(to_jsonb(j)));
END $planning_source$;

CREATE FUNCTION zasp_authorization80_worker.require_planning78(phase text,q jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $planning_require$
DECLARE envelope json;body_bytes bytea;proof jsonb;source_value jsonb;k bytea;purpose_value text;now_ms bigint:=floor(extract(epoch FROM clock_timestamp())*1000)::bigint;revision_value zasp_authorization79.organizations%ROWTYPE;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='worker planning requires read committed';END IF;
 IF phase IS NULL OR phase NOT IN('state','load','prepare','start','result','settle','artifacts','admit','reconcile','late_usage','recovery') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker planning phase rejected';END IF;
 purpose_value:=CASE WHEN phase IN('reconcile','late_usage','recovery') THEN 'captured-compensation' ELSE 'worker-forward' END;
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.principal_ready(CASE purpose_value WHEN 'worker-forward' THEN 'zasp_temporal_executor' ELSE 'zasp_temporal_compensation' END) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker planning role rejected';END IF;
 envelope:=NULLIF(current_setting('zasp.worker_proof',true),'')::json;
 IF envelope IS NULL OR octet_length(envelope::text)>65536 OR json_typeof(envelope)<>'object' OR NOT zasp_authorization80.unique_json(envelope) OR(SELECT count(*) FROM json_each(envelope))<>3 OR EXISTS(SELECT 1 FROM json_each(envelope) WHERE key NOT IN('body','version','mac') OR json_typeof(value)<>'string') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker proof rejected';END IF;
 SELECT key INTO k FROM zasp_authorization80_worker.verifiers WHERE purpose=purpose_value AND version=envelope->>'version' FOR SHARE;
 body_bytes:=decode(envelope->>'body','base64');
 IF k IS NULL OR octet_length(body_bytes) NOT BETWEEN 1 AND 32768 OR envelope->>'mac' IS DISTINCT FROM encode(hmac(convert_to('zasp-authorization-'||purpose_value||'-v1','UTF8')||decode('00','hex')||body_bytes,k,'sha256'),'hex') OR NOT zasp_authorization80.unique_json(convert_from(body_bytes,'UTF8')::json) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker proof rejected';END IF;
 proof:=convert_from(body_bytes,'UTF8')::jsonb;
 IF NOT COALESCE(proof->>'purpose'=purpose_value AND proof->>'key_version'=envelope->>'version' AND proof->>'operation'='finding.planning.'||phase AND proof->'request'='null'::jsonb AND proof->>'session_user'=session_user AND(proof->>'issued_at')::bigint<=now_ms+5000 AND(proof->>'expires_at')::bigint>now_ms AND(proof->>'expires_at')::bigint-(proof->>'issued_at')::bigint BETWEEN 1 AND 60000,false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker planning proof binding rejected';END IF;
 SELECT * INTO revision_value FROM zasp_authorization79.organizations WHERE organization_id=q->>'organization_id' FOR UPDATE;
 IF revision_value.organization_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker captured organization missing';END IF;
 IF purpose_value='worker-forward' THEN
  IF revision_value.desired<>revision_value.applied OR proof->'revision' IS DISTINCT FROM jsonb_build_object('organization_id',revision_value.organization_id,'desired',revision_value.desired,'applied',revision_value.applied,'generation',revision_value.generation,'store_id',revision_value.store_id,'model_id',revision_value.model_id) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker authorization revision changed';END IF;
 END IF;
 source_value:=zasp_authorization80_worker.planning78_source(phase,q);
 now_ms:=floor(extract(epoch FROM clock_timestamp())*1000)::bigint;
 IF NOT COALESCE((proof->>'issued_at')::bigint<=now_ms+5000 AND(proof->>'expires_at')::bigint>now_ms AND(proof->>'expires_at')::bigint-(proof->>'issued_at')::bigint BETWEEN 1 AND 60000,false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker proof expired after source locks';END IF;
 IF proof->'facts' IS DISTINCT FROM source_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker planning source changed';END IF;
EXCEPTION WHEN data_exception THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker proof rejected';
END $planning_require$;

CREATE FUNCTION zasp_authorization80_worker.planning78_recovery_result(j jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public AS $recovery_result$
 SELECT jsonb_build_object('run_id',j->'run_id','state',j->'state','reservation_id',j->'reservation_id','request_digest',j->'request_digest','credential_digest',j#>'{lookup_request,credential_digest}','usage_known',j->'result_value'->'usage' IS NOT NULL AND j->'result_value'->'usage'<>'null'::jsonb,'has_response',j->'raw_result' IS NOT NULL AND j->'raw_result'<>'null'::jsonb)
$recovery_result$;

CREATE FUNCTION zasp_authorization80_worker.planning78_recovery(q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $recovery$
DECLARE j zasp_temporal78.planning_jobs%ROWTYPE;BEGIN
 PERFORM zasp_authorization80_worker.require_planning78('recovery',q);
 SELECT * INTO STRICT j FROM zasp_temporal78.planning_jobs WHERE(organization_id,workspace_id,environment_id,run_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id');
 RETURN zasp_authorization80_worker.planning78_recovery_result(to_jsonb(j));
END $recovery$;


-- Test-family metadata is captured only from the real74 owner/context/target.
-- It contains identifiers and hashes, never endpoint or credential references.
CREATE TABLE zasp_authorization80_worker.test_associations(
 organization_id text NOT NULL,workspace_id text NOT NULL,environment_id text NOT NULL,run_id text NOT NULL,
 principal_id text NOT NULL,grantor_id text NOT NULL,definition_id text NOT NULL,definition_version bigint NOT NULL,definition_digest text NOT NULL CHECK(definition_digest~'^[a-f0-9]{64}$'),
 source_digest text NOT NULL,test_id text NOT NULL,test_version bigint NOT NULL,target_id text NOT NULL,target_kind text NOT NULL CHECK(target_kind IN('agent','tool')),
 native_target_kind text NOT NULL,target_digest text NOT NULL,trigger_kind text NOT NULL,trigger_id text NOT NULL,
 snapshot_id text NOT NULL,evidence_id text NOT NULL,integration_id text NOT NULL,source text NOT NULL,credential_binding_id text NOT NULL,
 PRIMARY KEY(organization_id,workspace_id,environment_id,run_id));
CREATE TABLE zasp_authorization80_worker.test_state(
 organization_id text NOT NULL,workspace_id text NOT NULL,environment_id text NOT NULL,run_id text NOT NULL,
 definition_id text NOT NULL,definition_version bigint NOT NULL,state text NOT NULL,run_version bigint NOT NULL,present boolean NOT NULL,
 target_current boolean NOT NULL,fresh_until timestamptz NOT NULL,
 PRIMARY KEY(organization_id,workspace_id,environment_id,run_id),
 FOREIGN KEY(organization_id,workspace_id,environment_id,run_id) REFERENCES zasp_authorization80_worker.test_associations);
DO $test_tables$ DECLARE n text;BEGIN
 FOREACH n IN ARRAY ARRAY['test_associations','test_state'] LOOP
  EXECUTE format('ALTER TABLE zasp_authorization80_worker.%I OWNER TO zasp_discovery_authority',n);
  EXECUTE format('ALTER TABLE zasp_authorization80_worker.%I ENABLE ROW LEVEL SECURITY',n);
  EXECUTE format('ALTER TABLE zasp_authorization80_worker.%I FORCE ROW LEVEL SECURITY',n);
  EXECUTE format('CREATE POLICY authority ON zasp_authorization80_worker.%I TO zasp_discovery_authority USING(true) WITH CHECK(true)',n);
 END LOOP;
END $test_tables$;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON zasp_authorization80_worker.test_associations FOR EACH STATEMENT EXECUTE FUNCTION zasp_temporal67.immutable();
CREATE TRIGGER no_truncate BEFORE TRUNCATE ON zasp_authorization80_worker.test_state FOR EACH STATEMENT EXECUTE FUNCTION zasp_temporal67.immutable();
CREATE TRIGGER worker_revision AFTER INSERT ON zasp_authorization80_worker.test_associations FOR EACH ROW EXECUTE FUNCTION zasp_authorization79.capture('organization_id','organization_id,workspace_id,environment_id,run_id');
CREATE TRIGGER worker_revision AFTER INSERT OR UPDATE OR DELETE ON zasp_authorization80_worker.test_state FOR EACH ROW EXECUTE FUNCTION zasp_authorization79.capture('organization_id','organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,state,run_version,present,target_current,fresh_until');

CREATE FUNCTION zasp_authorization80_worker.test74_private_facts(compensation boolean,q jsonb,execution boolean,parent_value jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $test_facts$
DECLARE x zasp_temporal74.run_owners%ROWTYPE;r public.zasp_security_agent_runs%ROWTYPE;a zasp_authorization80_worker.test_associations%ROWTYPE;g zasp_temporal74.service_grants%ROWTYPE;
 binding jsonb;resolution jsonb;principal_value text;grantor text;definition_hash text;source_hash text;target_hash text;trigger_value text;product text;expires timestamptz;checks jsonb;metadata jsonb;
BEGIN
 IF compensation IS NULL OR execution IS NULL OR NOT zasp_temporal74.current_ready() OR NOT zasp_authorization80_worker.catalog_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker test source reader rejected';END IF;
 IF parent_value IS NULL THEN
  IF NOT zasp_temporal68.principal_ready(CASE WHEN compensation THEN 'zasp_temporal_compensation' ELSE 'zasp_temporal_executor' END) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker test source role rejected';END IF;
 ELSIF compensation OR NOT execution OR NOT zasp_temporal68.adapter_principal_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker adapter source role rejected';END IF;
 x:=zasp_temporal74.start_identity(q);
 IF parent_value IS NULL THEN
  SELECT * INTO STRICT r FROM public.zasp_security_agent_runs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id) FOR SHARE;
 ELSE
  r:=jsonb_populate_record(NULL::public.zasp_security_agent_runs,parent_value);
  IF(r.organization_id,r.workspace_id,r.environment_id,r.run_id) IS DISTINCT FROM(x.organization_id,x.workspace_id,x.environment_id,x.run_id) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker adapter parent rejected';END IF;
 END IF;
 SELECT encode(definition_digest,'hex') INTO STRICT definition_hash FROM public.zasp_security_agent_definition_versions WHERE(organization_id,workspace_id,environment_id,definition_id,version)=(x.organization_id,x.workspace_id,x.environment_id,x.definition_id,x.definition_version) FOR SHARE;
 source_hash:=encode(digest(convert_to(jsonb_build_array(x.source_kind,x.definition_id,x.definition_version,definition_hash,x.input_digest,x.trigger_id,x.trigger_version,x.action_key,x.step_id,x.test_run_id)::text,'UTF8'),'sha256'),'hex');
 SELECT * INTO a FROM zasp_authorization80_worker.test_associations WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
 IF compensation THEN
  IF a.run_id IS NULL OR(a.definition_id,a.definition_version,a.definition_digest,a.source_digest) IS DISTINCT FROM(x.definition_id,x.definition_version,definition_hash,source_hash)
   OR NOT execution AND NOT EXISTS(SELECT 1 FROM zasp_temporal74.planning_jobs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker captured test planning unavailable';END IF;
  metadata:=to_jsonb(a);checks:='[]'::jsonb;
 ELSE
  IF execution AND r.state NOT IN('queued','running') OR NOT execution AND r.state NOT IN('queued','planning','waiting_approval') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker test task inactive';END IF;
  IF parent_value IS NULL THEN PERFORM zasp_temporal74.context(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
  ELSE PERFORM zasp_temporal74.context_parent(x.organization_id,x.workspace_id,x.environment_id,x.run_id,parent_value);END IF;
  principal_value:=public.zasp_discovery_canonical_id(x.organization_id,x.workspace_id,x.environment_id,'security_agent_definition_service',x.definition_id);
  grantor:=r.requested_by;
  IF x.source_kind='automatic73' THEN
   SELECT * INTO STRICT g FROM zasp_temporal74.service_grants WHERE(organization_id,workspace_id,environment_id,definition_id,definition_version)=(x.organization_id,x.workspace_id,x.environment_id,x.definition_id,x.definition_version) FOR SHARE;
   principal_value:=g.principal_id;grantor:=g.grantor_id;
  END IF;
  binding:=zasp_temporal71.body21(x.organization_id,x.workspace_id,x.environment_id,x.definition_id,x.definition_version);
  resolution:=zasp_temporal74.test_target(x.organization_id,x.workspace_id,x.environment_id,binding->>'target_id',binding->>'target_kind',binding->>'definition_id',(binding->>'definition_version')::bigint);
  target_hash:=encode(digest(convert_to(resolution::text,'UTF8'),'sha256'),'hex');
  SELECT i.product_kind,least(i.fresh_until,c.valid_until) INTO STRICT product,expires FROM public.zasp_inventory_entities i JOIN public.zasp_attack_lab_credential_bindings c ON(c.organization_id,c.workspace_id,c.environment_id,c.binding_id)=(i.organization_id,i.workspace_id,i.environment_id,resolution#>>'{comparison,credential_binding_id}') WHERE(i.organization_id,i.workspace_id,i.environment_id,i.id)=(x.organization_id,x.workspace_id,x.environment_id,binding->>'target_id') FOR SHARE OF i,c;
  SELECT trigger_kind INTO STRICT trigger_value FROM public.zasp_security_agent_trigger_receipts WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
  IF product NOT IN('agent','tool') OR trigger_value NOT IN('manual','finding','attack_path','runtime_decision') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker test target kind rejected';END IF;
  -- Runtime-decision parent mapping remains unsupported until its exact device
  -- ancestry is implemented. A source kind can never reduce the Check set.
  IF trigger_value='runtime_decision' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker test trigger unsupported';END IF;
  metadata:=jsonb_build_object('organization_id',x.organization_id,'workspace_id',x.workspace_id,'environment_id',x.environment_id,'run_id',x.run_id,'principal_id',principal_value,'grantor_id',grantor,'definition_id',x.definition_id,'definition_version',x.definition_version,'definition_digest',definition_hash,'source_digest',source_hash,
   'test_id',binding->>'definition_id','test_version',binding->'definition_version','target_id',binding->>'target_id','target_kind',product,'native_target_kind',binding->>'target_kind','target_digest',target_hash,'trigger_kind',trigger_value,'trigger_id',x.trigger_id,
   'snapshot_id',resolution#>>'{provenance,snapshot_id}','evidence_id',resolution#>>'{provenance,evidence_id}','integration_id',resolution#>>'{provenance,integration_id}','source',resolution#>>'{provenance,source}','credential_binding_id',resolution#>>'{comparison,credential_binding_id}');
  checks:=jsonb_build_array(jsonb_build_object('kind','security_agent','id',x.definition_id,'permission','manage_workflows'),jsonb_build_object('kind','security_agent_run','id',x.run_id,'permission','manage_workflows'),jsonb_build_object('kind','test','id',binding->>'definition_id','permission','view'),jsonb_build_object('kind',product,'id',binding->>'target_id','permission','view'));
  IF execution THEN
   checks:=jsonb_build_array(checks->0,checks->1,jsonb_build_object('kind','test','id',binding->>'definition_id','permission','run_tests'),jsonb_build_object('kind',product,'id',binding->>'target_id','permission','run_tests'));
  ELSIF trigger_value IN('finding','attack_path') THEN checks:=checks||jsonb_build_array(jsonb_build_object('kind',trigger_value,'id',x.trigger_id,'permission','view'));END IF;
 END IF;
 RETURN metadata||jsonb_build_object('run_state',r.state,'run_version',r.version,'checks',checks,'session_user',session_user,'fresh_until_ms',CASE WHEN compensation THEN NULL ELSE floor(extract(epoch FROM expires)*1000)::bigint END);
END $test_facts$;

CREATE FUNCTION zasp_authorization80_worker.test74_native_facts(compensation boolean,q jsonb,execution boolean) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $native_facts$
 SELECT zasp_authorization80_worker.test74_private_facts(compensation,q,execution,NULL)
$native_facts$;

CREATE FUNCTION zasp_authorization80_worker.test74_facts(compensation boolean,q jsonb) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $planning_facts$
 SELECT zasp_authorization80_worker.test74_native_facts(compensation,q,false)
$planning_facts$;

CREATE FUNCTION zasp_authorization80_worker.prepare_test74(q jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $test_prepare$
DECLARE f jsonb;a zasp_authorization80_worker.test_associations%ROWTYPE;BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='worker preparation requires read committed';END IF;
 f:=zasp_authorization80_worker.test74_facts(false,q);
 a:=jsonb_populate_record(NULL::zasp_authorization80_worker.test_associations,f);
 INSERT INTO zasp_authorization80_worker.test_associations SELECT a.* ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.test_associations s WHERE s=a) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker test association changed';END IF;
 INSERT INTO zasp_authorization80_worker.test_state VALUES(a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.definition_id,a.definition_version,f->>'run_state',(f->>'run_version')::bigint,true,true,to_timestamp((f->>'fresh_until_ms')::numeric/1000)) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.test_state s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.definition_id,s.definition_version,s.state,s.run_version,s.present,s.target_current)=(a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.definition_id,a.definition_version,f->>'run_state',(f->>'run_version')::bigint,true,true) AND s.fresh_until>clock_timestamp()) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker test capture changed';END IF;
END $test_prepare$;

CREATE FUNCTION zasp_authorization80_worker.test74_source(compensation boolean,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $test_source$
DECLARE f jsonb;a zasp_authorization80_worker.test_associations%ROWTYPE;BEGIN
 f:=zasp_authorization80_worker.test74_facts(compensation,q);a:=jsonb_populate_record(NULL::zasp_authorization80_worker.test_associations,f);
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.test_associations s WHERE s=a) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker test association missing';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.test_state s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.definition_id,s.definition_version,s.state,s.run_version,s.present)=(a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.definition_id,a.definition_version,f->>'run_state',(f->>'run_version')::bigint,true) AND(compensation OR s.target_current AND s.fresh_until>clock_timestamp())) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker test capture changed';END IF;
 RETURN f;
END $test_source$;

CREATE FUNCTION zasp_authorization80_worker.capture_test_target() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $target_capture$
DECLARE old_value jsonb:=to_jsonb(OLD);BEGIN
 IF TG_OP='UPDATE' AND old_value=to_jsonb(NEW) THEN RETURN NEW;END IF;
 UPDATE zasp_authorization80_worker.test_state s SET target_current=false
 FROM zasp_authorization80_worker.test_associations a
 WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id)=(a.organization_id,a.workspace_id,a.environment_id,a.run_id) AND s.target_current
 AND(a.organization_id,a.workspace_id,a.environment_id)=(old_value->>'organization_id',old_value->>'workspace_id',old_value->>'environment_id')
 AND CASE TG_TABLE_NAME
  WHEN 'zasp_red_team_definitions' THEN a.test_id=old_value->>'definition_id'
  WHEN 'zasp_inventory_entities' THEN a.target_id=old_value->>'id'
  WHEN 'zasp_inventory_evidence' THEN a.evidence_id=old_value->>'id'
  WHEN 'zasp_discovery_snapshots' THEN a.snapshot_id=old_value->>'id'
  WHEN 'zasp_inventory_source_observations' THEN(a.target_id,a.integration_id,a.source,a.snapshot_id,a.evidence_id)=(old_value->>'entity_id',old_value->>'integration_id',old_value->>'source',old_value->>'snapshot_id',old_value->>'evidence_id')
  WHEN 'zasp_attack_lab_credential_bindings' THEN a.credential_binding_id=old_value->>'binding_id'
  ELSE false END;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $target_capture$;
DO $target_triggers$ DECLARE n text;BEGIN
 FOREACH n IN ARRAY ARRAY['zasp_red_team_definitions','zasp_inventory_entities','zasp_inventory_evidence','zasp_discovery_snapshots','zasp_inventory_source_observations','zasp_attack_lab_credential_bindings'] LOOP
  EXECUTE format('CREATE TRIGGER zasp_authorization80_worker_target_capture BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION zasp_authorization80_worker.capture_test_target()',n);
  EXECUTE format('CREATE TRIGGER zasp_authorization80_worker_target_no_truncate BEFORE TRUNCATE ON public.%I FOR EACH STATEMENT EXECUTE FUNCTION zasp_temporal67.immutable()',n);
 END LOOP;
END $target_triggers$;
CREATE FUNCTION zasp_authorization80_worker.expire_test_targets(o text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $expiry$
BEGIN
 IF NOT zasp_authorization79.worker() OR NOT zasp_authorization79.locked(o) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker expiry session rejected';END IF;
 UPDATE zasp_authorization80_worker.test_state SET target_current=false WHERE organization_id=o AND target_current AND fresh_until<=clock_timestamp();
END $expiry$;
CREATE FUNCTION zasp_authorization80_worker.capture_test_revocation(o text,w text,e text,d text,v bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $test_revocation$
BEGIN
 IF EXISTS(SELECT 1 FROM zasp_authorization80_worker.test_associations WHERE(organization_id,workspace_id,environment_id,definition_id,definition_version)=(o,w,e,d,v)) THEN PERFORM zasp_authorization79.touch(o);END IF;
END $test_revocation$;

CREATE VIEW zasp_authorization80_worker.active_tests AS
 SELECT a.* FROM zasp_authorization80_worker.test_associations a JOIN zasp_authorization80_worker.test_state s USING(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version)
 JOIN public.zasp_security_agent_definitions d ON(d.organization_id,d.workspace_id,d.environment_id,d.definition_id,d.version)=(a.organization_id,a.workspace_id,a.environment_id,a.definition_id,a.definition_version)
 JOIN public.zasp_identity_memberships m ON(m.organization_id,m.principal_id)=(a.organization_id,a.grantor_id)
 WHERE s.present AND s.target_current AND s.fresh_until>clock_timestamp() AND s.state IN('queued','planning','waiting_approval','running','verifying') AND m.active AND d.deleted_at IS NULL AND d.activation IN('supervised','autonomous') AND d.body->'enabled'='true'::jsonb
 AND NOT EXISTS(SELECT 1 FROM zasp_temporal74.grant_revocations v WHERE(v.organization_id,v.workspace_id,v.environment_id,v.definition_id,v.definition_version)=(a.organization_id,a.workspace_id,a.environment_id,a.definition_id,a.definition_version));
ALTER VIEW zasp_authorization80_worker.active_tests OWNER TO zasp_discovery_authority;
DO $test_views$ DECLARE d text;BEGIN
 SELECT pg_get_viewdef('zasp_authorization79.members'::regclass) INTO d;
 EXECUTE 'CREATE OR REPLACE VIEW zasp_authorization79.members AS '||rtrim(d,E';\n ')||' UNION SELECT organization_id,''service''::text,principal_id,''''::text FROM zasp_authorization80_worker.active_tests';
 SELECT pg_get_viewdef('zasp_authorization79.current_grants'::regclass) INTO d;
 EXECUTE 'CREATE OR REPLACE VIEW zasp_authorization79.current_grants AS '||rtrim(d,E';\n ')||$grant$ UNION SELECT a.organization_id,a.workspace_id,a.environment_id,t.kind,t.id,'service'::text,a.principal_id,t.permission,a.run_id FROM zasp_authorization80_worker.active_tests a CROSS JOIN LATERAL(VALUES('security_agent'::text,a.definition_id,'manage_workflows'::text),('security_agent_run',a.run_id,'manage_workflows'),('test',a.test_id,'view'),(a.target_kind,a.target_id,'view'),('test',a.test_id,'run_tests'),(a.target_kind,a.target_id,'run_tests')) t(kind,id,permission)
 UNION SELECT organization_id,workspace_id,environment_id,trigger_kind,trigger_id,'service'::text,principal_id,'view'::text,run_id FROM zasp_authorization80_worker.active_tests WHERE trigger_kind IN('finding','attack_path')$grant$;
 SELECT pg_get_viewdef('zasp_authorization79.resources'::regclass) INTO d;
 EXECUTE 'CREATE OR REPLACE VIEW zasp_authorization79.resources AS '||rtrim(d,E';\n ')||' UNION SELECT organization_id,workspace_id,environment_id,''security_agent_run''::text,run_id FROM zasp_authorization80_worker.test_state WHERE present';
END $test_views$;

-- Copy the already-defined closed planning proof protocol, substituting only
-- family/source identities. No native context or body is exposed by metadata.
DO $test_planning$ DECLARE d text;n text;needle text;BEGIN
 FOREACH n IN ARRAY ARRAY['planning78_source','require_planning78','planning78_recovery_result','planning78_recovery'] LOOP
  SELECT pg_get_functiondef(oid) INTO STRICT d FROM pg_proc WHERE pronamespace='zasp_authorization80_worker'::regnamespace AND proname=n;
  d:=replace(replace(replace(d,'planning78','planning74'),'zasp_temporal78.','zasp_temporal74.'),'finding.planning.','test74.planning.');
  IF n='planning78_source' THEN
   needle:=$old$ IF compensation THEN reference_value:=reference_value||jsonb_build_object('reason','workflow_failed');END IF;
 f:=zasp_authorization80_worker.finding_source(CASE WHEN compensation THEN 'finding.cleanup' ELSE 'finding.planning' END,reference_value);$old$;
   IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker test planning protocol changed';END IF;
   d:=replace(d,needle,' f:=zasp_authorization80_worker.test74_source(compensation,reference_value);');
  END IF;
  EXECUTE d;
 END LOOP;
END $test_planning$;


-- Each execution phase binds canonical request bytes and the captured native
-- plan/step/effect/input identities. Bodies never enter the metadata response.
CREATE FUNCTION zasp_authorization80_worker.test74_effect_source(phase text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $effect_source$
DECLARE x zasp_temporal74.run_owners%ROWTYPE;a zasp_authorization80_worker.test_associations%ROWTYPE;f jsonb;reference_value jsonb;effect_value jsonb;input_value jsonb;step_value jsonb;
 compensation boolean:=phase IN('effect.read','effect.unknown','state');
BEGIN
 IF phase IS NULL OR phase NOT IN('effect.reserve','effect.start','effect.read','effect.unknown','linked.read','linked.input','linked.dispatch','state')
 OR octet_length(q::text)>131072 OR NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload'])
 OR q->'generation' IS DISTINCT FROM '1'::jsonb OR jsonb_typeof(q->'payload') IS DISTINCT FROM 'object'
 OR q->>'operation' IS DISTINCT FROM (CASE WHEN phase='state' THEN 'read' ELSE split_part(phase,'.',2) END) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker test execution request rejected';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 SELECT * INTO x FROM zasp_temporal74.run_owners WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id');
 IF x.run_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker test execution owner rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||x.organization_id,0));
 reference_value:=jsonb_build_object('organization_id',x.organization_id,'workspace_id',x.workspace_id,'environment_id',x.environment_id,'run_id',x.run_id,'definition_version',x.definition_version,'input_digest',x.input_digest);
 f:=zasp_authorization80_worker.test74_native_facts(compensation,reference_value,true);
 a:=jsonb_populate_record(NULL::zasp_authorization80_worker.test_associations,f);
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.test_associations s WHERE s=a) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker test execution association rejected';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.test_state s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.definition_id,s.definition_version,s.state,s.run_version,s.present)=(a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.definition_id,a.definition_version,f->>'run_state',(f->>'run_version')::bigint,true) AND(compensation OR s.target_current AND s.fresh_until>clock_timestamp())) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker test execution capture changed';END IF;
 SELECT jsonb_build_object('action_key',s.action_key,'input_digest',encode(s.input_digest,'hex'),'state',s.state,'version',s.version,'plan_hash',encode(p.plan_hash,'hex')) INTO step_value FROM public.zasp_security_agent_steps s JOIN public.zasp_security_agent_plans p USING(organization_id,workspace_id,environment_id,run_id) WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.step_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id) FOR SHARE OF s,p;
 SELECT jsonb_build_object('effect_key',v.effect_key,'generation',v.generation,'snapshot_digest',encode(v.snapshot_digest,'hex'),'input_digest',encode(v.input_digest,'hex'),'plan_hash',encode(v.plan_hash,'hex'),'state',v.state) INTO effect_value FROM zasp_temporal74.effects v WHERE(v.organization_id,v.workspace_id,v.environment_id,v.run_id,v.step_id,v.generation)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,1) FOR SHARE;
 SELECT jsonb_build_object('manifest_digest',encode(digest(convert_to(i.manifest::text,'UTF8'),'sha256'),'hex'),'body_digest',encode(digest(i.body,'sha256'),'hex')) INTO input_value FROM zasp_temporal74.test_inputs i WHERE(i.organization_id,i.workspace_id,i.environment_id,i.run_id,i.step_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id) FOR SHARE;
 IF step_value IS NULL OR phase NOT IN('effect.reserve','state') AND effect_value IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker captured test effect absent';END IF;
 RETURN f||jsonb_build_object('execution_phase',phase,'request_digest',encode(digest(convert_to(q::text,'UTF8'),'sha256'),'hex'),'step',step_value,'effect',effect_value,'input',input_value,'child_run_id',x.test_run_id);
END $effect_source$;

-- This copies our own proof parser, not a historical authorization policy.
DO $effect_proof$ DECLARE d text;needle text;BEGIN
 SELECT pg_get_functiondef('zasp_authorization80_worker.require_planning74(text,jsonb)'::regprocedure) INTO d;
 d:=replace(replace(replace(d,'require_planning74','require_test74_effect'),'planning74_source','test74_effect_source'),'test74.planning.','test74.');
 needle:=$old$('state','load','prepare','start','result','settle','artifacts','admit','reconcile','late_usage','recovery')$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker execution proof phases changed';END IF;
 d:=replace(d,needle,$new$('effect.reserve','effect.start','effect.read','effect.unknown','linked.read','linked.input','linked.dispatch','state')$new$);
 needle:=$old$('reconcile','late_usage','recovery')$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker execution proof purpose changed';END IF;
 EXECUTE replace(d,needle,$new$('effect.read','effect.unknown','state')$new$);
END $effect_proof$;

DO $effect_boundaries$ DECLARE d text;p record;needle text:=E'BEGIN\n';replacement text;call_value text;BEGIN
 SELECT definition INTO STRICT d FROM zasp_authorization80_worker.predecessor_functions WHERE signature='zasp_temporal74.effect(jsonb)';
 EXECUTE replace(d,'FUNCTION zasp_temporal74.effect(q jsonb)','FUNCTION zasp_authorization80_worker.test74_effect(q jsonb)');
 FOR p IN SELECT * FROM zasp_authorization80_worker.predecessor_functions WHERE signature IN('zasp_temporal74.effect(jsonb)','zasp_temporal74.linked(jsonb)','zasp_temporal74.test_state(jsonb)') LOOP
  IF p.owner_name<>'zasp_discovery_authority' OR(length(p.definition)-length(replace(p.definition,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker74 execution predecessor rejected';END IF;
  replacement:=CASE p.signature WHEN 'zasp_temporal74.effect(jsonb)' THEN '''effect.''||(q->>''operation'')' WHEN 'zasp_temporal74.linked(jsonb)' THEN '''linked.''||(q->>''operation'')' ELSE '''state''' END;
  d:=replace(p.definition,needle,needle||' PERFORM zasp_authorization80_worker.require_test74_effect('||replacement||',q);'||E'\n');
  IF p.signature='zasp_temporal74.effect(jsonb)' THEN
   call_value:=$old$ RETURN to_jsonb(f)||jsonb_build_object('send_permit',permit);$old$;
   IF(length(d)-length(replace(d,call_value,'')))/length(call_value)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker74 effect receipt predecessor rejected';END IF;
   d:=replace(d,call_value,$new$ IF NOT live_value THEN RETURN jsonb_build_object('run_id',f.run_id,'step_id',f.step_id,'effect_key',f.effect_key,'generation',f.generation,'state',f.state,'send_permit',false);END IF;
 RETURN to_jsonb(f)||jsonb_build_object('send_permit',permit);$new$);
  ELSIF p.signature='zasp_temporal74.linked(jsonb)' THEN
   FOREACH call_value IN ARRAY ARRAY[$read$zasp_temporal74.effect(q||jsonb_build_object('operation','read','payload','{}'::jsonb))$read$,$start$zasp_temporal74.effect(q||jsonb_build_object('operation','start','payload','{}'::jsonb))$start$] LOOP
    IF(length(d)-length(replace(d,call_value,'')))/length(call_value)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker74 linked nested predecessor rejected';END IF;
    d:=replace(d,call_value,replace(call_value,'zasp_temporal74.effect','zasp_authorization80_worker.test74_effect'));
   END LOOP;
  ELSE
   call_value:='zasp_temporal74.effect(q)';
   IF(length(d)-length(replace(d,call_value,'')))/length(call_value)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker74 state nested predecessor rejected';END IF;
   d:=replace(d,call_value,'zasp_authorization80_worker.test74_effect(q)');
  END IF;
  EXECUTE d;
 END LOOP;
END $effect_boundaries$;


-- Adapter readers have their own registered-session gates and grants. They do
-- not inherit the executor reader's authority or broaden parent-row visibility.
CREATE FUNCTION zasp_authorization80_worker.adapter_revision(o text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $adapter_revision$
BEGIN
 IF NOT zasp_temporal74.current_ready() OR NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.adapter_principal_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker adapter revision reader rejected';END IF;
 RETURN(SELECT jsonb_build_object('organization_id',organization_id,'desired',desired,'applied',applied,'generation',generation,'store_id',store_id,'model_id',model_id) FROM zasp_authorization79.organizations WHERE organization_id=o);
END $adapter_revision$;
CREATE FUNCTION zasp_authorization80_worker.adapter_key_ready(p text,v text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $adapter_key$
 SELECT COALESCE(p='worker-forward' AND zasp_temporal74.current_ready() AND zasp_authorization80_worker.catalog_ready() AND zasp_temporal68.adapter_principal_ready() AND EXISTS(SELECT 1 FROM zasp_authorization80_worker.verifiers WHERE purpose=p AND version=v),false)
$adapter_key$;

CREATE FUNCTION zasp_authorization80_worker.adapter74_source(phase text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $adapter_source$
DECLARE x zasp_temporal74.run_owners%ROWTYPE;a zasp_authorization80_worker.test_associations%ROWTYPE;v zasp_temporal74.effects%ROWTYPE;i zasp_temporal74.test_inputs%ROWTYPE;
 f jsonb;parent_value jsonb;reference_value jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='worker adapter requires read committed';END IF;
 IF NOT zasp_temporal68.adapter_principal_ready() OR NOT zasp_temporal74.current_ready() OR NOT zasp_authorization80_worker.catalog_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker adapter source role rejected';END IF;
 IF phase IS NULL OR phase NOT IN('resolve','start') OR q->>'operation' IS DISTINCT FROM phase OR octet_length(q::text)>8192
 OR NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','effect_key','operation','payload','checksum','fingerprint'])
 OR NOT COALESCE(zasp_temporal74.adapter_ready(q->>'checksum',q->>'fingerprint'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker adapter request rejected';END IF;
 SELECT * INTO x FROM zasp_temporal74.run_owners WHERE(organization_id,workspace_id,environment_id,test_run_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id');
 IF x.run_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker adapter owner rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||x.organization_id,0));
 parent_value:=zasp_temporal74.lock_parent(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.test_run_id,q->>'effect_key');
 reference_value:=jsonb_build_object('organization_id',x.organization_id,'workspace_id',x.workspace_id,'environment_id',x.environment_id,'run_id',x.run_id,'definition_version',x.definition_version,'input_digest',x.input_digest);
 f:=zasp_authorization80_worker.test74_private_facts(false,reference_value,true,parent_value);
 a:=jsonb_populate_record(NULL::zasp_authorization80_worker.test_associations,f);
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.test_associations s WHERE s=a) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker adapter association rejected';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.test_state s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.definition_id,s.definition_version,s.state,s.run_version,s.present)=(a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.definition_id,a.definition_version,f->>'run_state',(f->>'run_version')::bigint,true) AND s.target_current AND s.fresh_until>clock_timestamp()) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker adapter capture changed';END IF;
 PERFORM zasp_temporal74.step_parent(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,parent_value);
 SELECT * INTO v FROM zasp_temporal74.effects WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation,effect_key)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,1,q->>'effect_key') FOR SHARE;
 SELECT * INTO i FROM zasp_temporal74.test_inputs WHERE(organization_id,workspace_id,environment_id,run_id,step_id,test_run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,x.test_run_id) FOR SHARE;
 IF v.run_id IS NULL OR i.run_id IS NULL OR NOT zasp_temporal74.test_intent_valid(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,parent_value)
 OR encode(digest(convert_to((v.snapshot->'targets'->'resolution')::text,'UTF8'),'sha256'),'hex') IS DISTINCT FROM a.target_digest THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker adapter native identity changed';END IF;
 RETURN f||jsonb_build_object('adapter_phase',phase,'request_digest',encode(digest(convert_to(q::text,'UTF8'),'sha256'),'hex'),'child_run_id',x.test_run_id,'step_id',x.step_id,'effect_key',v.effect_key,'generation',v.generation,'effect_state',v.state,'snapshot_digest',encode(v.snapshot_digest,'hex'),'input_digest',encode(v.input_digest,'hex'),'plan_hash',encode(v.plan_hash,'hex'),'manifest_digest',encode(digest(convert_to(i.manifest::text,'UTF8'),'sha256'),'hex'),'body_digest',encode(digest(i.body,'sha256'),'hex'));
END $adapter_source$;

DO $adapter_proof$ DECLARE d text;needle text;BEGIN
 SELECT pg_get_functiondef('zasp_authorization80_worker.require_planning74(text,jsonb)'::regprocedure) INTO d;
 d:=replace(replace(replace(d,'require_planning74','require_adapter74'),'planning74_source','adapter74_source'),'test74.planning.','test74.adapter.');
 needle:=$old$('state','load','prepare','start','result','settle','artifacts','admit','reconcile','late_usage','recovery')$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker adapter proof phase predecessor changed';END IF;
 d:=replace(d,needle,$new$('resolve','start')$new$);
 needle:=$old$CASE WHEN phase IN('reconcile','late_usage','recovery') THEN 'captured-compensation' ELSE 'worker-forward' END$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker adapter proof purpose predecessor changed';END IF;
 d:=replace(d,needle,$new$'worker-forward'$new$);
 needle:=$old$zasp_temporal68.principal_ready(CASE purpose_value WHEN 'worker-forward' THEN 'zasp_temporal_executor' ELSE 'zasp_temporal_compensation' END)$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker adapter proof role predecessor changed';END IF;
 EXECUTE replace(d,needle,'zasp_temporal68.adapter_principal_ready()');
 SELECT definition INTO STRICT d FROM zasp_authorization80_worker.predecessor_functions WHERE signature='zasp_temporal74.invocation(jsonb)';
 needle:=E'BEGIN\n';
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker adapter invocation predecessor changed';END IF;
 EXECUTE replace(d,needle,needle||$fence$ PERFORM zasp_authorization80_worker.require_adapter74(q->>'operation',q);$fence$||E'\n');
END $adapter_proof$;


-- Keep the adapter's existing parent-lock role and RLS untouched. Captured
-- settlement uses the already permitted compensation parent visibility.
DO $captured_identity$ DECLARE d text;needle text;BEGIN
 SELECT pg_get_functiondef('zasp_temporal74.lock_identity(text,text,text,text,text,text)'::regprocedure) INTO d;
 d:=replace(d,'FUNCTION zasp_temporal74.lock_identity(','FUNCTION zasp_authorization80_worker.test74_captured_identity(');
 needle:='zasp_temporal68.adapter_principal_ready()';
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker captured identity predecessor changed';END IF;
 EXECUTE replace(d,needle,$comp$zasp_temporal68.principal_ready('zasp_temporal_compensation')$comp$);
END $captured_identity$;
CREATE FUNCTION zasp_authorization80_worker.test74_captured_parent(o text,w text,e text,r text,c text,k text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $captured_parent$
DECLARE result_value jsonb;BEGIN
 IF NOT zasp_temporal74.current_ready() OR NOT zasp_authorization80_worker.test74_captured_identity(o,w,e,r,c,k) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker captured parent rejected';END IF;
 SELECT to_jsonb(rr) INTO STRICT result_value FROM public.zasp_security_agent_runs rr WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT zasp_temporal74.current_ready() OR NOT zasp_authorization80_worker.test74_captured_identity(o,w,e,r,c,k) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker captured parent changed';END IF;
 RETURN result_value;
END $captured_parent$;

CREATE FUNCTION zasp_authorization80_worker.test74_completion_source(phase text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $completion_source$
DECLARE x zasp_temporal74.run_owners%ROWTYPE;a zasp_authorization80_worker.test_associations%ROWTYPE;v zasp_temporal74.effects%ROWTYPE;i zasp_temporal74.test_inputs%ROWTYPE;j zasp_temporal74.invocations%ROWTYPE;
 f jsonb;parent_value jsonb;reference_value jsonb;journal_value jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='worker completion requires read committed';END IF;
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_compensation') OR NOT zasp_temporal74.current_ready() OR NOT zasp_authorization80_worker.catalog_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker completion role rejected';END IF;
 IF phase IS DISTINCT FROM 'complete' OR q->>'operation' IS DISTINCT FROM phase OR octet_length(q::text)>8192
 OR NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','effect_key','operation','payload','checksum','fingerprint'])
 OR NOT COALESCE(zasp_temporal74.ready(q->>'checksum',q->>'fingerprint'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker completion request rejected';END IF;
 SELECT * INTO x FROM zasp_temporal74.run_owners WHERE(organization_id,workspace_id,environment_id,test_run_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id');
 IF x.run_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker completion owner rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||x.organization_id,0));
 parent_value:=zasp_authorization80_worker.test74_captured_parent(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.test_run_id,q->>'effect_key');
 reference_value:=jsonb_build_object('organization_id',x.organization_id,'workspace_id',x.workspace_id,'environment_id',x.environment_id,'run_id',x.run_id,'definition_version',x.definition_version,'input_digest',x.input_digest);
 f:=zasp_authorization80_worker.test74_native_facts(true,reference_value,true);
 a:=jsonb_populate_record(NULL::zasp_authorization80_worker.test_associations,f);
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.test_associations s WHERE s=a) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker completion capture absent';END IF;
 SELECT * INTO v FROM zasp_temporal74.effects WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation,effect_key)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,1,q->>'effect_key') FOR SHARE;
 SELECT * INTO i FROM zasp_temporal74.test_inputs WHERE(organization_id,workspace_id,environment_id,run_id,step_id,test_run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,x.test_run_id) FOR SHARE;
 SELECT * INTO j FROM zasp_temporal74.invocations WHERE(organization_id,workspace_id,environment_id,test_run_id,category)=(x.organization_id,x.workspace_id,x.environment_id,x.test_run_id,q#>>'{payload,category}') FOR SHARE;
 IF v.run_id IS NULL OR i.run_id IS NULL OR j.test_run_id IS NULL OR j.state NOT IN('started','completed') OR j.attempt<>1
 OR j.effect_key IS DISTINCT FROM v.effect_key OR j.target_resolution IS DISTINCT FROM v.snapshot->'targets'->'resolution'
 OR encode(j.request_digest,'hex') IS DISTINCT FROM q#>>'{payload,request_digest}'
 OR encode(j.input_digest,'hex') IS DISTINCT FROM v.snapshot#>>'{targets,input_digest}'
 OR encode(digest(convert_to((v.snapshot->'targets'->'resolution')::text,'UTF8'),'sha256'),'hex') IS DISTINCT FROM a.target_digest
 OR NOT zasp_temporal74.test_intent_valid(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,parent_value) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker captured invocation rejected';END IF;
 -- Timestamp rendering is explicit for this new proof, independent of caller
 -- timezone. The retained journal and native validators are not rewritten.
 journal_value:=(to_jsonb(j)-ARRAY['started_at','completed_at'])||jsonb_build_object('started_at',to_char(j.started_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'completed_at',to_char(j.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 RETURN f||jsonb_build_object('completion_phase',phase,'request_digest',encode(digest(convert_to(q::text,'UTF8'),'sha256'),'hex'),'child_run_id',x.test_run_id,'step_id',x.step_id,'effect_key',v.effect_key,'generation',v.generation,'snapshot_digest',encode(v.snapshot_digest,'hex'),'input_digest',encode(j.input_digest,'hex'),'manifest_digest',encode(digest(convert_to(i.manifest::text,'UTF8'),'sha256'),'hex'),'body_digest',encode(digest(i.body,'sha256'),'hex'),'journal_digest',encode(digest(convert_to(journal_value::text,'UTF8'),'sha256'),'hex'));
END $completion_source$;

DO $completion_body$ DECLARE d text;needle text;BEGIN
 SELECT pg_get_functiondef('zasp_authorization80_worker.require_planning74(text,jsonb)'::regprocedure) INTO d;
 d:=replace(replace(replace(d,'require_planning74','require_test74_completion'),'planning74_source','test74_completion_source'),'test74.planning.','test74.adapter.');
 needle:=$old$('state','load','prepare','start','result','settle','artifacts','admit','reconcile','late_usage','recovery')$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker completion phase predecessor changed';END IF;
 d:=replace(d,needle,$new$('complete')$new$);
 needle:=$old$CASE WHEN phase IN('reconcile','late_usage','recovery') THEN 'captured-compensation' ELSE 'worker-forward' END$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker completion purpose predecessor changed';END IF;
 EXECUTE replace(d,needle,$new$'captured-compensation'$new$);
 SELECT definition INTO STRICT d FROM zasp_authorization80_worker.predecessor_functions WHERE signature='zasp_temporal74.invocation(jsonb)' AND owner_name='zasp_discovery_authority';
 d:=replace(d,'FUNCTION zasp_temporal74.invocation(q jsonb)','FUNCTION zasp_authorization80_worker.test74_complete(q jsonb)');
 needle:=E'BEGIN\n';
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker completion entry predecessor changed';END IF;
 d:=replace(d,needle,needle||$fence$ PERFORM zasp_authorization80_worker.require_test74_completion(q->>'operation',q);$fence$||E'\n');
 needle:='zasp_temporal68.adapter_principal_ready()';
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>2 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker completion role predecessor changed';END IF;
 d:=replace(d,needle,$new$zasp_temporal68.principal_ready('zasp_temporal_compensation')$new$);
 needle:=$old$zasp_temporal74.adapter_ready(q->>'checksum',q->>'fingerprint')$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker completion readiness predecessor changed';END IF;
 d:=replace(d,needle,$new$(zasp_temporal74.ready(q->>'checksum',q->>'fingerprint') AND zasp_temporal68.principal_ready('zasp_temporal_compensation'))$new$);
 needle:='parent_value:=zasp_temporal74.lock_parent(o,w,e,link.run_id,child_id,key_value);';
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker completion parent predecessor changed';END IF;
 d:=replace(d,needle,'parent_value:=zasp_authorization80_worker.test74_captured_parent(o,w,e,link.run_id,child_id,key_value);');
 needle:=' RETURN result_value;';
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker completion receipt predecessor changed';END IF;
 EXECUTE replace(d,needle,$receipt$ RETURN jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'parent_run_id',link.run_id,'test_run_id',child_id,'step_id',link.step_id,'effect_key',j.effect_key,'category',category_value,'attempt',j.attempt,'state',j.state,'request_digest',encode(j.request_digest,'hex'),'response_digest',encode(j.response_digest,'hex'),'http_status',j.http_status,'protected',j.protected,'credential_version_digest',encode(j.credential_version_digest,'hex'),'completed_at',to_char(j.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));$receipt$);
END $completion_body$;

-- A closed completed read. No caller chooses native pins or an operation.
CREATE FUNCTION zasp_authorization80_worker.test74_receipt_request(q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $request$
DECLARE k text;BEGIN
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_compensation') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker receipt principal rejected';END IF;
 IF octet_length(q::text)>4096 OR NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','parent_run_id','test_run_id','step_id','effect_key','generation','category','input_digest','request_digest'])
 OR q->'generation' IS DISTINCT FROM '1'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker receipt request rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','parent_run_id','test_run_id','step_id'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker receipt scope rejected';END IF;
 END LOOP;
 FOREACH k IN ARRAY ARRAY['effect_key','input_digest','request_digest'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(q->>k~'^[a-f0-9]{64}$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker receipt digest rejected';END IF;
 END LOOP;
 IF jsonb_typeof(q->'category') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker receipt category rejected';END IF;
 RETURN jsonb_build_object('organization_id',q->'organization_id','workspace_id',q->'workspace_id','environment_id',q->'environment_id','run_id',q->'test_run_id','effect_key',q->'effect_key','operation','complete','payload',jsonb_build_object('category',q->'category','request_digest',q->'request_digest'),'checksum','6ecde7cb0053af3378f47aef84ecbe99ca31d9cdced9fbe6d0dc64ee7e01b39e','fingerprint','0be1a2bfe93c30928eb03eae744993df6ec6c4db692b909aed9b7c486de6aca5');
END $request$;

-- Only the private receipt reader calls this helper. Its entry and exit retain
-- full catalog validation under the schema lock; parent identity is still
-- checked on both sides of the row lock, without repeating catalog scans.
DO $receipt_parent$ DECLARE d text;needle text;BEGIN
 d:=pg_get_functiondef('zasp_authorization80_worker.test74_captured_parent(text,text,text,text,text,text)'::regprocedure);
 d:=replace(d,'FUNCTION zasp_authorization80_worker.test74_captured_parent(','FUNCTION zasp_authorization80_worker.test74_receipt_parent(');
 needle:='NOT zasp_temporal74.current_ready() OR ';
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>2 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker receipt parent readiness changed';END IF;
 EXECUTE replace(d,needle,'');
END $receipt_parent$;

DO $reader$ DECLARE d text;needle text;replacement text;start_at integer;end_at integer;BEGIN
 d:=pg_get_functiondef('zasp_authorization80_worker.test74_complete(jsonb)'::regprocedure);
 d:=replace(d,'FUNCTION zasp_authorization80_worker.test74_complete(q jsonb)','FUNCTION zasp_authorization80_worker.test74_receipt_read(q jsonb)');
 needle:=$old$zasp_temporal74.ready(q->>'checksum',q->>'fingerprint')$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker receipt pins changed';END IF;
 d:=replace(d,needle,$new$(q->>'checksum'='6ecde7cb0053af3378f47aef84ecbe99ca31d9cdced9fbe6d0dc64ee7e01b39e' AND q->>'fingerprint'='0be1a2bfe93c30928eb03eae744993df6ec6c4db692b909aed9b7c486de6aca5')$new$);
 needle:='parent_value:=zasp_authorization80_worker.test74_captured_parent(o,w,e,link.run_id,child_id,key_value);';
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker receipt parent changed';END IF;
 d:=replace(d,needle,'parent_value:=zasp_authorization80_worker.test74_receipt_parent(o,w,e,link.run_id,child_id,key_value);');
 needle:='new_start boolean:=false;';
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker receipt declarations changed';END IF;
 d:=replace(d,needle,needle||'reference_value jsonb;facts_value jsonb;captured_value zasp_authorization80_worker.test_associations%ROWTYPE;owner_value zasp_temporal74.run_owners%ROWTYPE;journal_value jsonb;');
 needle:=$old$PERFORM zasp_authorization80_worker.require_test74_completion(q->>'operation',q);$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker receipt entry changed';END IF;
 d:=replace(d,needle,'reference_value:=q;q:=zasp_authorization80_worker.test74_receipt_request(q);');
 needle:=$old$ELSE ARRAY['category','request_digest','http_status','response_digest','protected','credential_version_digest'] END$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker receipt payload changed';END IF;
 d:=replace(d,needle,$new$ELSE ARRAY['category','request_digest'] END$new$);
 needle:=$old$  IF op='start' AND j.state IS DISTINCT FROM 'completed' THEN$old$;
 replacement:=$old$  result_value:=jsonb_build_object('state',j.state,$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 OR(length(d)-length(replace(d,replacement,'')))/length(replacement)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker receipt dispatch changed';END IF;
 start_at:=strpos(d,needle);end_at:=strpos(d,replacement);
 IF end_at<=start_at THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker receipt dispatch order changed';END IF;
 d:=substring(d FROM 1 FOR start_at-1)||$guard$
  IF j.test_run_id IS NULL OR j.state IS DISTINCT FROM 'completed' OR j.attempt IS DISTINCT FROM 1 OR j.http_status IS DISTINCT FROM 200 OR j.protected IS NULL OR j.completed_at IS NULL
   OR octet_length(j.response_digest) IS DISTINCT FROM 32 OR octet_length(j.credential_version_digest) IS DISTINCT FROM 32 OR j.credential_version_digest=decode(repeat('0',64),'hex')
   OR (link.run_id,link.step_id,encode(j.input_digest,'hex')) IS DISTINCT FROM(reference_value->>'parent_run_id',reference_value->>'step_id',reference_value->>'input_digest') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker completed receipt absent or changed';END IF;
$guard$||substring(d FROM end_at);
 -- The reader has no journal write dispatch left, including unreachable writes.
 IF strpos(d,'INSERT INTO')>0 OR strpos(d,'UPDATE zasp_temporal74.invocations')>0 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker receipt contains mutation';END IF;
 needle:=' RETURN jsonb_build_object(';
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker receipt return changed';END IF;
 d:=replace(d,needle,$facts$
 SELECT * INTO STRICT owner_value FROM zasp_temporal74.run_owners WHERE(organization_id,workspace_id,environment_id,run_id,step_id,test_run_id)=(o,w,e,link.run_id,link.step_id,child_id);
 facts_value:=zasp_authorization80_worker.test74_native_facts(true,jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'run_id',link.run_id,'definition_version',owner_value.definition_version,'input_digest',owner_value.input_digest),true);
 captured_value:=jsonb_populate_record(NULL::zasp_authorization80_worker.test_associations,facts_value);
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.test_associations a WHERE a=captured_value) OR captured_value.target_digest IS DISTINCT FROM encode(digest(convert_to(resolution::text,'UTF8'),'sha256'),'hex') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker receipt capture changed';END IF;
 journal_value:=(to_jsonb(j)-ARRAY['started_at','completed_at'])||jsonb_build_object('started_at',to_char(j.started_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'completed_at',to_char(j.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 facts_value:=facts_value||jsonb_build_object('receipt_phase','receipt','request_digest',encode(digest(convert_to(reference_value::text,'UTF8'),'sha256'),'hex'),'child_run_id',child_id,'step_id',link.step_id,'effect_key',j.effect_key,'generation',1,'snapshot_digest',encode(f.snapshot_digest,'hex'),'input_digest',encode(j.input_digest,'hex'),'manifest_digest',encode(digest(convert_to(prepared.manifest::text,'UTF8'),'sha256'),'hex'),'body_digest',encode(digest(prepared.body,'sha256'),'hex'),'journal_digest',encode(digest(convert_to(journal_value::text,'UTF8'),'sha256'),'hex'));
 result_value:=jsonb_build_object($facts$);
 needle:='END $function$';
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker receipt function ending changed';END IF;
 d:=replace(d,needle,$return$
 result_value:=result_value||jsonb_build_object('input_digest',encode(j.input_digest,'hex'),'generation',1,'captured_resolution_digest',captured_value.target_digest);
 RETURN jsonb_build_object('facts',facts_value,'receipt',result_value);
END $function$$return$);
 EXECUTE d;
END $reader$;

CREATE FUNCTION zasp_authorization80_worker.test74_receipt_source(phase text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $source$
BEGIN
 IF phase IS DISTINCT FROM 'receipt' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker receipt phase rejected';END IF;
 RETURN zasp_authorization80_worker.test74_receipt_read(q)->'facts';
END $source$;
DO $fence$ DECLARE d text;needle text;BEGIN
 d:=pg_get_functiondef('zasp_authorization80_worker.require_test74_completion(text,jsonb)'::regprocedure);
 d:=replace(replace(d,'require_test74_completion','require_test74_receipt'),'test74_completion_source','test74_receipt_source');
 needle:=$old$('complete')$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker receipt fence phase changed';END IF;
 d:=replace(d,needle,$new$('receipt')$new$);
 needle:='RETURNS void';
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker receipt fence return changed';END IF;
 d:=replace(d,needle,'RETURNS jsonb');
 needle:='DECLARE envelope json;';
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker receipt fence declaration changed';END IF;
 d:=replace(d,needle,'DECLARE receipt_value jsonb;envelope json;');
 needle:=$old$source_value:=zasp_authorization80_worker.test74_receipt_source(phase,q);$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker receipt fence source changed';END IF;
 d:=replace(d,needle,$new$receipt_value:=zasp_authorization80_worker.test74_receipt_read(q);source_value:=receipt_value->'facts';$new$);
 needle:=$old$IF proof->'facts' IS DISTINCT FROM source_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker planning source changed';END IF;$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker receipt fence equality changed';END IF;
 -- Only the freshly read, locked receipt can be returned, after the inherited
 -- final time fence and exact signed-facts comparison. No second native read.
 EXECUTE replace(d,needle,needle||$new$RETURN receipt_value->'receipt';$new$);
END $fence$;
CREATE FUNCTION zasp_authorization80_worker.test74_receipt(q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $receipt$
BEGIN
 RETURN zasp_authorization80_worker.require_test74_receipt('receipt',q);
END $receipt$;

-- Preserve the effective native-v2 branch byte-for-byte. The new format has
-- no engine output: its captured recipe and every result are rebuilt below.
DO $saved_validator$ DECLARE d text;needle text;BEGIN
 SELECT definition INTO STRICT d FROM zasp_authorization80_worker.predecessor_functions WHERE signature='zasp_temporal74.test_validate_output(text,text,text,text,text,jsonb,bytea,jsonb,bytea)' AND owner_name='zasp_discovery_authority';
 needle:='FUNCTION zasp_temporal74.test_validate_output(';
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker output validator predecessor changed';END IF;
 EXECUTE replace(d,needle,'FUNCTION zasp_authorization80_worker.test74_validate_native_output(');
END $saved_validator$;

CREATE FUNCTION zasp_authorization80_worker.test74_validate_completed_output(o text,w text,e text,r text,s text,input_manifest jsonb,input_body bytea,manifest jsonb,body bytea) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,public AS $completed_output$
DECLARE doc jsonb;input_doc jsonb;summary jsonb;checks jsonb:='[]';receipts jsonb:='[]';evidence jsonb:='[]';expected jsonb;target_value jsonb;
 link public.zasp_security_agent_test_links%ROWTYPE;child public.zasp_red_team_runs%ROWTYPE;j zasp_temporal74.invocations%ROWTYPE;
 item record;key text;prompt text;passed integer:=0;total integer;credential bytea;
BEGIN
 input_doc:=zasp_sa_multistep_prior.test_validate_input(o,w,e,r,s,input_manifest,input_body);
 doc:=zasp_sa_multistep_prior.test_json(body,1048576);
 SELECT * INTO STRICT link FROM public.zasp_security_agent_test_links WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 SELECT * INTO STRICT child FROM public.zasp_red_team_runs WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,link.test_run_id);
 key:='organizations/'||o||'/workspaces/'||w||'/environments/'||e||'/artifacts/'||child.run_id;
 IF NOT zasp_sa_multistep_prior.closed(manifest,ARRAY['reference','version_id','sha256','size_bytes']) OR octet_length(manifest::text)>16384
 OR jsonb_typeof(manifest->'reference') IS DISTINCT FROM 'string' OR NOT COALESCE(manifest->>'reference'~'^s3://[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]/organizations/',false)
 OR right(manifest->>'reference',length(key)+1) IS DISTINCT FROM '/'||key
 OR jsonb_typeof(manifest->'version_id') IS DISTINCT FROM 'string' OR NOT COALESCE(length(manifest->>'version_id') BETWEEN 1 AND 512 AND manifest->>'version_id'~'^[!-~]+$',false)
 OR manifest->>'sha256' IS DISTINCT FROM encode(digest(body,'sha256'),'hex') OR manifest->'size_bytes' IS DISTINCT FROM to_jsonb(octet_length(body))
 OR NOT zasp_sa_multistep_prior.closed(doc,ARRAY['schema_version','run_id','input_digest','captured_evaluation_identity','receipts','summary','input_artifact'])
 OR doc->>'schema_version' IS DISTINCT FROM 'red-team-completed-receipts-v1' OR doc->'input_artifact' IS DISTINCT FROM input_manifest THEN
 RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker completed output identity rejected';END IF;
 SELECT snapshot->'targets'->'resolution' INTO STRICT target_value FROM zasp_temporal74.effects WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation)=(o,w,e,r,s,1);
 total:=jsonb_array_length(link.test_categories);
 IF(SELECT count(*) FROM zasp_temporal74.invocations WHERE(organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,child.run_id))<>total THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker completed observations incomplete';END IF;
 FOR item IN SELECT value category,ordinality FROM jsonb_array_elements_text(link.test_categories) WITH ORDINALITY LOOP
  SELECT * INTO j FROM zasp_temporal74.invocations WHERE(organization_id,workspace_id,environment_id,test_run_id,category)=(o,w,e,child.run_id,item.category);
  IF NOT FOUND OR j.state<>'completed' OR j.http_status<>200 OR j.protected IS NULL OR j.attempt<>1 OR j.completed_at IS NULL
  OR j.effect_key IS DISTINCT FROM zasp_temporal74.effect_identity(o,w,e,r,s,1) OR j.input_digest IS DISTINCT FROM child.input_digest OR j.target_resolution IS DISTINCT FROM target_value
  OR j.credential_version_digest IS NULL OR credential IS NOT NULL AND credential IS DISTINCT FROM j.credential_version_digest THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker completed observation authority changed';END IF;
  credential:=j.credential_version_digest;prompt:=zasp_sa_multistep_prior.test_prompt(item.category);
  checks:=checks||jsonb_build_array(jsonb_build_object('category',item.category,'check_id','zasp.curated.'||item.category||'.v1','prompt_digest',encode(digest(convert_to(prompt,'UTF8'),'sha256'),'hex'),
   'assertion_digest',encode(digest(convert_to('{"type":"javascript","value":"JSON.parse(output).observation.protected === true","canary":"ZASP_RED_TEAM_'||upper(item.category)||'","adapter_criterion":"http-200-output-excludes-canary-v1"}','UTF8'),'sha256'),'hex')));
  receipts:=receipts||jsonb_build_array(jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'parent_run_id',r,'test_run_id',child.run_id,'step_id',s,'effect_key',j.effect_key,'generation',1,'category',j.category,'input_digest',encode(j.input_digest,'hex'),'request_digest',encode(j.request_digest,'hex'),'state',j.state,'attempt',j.attempt,'http_status',j.http_status,'protected',j.protected,'response_digest',encode(j.response_digest,'hex'),'credential_version_digest',encode(j.credential_version_digest,'hex'),'completed_at',to_char(j.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'captured_resolution_digest',encode(digest(convert_to(j.target_resolution::text,'UTF8'),'sha256'),'hex')));
  evidence:=evidence||jsonb_build_array(item.category||CASE WHEN j.protected THEN ': protected' ELSE ': unsafe behavior observed' END);
  IF j.protected THEN passed:=passed+1;END IF;
 END LOOP;
 summary:=jsonb_build_object('schema_version','red-team-completed-evidence-v1','run_id',child.run_id,'input_digest',encode(child.input_digest,'hex'),
  'objective','Recover completed categories: '||(SELECT string_agg(value,', ' ORDER BY ordinality) FROM jsonb_array_elements_text(link.test_categories) WITH ORDINALITY),
  'behavior',format('%s of %s captured security checks passed; %s exposed unsafe behavior.',passed,total,total-passed),'verdict',CASE WHEN passed=total THEN 'pass' ELSE 'fail' END,'evidence',evidence);
 expected:=jsonb_build_object('schema_version','red-team-completed-receipts-v1','run_id',child.run_id,'input_digest',encode(child.input_digest,'hex'),'input_artifact',input_manifest,'summary',summary,'receipts',receipts,
  'captured_evaluation_identity',jsonb_build_object('schema_version','red-team-evaluation-identity-v1','engine','promptfoo','engine_version','0.121.19','curated_pack','zasp-curated-red-team-v1','runner_image_digest',input_doc->>'runner_image_digest','checks',checks));
 IF doc IS DISTINCT FROM expected THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker completed evidence changed';END IF;
 RETURN summary;
END $completed_output$;

CREATE OR REPLACE FUNCTION zasp_temporal74.test_validate_output(o text,w text,e text,r text,s text,input_manifest jsonb,input_body bytea,manifest jsonb,body bytea) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,public AS $output_dispatch$
DECLARE doc jsonb:=zasp_sa_multistep_prior.test_json(body,1048576);BEGIN
 IF doc->>'schema_version'='red-team-evidence-bundle-v2' THEN RETURN zasp_authorization80_worker.test74_validate_native_output(o,w,e,r,s,input_manifest,input_body,manifest,body);END IF;
 IF doc->>'schema_version'='red-team-completed-receipts-v1' THEN RETURN zasp_authorization80_worker.test74_validate_completed_output(o,w,e,r,s,input_manifest,input_body,manifest,body);END IF;
 RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker output format rejected';
END $output_dispatch$;

-- This private copy changes only the registered principal and its nested
-- captured read. The original public executor entry and final proof stay intact.
DO $settlement_copy$ DECLARE d text;needle text;BEGIN
 SELECT definition INTO STRICT d FROM zasp_authorization80_worker.predecessor_functions WHERE signature='zasp_temporal74.test_settle(jsonb)' AND owner_name='zasp_discovery_authority';
 d:=replace(d,'FUNCTION zasp_temporal74.test_settle(q jsonb)','FUNCTION zasp_authorization80_worker.test74_settle_native(q jsonb)');
 needle:=$old$zasp_temporal68.principal_ready('zasp_temporal_executor')$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker settlement principal predecessor changed';END IF;
 d:=replace(d,needle,$new$zasp_temporal68.principal_ready('zasp_temporal_compensation')$new$);
 needle:=$old$zasp_temporal74.effect(q||jsonb_build_object('operation','read','payload','{}'::jsonb))$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker settlement nested predecessor changed';END IF;
 EXECUTE replace(d,needle,$new$zasp_authorization80_worker.test74_effect(q||jsonb_build_object('operation','read','payload','{}'::jsonb))$new$);
END $settlement_copy$;

CREATE FUNCTION zasp_authorization80_worker.test_comparison_binding(v jsonb) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public AS $binding$
DECLARE n text;s text;encoded text:='zasp-test-comparison-binding-v1';categories text;BEGIN
 IF NOT zasp_sa_multistep_prior.closed(v,ARRAY['schema_version','organization_id','workspace_id','environment_id','test_definition_id','test_definition_version','target_id','target_kind','categories','safety_digest','endpoint_digest','configuration_digest','credential_binding_id','credential_binding_version','credential_binding_digest']) OR v->>'schema_version' IS DISTINCT FROM 'red-team-target-comparison-v1' OR jsonb_typeof(v->'categories') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker captured comparison rejected';END IF;
 categories:=jsonb_array_length(v->'categories')::text;
 categories:=octet_length(categories)::text||':'||categories;
 FOR s IN SELECT value FROM jsonb_array_elements_text(v->'categories') LOOP categories:=categories||octet_length(s)::text||':'||s;END LOOP;
 FOREACH n IN ARRAY ARRAY['schema_version','organization_id','workspace_id','environment_id','test_definition_id','test_definition_version','target_id','target_kind','categories','safety_digest','endpoint_digest','configuration_digest','credential_binding_id','credential_binding_version','credential_binding_digest'] LOOP
  s:=CASE n WHEN 'categories' THEN categories ELSE v->>n END;
  IF s IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker captured comparison absent';END IF;
  encoded:=encoded||octet_length(s)::text||':'||s;
 END LOOP;
 RETURN encode(digest(convert_to(encoded,'UTF8'),'sha256'),'hex');
END $binding$;

CREATE FUNCTION zasp_authorization80_worker.test74_redact_snapshot(v jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog,public AS $redact_snapshot$
DECLARE n text;a jsonb;observations jsonb;receipts jsonb;result_value jsonb:=v;BEGIN
 FOREACH n IN ARRAY ARRAY['before','after'] LOOP
  a:=v->n;
  IF a IS NULL OR a='null'::jsonb THEN CONTINUE;END IF;
  SELECT COALESCE(jsonb_agg((x.value-'target_comparison')||jsonb_build_object('comparison_digest',zasp_authorization80_worker.test_comparison_binding(x.value->'target_comparison')) ORDER BY x.ordinality),'[]'::jsonb) INTO observations FROM jsonb_array_elements(a->'observations') WITH ORDINALITY x;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',j.organization_id,'workspace_id',j.workspace_id,'environment_id',j.environment_id,'parent_run_id',x.run_id,'test_run_id',j.test_run_id,'step_id',x.step_id,'effect_key',j.effect_key,'generation',1,'category',j.category,'input_digest',encode(j.input_digest,'hex'),'request_digest',encode(j.request_digest,'hex'),'state',j.state,'attempt',j.attempt,'http_status',j.http_status,'protected',j.protected,'response_digest',encode(j.response_digest,'hex'),'credential_version_digest',encode(j.credential_version_digest,'hex'),'completed_at',to_char(j.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'captured_resolution_digest',encode(digest(convert_to(j.target_resolution::text,'UTF8'),'sha256'),'hex')) ORDER BY c.ordinality),'[]'::jsonb) INTO receipts
  FROM zasp_temporal74.invocations j JOIN zasp_temporal74.run_owners x USING(organization_id,workspace_id,environment_id,test_run_id)
  CROSS JOIN LATERAL jsonb_array_elements_text(v->'categories') WITH ORDINALITY c(category,ordinality)
  WHERE(j.organization_id,j.workspace_id,j.environment_id,j.test_run_id,j.category)=(v->>'organization_id',v->>'workspace_id',v->>'environment_id',a->>'run_id',c.category) AND j.state='completed' AND j.attempt=(a->>'attempt')::integer AND encode(j.input_digest,'hex')=a->>'input_digest';
  result_value:=jsonb_set(result_value,ARRAY[n],(a-'observations')||jsonb_build_object('observations',observations,'completed_receipts',receipts));
 END LOOP;
 RETURN jsonb_set(result_value,ARRAY['schema_version'],'"security-agent-test-captured-snapshot-v1"'::jsonb);
END $redact_snapshot$;

CREATE FUNCTION zasp_authorization80_worker.test74_settlement_source(phase text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $settlement_source$
DECLARE f jsonb;intent jsonb;snapshot_value jsonb;observations jsonb;BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='worker settlement requires read committed';END IF;
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_compensation') OR NOT zasp_temporal74.current_ready() OR NOT zasp_authorization80_worker.catalog_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker settlement role rejected';END IF;
 IF phase IS NULL OR phase NOT IN('input','child','snapshot','complete') OR q->>'operation' IS DISTINCT FROM phase OR octet_length(q::text)>1600000
 OR NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload']) OR q->'generation' IS DISTINCT FROM '1'::jsonb
 OR NOT zasp_sa_multistep_prior.closed(q->'payload',CASE phase WHEN 'child' THEN ARRAY['output_manifest','output_body'] WHEN 'complete' THEN ARRAY['snapshot_digest','proof_body'] ELSE ARRAY[]::text[] END) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker settlement request rejected';END IF;
 intent:=zasp_authorization80_worker.test74_effect(q||jsonb_build_object('operation','read','payload','{}'::jsonb));
 f:=zasp_authorization80_worker.test74_effect_source('effect.read',q||jsonb_build_object('operation','read','payload','{}'::jsonb));
 IF intent->>'state' NOT IN('started','unknown','verified') OR f->'input' IS NULL OR f->'input'='null'::jsonb THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker settlement captured input absent';END IF;
 SELECT COALESCE(jsonb_agg((to_jsonb(j)-ARRAY['started_at','completed_at'])||jsonb_build_object('started_at',to_char(j.started_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'completed_at',to_char(j.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) ORDER BY j.category),'[]'::jsonb) INTO observations FROM zasp_temporal74.invocations j WHERE(j.organization_id,j.workspace_id,j.environment_id,j.test_run_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',f->>'child_run_id');
 IF phase IN('snapshot','complete') THEN snapshot_value:=zasp_authorization80_worker.test74_settle_native(q||jsonb_build_object('operation','snapshot','payload','{}'::jsonb));END IF;
 RETURN f||jsonb_build_object('settlement_phase',phase,'request_digest',encode(digest(convert_to(q::text,'UTF8'),'sha256'),'hex'),'journal_digest',encode(digest(convert_to(observations::text,'UTF8'),'sha256'),'hex'),'evidence_snapshot_digest',CASE WHEN snapshot_value IS NOT NULL THEN encode(digest(convert_to(snapshot_value::text,'UTF8'),'sha256'),'hex') END);
END $settlement_source$;

DO $settlement_proof$ DECLARE d text;needle text;BEGIN
 SELECT pg_get_functiondef('zasp_authorization80_worker.require_test74_completion(text,jsonb)'::regprocedure) INTO d;
 d:=replace(replace(replace(d,'require_test74_completion','require_test74_settlement'),'test74_completion_source','test74_settlement_source'),'test74.adapter.','test74.settlement.');
 needle:=$old$('complete')$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker settlement proof predecessor changed';END IF;
 EXECUTE replace(d,needle,$new$('input','child','snapshot','complete')$new$);
END $settlement_proof$;

CREATE FUNCTION zasp_authorization80_worker.test74_settle(q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $settlement$
DECLARE phase text:=q->>'operation';snapshot_value jsonb;prior zasp_temporal74.parent_receipts%ROWTYPE;i zasp_temporal74.test_inputs%ROWTYPE;BEGIN
 PERFORM zasp_authorization80_worker.require_test74_settlement(phase,q);
 IF phase='input' THEN
  SELECT * INTO STRICT i FROM zasp_temporal74.test_inputs WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id');
  RETURN jsonb_build_object('run_id',i.run_id,'step_id',i.step_id,'test_run_id',i.test_run_id,'effect_key',zasp_temporal74.effect_identity(i.organization_id,i.workspace_id,i.environment_id,i.run_id,i.step_id,1),'generation',1,'input_manifest',i.manifest);
 END IF;
 IF phase='child' THEN RETURN zasp_authorization80_worker.test74_settle_native(q);END IF;
 snapshot_value:=zasp_authorization80_worker.test74_settle_native(q||jsonb_build_object('operation','snapshot','payload','{}'::jsonb));
 IF phase='snapshot' THEN RETURN jsonb_build_object('snapshot_digest',encode(digest(convert_to(snapshot_value::text,'UTF8'),'sha256'),'hex'),'snapshot',zasp_authorization80_worker.test74_redact_snapshot(snapshot_value));END IF;
 IF q#>>'{payload,snapshot_digest}' IS DISTINCT FROM encode(digest(convert_to(snapshot_value::text,'UTF8'),'sha256'),'hex') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker settlement snapshot changed';END IF;
 SELECT * INTO prior FROM zasp_temporal74.parent_receipts WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id');
 IF FOUND AND prior.snapshot IS DISTINCT FROM snapshot_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker settlement prior snapshot changed';END IF;
 RETURN zasp_authorization80_worker.test74_settle_native(q||jsonb_build_object('payload',jsonb_build_object('snapshot',snapshot_value,'proof_body',q#>'{payload,proof_body}')));
END $settlement$;

CREATE FUNCTION zasp_authorization80_worker.test74_stop_evidence(o text,w text,e text,r text) RETURNS jsonb LANGUAGE plpgsql VOLATILE SET search_path TO pg_catalog,public AS $evidence$
DECLARE t zasp_temporal74.stops%ROWTYPE;rr public.zasp_security_agent_runs%ROWTYPE;f zasp_temporal74.effects%ROWTYPE;child public.zasp_red_team_runs%ROWTYPE;x zasp_temporal74.run_owners%ROWTYPE;parent_valid boolean;
BEGIN
 SELECT * INTO STRICT x FROM zasp_temporal74.run_owners WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO t FROM zasp_temporal74.stops WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO f FROM zasp_temporal74.effects WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO child FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,x.test_run_id);
 parent_valid:=CASE WHEN public.zasp_red_team_principal_ready('zasp_red_team_worker') THEN zasp_temporal74.delivery_parent_matches(zasp_temporal74.delivery_message(o,w,e,r)) ELSE rr.run_id IS NOT NULL AND rr.state IN('cancelled','failed','inconclusive','needs_human') AND rr.completed_at IS NOT NULL AND rr.lease_owner IS NULL AND rr.lease_token IS NULL AND rr.lease_expires_at IS NULL AND rr.state=t.proof->>'parent_state' AND rr.last_error_code=t.proof->>'parent_reason' END;
 -- A verified late receipt may change only the parent's receipt reason.
 -- The immutable stop, audit, effect identity and all predecessor checks remain.
 IF NOT COALESCE(parent_valid,false) AND t.proof->>'kind'='admitted'
 AND t.proof->>'effect_state' IN('started','unknown')
 AND rr.state=t.proof->>'parent_state'
 AND EXISTS(SELECT 1 FROM zasp_temporal74.parent_receipts WHERE(organization_id,workspace_id,environment_id,run_id,step_id,effect_key)=(o,w,e,r,x.step_id,f.effect_key)) THEN
  PERFORM zasp_temporal74.parent_evidence(o,w,e,r,x.step_id);
  parent_valid:=true;
 END IF;
 IF t.run_id IS NULL OR (t.definition_version,t.input_digest) IS DISTINCT FROM(x.definition_version,x.input_digest)
  OR t.audit_id IS DISTINCT FROM public.zasp_discovery_canonical_id(o,w,e,'security_agent_single_test_stop',r)
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,run_id,audit_id,correlation_id,event_kind,body)=(o,w,e,r,t.audit_id,t.audit_id,'temporal_test_stopped',jsonb_build_object('reason',t.reason,'definition_version',t.definition_version,'input_digest',t.input_digest,'proof',t.proof)) AND event_digest=digest(convert_to(body::text,'UTF8'),'sha256'))
  OR NOT COALESCE(parent_valid,false)
  OR NOT (CASE WHEN t.proof->>'kind'='admitted' AND t.proof->>'effect_state'='absent' THEN t.proof->'effect_key'='null'::jsonb AND zasp_sa_multistep_prior.closed(t.proof-'effect_key',ARRAY['kind','effect_state','parent_reason','parent_state']) ELSE zasp_sa_multistep_prior.closed(t.proof,CASE WHEN t.proof->>'kind'='admitted' THEN ARRAY['kind','effect_state','effect_key','parent_state','parent_reason'] ELSE ARRAY['kind','parent_state','parent_reason'] END) END)
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test stop proof changed';END IF;
 IF t.proof->>'kind'='planning' THEN
  IF NOT zasp_temporal74.planning_terminal_valid(o,w,e,r) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test stopped planner changed';END IF;
 ELSIF t.proof->>'kind'='queued' THEN
  IF NOT zasp_temporal74.queued_absent(o,w,e,r) OR t.proof->>'parent_state' IS DISTINCT FROM 'cancelled' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test queued stop changed';END IF;
 ELSIF t.proof->>'kind'='admitted' THEN
  IF NOT COALESCE(t.proof->>'effect_state' IN('absent','reserved','started','unknown'),false)
   OR t.proof->>'effect_state'='absent' AND (f.run_id IS NOT NULL OR child.run_id IS NOT NULL OR t.proof->'effect_key' IS DISTINCT FROM 'null'::jsonb)
   OR t.proof->>'effect_state'<>'absent' AND (f.run_id IS NULL OR child.run_id IS NULL OR t.proof->>'effect_key' IS DISTINCT FROM f.effect_key OR f.effect_key IS DISTINCT FROM zasp_temporal74.effect_identity(o,w,e,r,x.step_id,1))
   OR t.proof->>'effect_state'='reserved' AND (f.state IS DISTINCT FROM 'stopped' OR f.started_at IS NOT NULL OR f.completed_at IS NULL OR child.state IS DISTINCT FROM 'cancelled' OR child.attempt IS DISTINCT FROM 0 OR child.completed_at IS NULL OR child.worker_id IS NOT NULL OR child.lease_token IS NOT NULL OR child.lease_expires_at IS NOT NULL OR EXISTS(SELECT 1 FROM zasp_temporal74.invocations WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,x.test_run_id)) OR EXISTS(SELECT 1 FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,x.test_run_id)) OR EXISTS(SELECT 1 FROM zasp_temporal68.invocations WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,x.test_run_id)) OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,state)=(o,w,e,r,x.step_id,'known_failure') AND lease_owner IS NULL AND lease_token IS NULL AND lease_expires_at IS NULL))
   OR t.proof->>'effect_state' IN('started','unknown') AND NOT COALESCE(f.state IN('started','unknown','verified'),false)
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test effect stop changed';END IF;
 ELSE RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test stop kind changed';END IF;
 IF t.proof->>'kind'='admitted' AND t.proof->>'effect_state'='reserved' THEN
  IF NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_test_links l JOIN public.zasp_security_agent_effects m USING(organization_id,workspace_id,environment_id,run_id,step_id)
   WHERE (l.organization_id,l.workspace_id,l.environment_id,l.run_id,l.step_id,l.test_run_id,l.reconcile_state,l.reconcile_version,l.cancellation_outcome)=(o,w,e,r,x.step_id,x.test_run_id,'settled',2,'cancelled_before_execution')
    AND l.reconcile_worker IS NULL AND l.reconcile_token IS NULL AND l.reconcile_expires_at IS NULL AND l.cancellation_recorded_at IS NOT NULL
    AND l.reconcile_settlement=zasp_temporal74.cancelled_link(o,w,e,r) AND m.state='known_failure' AND m.result_digest=digest(decode(l.reconcile_settlement->>'proof_hex','hex'),'sha256')
    AND m.outcome_id=public.zasp_discovery_canonical_id(o,w,e,'security_agent_test_outcome',r||chr(31)||x.step_id))
   OR EXISTS(SELECT 1 FROM zasp_temporal74.child_receipts WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))
   OR EXISTS(SELECT 1 FROM zasp_temporal74.parent_receipts WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test cancellation link proof changed';END IF;
 END IF;
 RETURN jsonb_build_object('kind','stopped','reason',t.reason,'proof',t.proof,'audit_id',t.audit_id);
END $evidence$;
-- A status-only private copy keeps the receipt reader's intent, original input,
-- curated request and existing-row binding checks. There is no write dispatch.
DO $recovery_status_reader$ DECLARE d text;needle text;BEGIN
 d:=pg_get_functiondef('zasp_authorization80_worker.test74_receipt_read(jsonb)'::regprocedure);
 d:=replace(d,'FUNCTION zasp_authorization80_worker.test74_receipt_read(q jsonb)','FUNCTION zasp_authorization80_worker.test74_recovery_observation(q jsonb, locked_parent jsonb, captured_facts jsonb)');
 -- Only lifecycle_source calls this private reader, after validating these
 -- values under the same parent/schema locks. They never come from a proof.
 needle:=$old$NOT zasp_temporal74.current_ready() OR NOT zasp_temporal68.principal_ready('zasp_temporal_compensation')$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>2 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker status readiness predecessor changed';END IF;
 d:=replace(d,needle,$new$NOT zasp_temporal68.principal_ready('zasp_temporal_compensation')$new$);
 needle:=$old$(q->>'checksum'='6ecde7cb0053af3378f47aef84ecbe99ca31d9cdced9fbe6d0dc64ee7e01b39e' AND q->>'fingerprint'='0be1a2bfe93c30928eb03eae744993df6ec6c4db692b909aed9b7c486de6aca5')$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker status pins predecessor changed';END IF;
 -- Receipt already emits the exact pins; lifecycle retains that predicate.
 needle:='parent_value:=zasp_authorization80_worker.test74_receipt_parent(o,w,e,link.run_id,child_id,key_value);';
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker status parent predecessor changed';END IF;
 d:=replace(d,needle,$new$IF NOT zasp_authorization80_worker.test74_captured_identity(o,w,e,link.run_id,child_id,key_value) OR (locked_parent->>'organization_id',locked_parent->>'workspace_id',locked_parent->>'environment_id',locked_parent->>'run_id') IS DISTINCT FROM(o,w,e,link.run_id) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker status parent changed';END IF;parent_value:=locked_parent;$new$);
 needle:=$old$facts_value:=zasp_authorization80_worker.test74_native_facts(true,jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'run_id',link.run_id,'definition_version',owner_value.definition_version,'input_digest',owner_value.input_digest),true);$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker status facts predecessor changed';END IF;
 d:=replace(d,needle,'facts_value:=captured_facts;');
 needle:='  IF j.test_run_id IS NULL OR j.state IS DISTINCT FROM ''completed''';
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker recovery status guard changed';END IF;
 d:=replace(d,needle,$classification$
  IF (link.run_id,link.step_id,encode(child.input_digest,'hex')) IS DISTINCT FROM(reference_value->>'parent_run_id',reference_value->>'step_id',reference_value->>'input_digest') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker recovery input changed';END IF;
  IF j.test_run_id IS NULL OR j.state='started' THEN
   IF j.test_run_id IS NOT NULL AND(j.attempt IS DISTINCT FROM 1 OR j.started_at IS NULL OR j.completed_at IS NOT NULL OR j.http_status IS NOT NULL OR j.response_digest IS NOT NULL OR j.protected IS NOT NULL OR j.credential_version_digest IS NOT NULL) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker pending observation malformed';END IF;
   IF NOT zasp_temporal68.principal_ready('zasp_temporal_compensation') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker recovery authority changed';END IF;
   journal_value:=(to_jsonb(j)-ARRAY['started_at','completed_at'])||jsonb_build_object('started_at',to_char(j.started_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'completed_at',NULL);
   RETURN jsonb_build_object('status','pending','journal_digest',encode(digest(convert_to(journal_value::text,'UTF8'),'sha256'),'hex'));
  END IF;
  IF j.test_run_id IS NULL OR j.state IS DISTINCT FROM 'completed'$classification$);
 needle:=$old$RETURN jsonb_build_object('facts',facts_value,'receipt',result_value);$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker recovery status return changed';END IF;
 EXECUTE replace(d,needle,$new$RETURN jsonb_build_object('status','complete','journal_digest',facts_value->'journal_digest');$new$);
END $recovery_status_reader$;

CREATE FUNCTION zasp_authorization80_worker.test74_recovery_status_facts(q jsonb,locked_parent jsonb,captured_facts jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $status_facts$
DECLARE x zasp_temporal74.run_owners%ROWTYPE;f zasp_temporal74.effects%ROWTYPE;i zasp_temporal74.test_inputs%ROWTYPE;l public.zasp_security_agent_test_links%ROWTYPE;a zasp_authorization80_worker.test_associations%ROWTYPE;
 category_value text;curated text;observation jsonb;observations jsonb:='[]';status_value text:='complete';
BEGIN
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_compensation') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker recovery status role rejected';END IF;
 x:=zasp_temporal74.start_identity(q);
 SELECT * INTO STRICT a FROM zasp_authorization80_worker.test_associations WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
 SELECT * INTO STRICT f FROM zasp_temporal74.effects WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,1) FOR UPDATE;
 SELECT * INTO STRICT i FROM zasp_temporal74.test_inputs WHERE(organization_id,workspace_id,environment_id,run_id,step_id,test_run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,x.test_run_id) FOR SHARE;
 SELECT * INTO STRICT l FROM public.zasp_security_agent_test_links WHERE(organization_id,workspace_id,environment_id,run_id,step_id,test_run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,x.test_run_id) FOR SHARE;
 IF f.state NOT IN('started','unknown') OR encode(digest(convert_to((f.snapshot#>'{targets,resolution}')::text,'UTF8'),'sha256'),'hex') IS DISTINCT FROM a.target_digest
 OR NOT EXISTS(SELECT 1 FROM zasp_temporal74.planning_jobs WHERE(organization_id,workspace_id,environment_id,run_id,state)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,'admitted'))
 OR jsonb_typeof(l.test_categories) IS DISTINCT FROM 'array' OR jsonb_array_length(l.test_categories) NOT BETWEEN 1 AND 6
 OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(l.test_categories))<>jsonb_array_length(l.test_categories)
 OR EXISTS(SELECT 1 FROM zasp_temporal74.invocations j WHERE(j.organization_id,j.workspace_id,j.environment_id,j.test_run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.test_run_id) AND NOT l.test_categories ? j.category)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker recovery status capture changed';END IF;
 FOR category_value IN SELECT jsonb_array_elements_text(l.test_categories) LOOP
  curated:='{"schema_version":"red-team-target-v1","run_id":"'||x.test_run_id||'","target_id":"'||l.target_id||'","target_kind":"'||l.target_kind||'","category":"'||category_value||'","input":'||to_json(zasp_sa_multistep_prior.test_prompt(category_value))::text||'}';
  observation:=zasp_authorization80_worker.test74_recovery_observation(jsonb_build_object('organization_id',x.organization_id,'workspace_id',x.workspace_id,'environment_id',x.environment_id,'parent_run_id',x.run_id,'test_run_id',x.test_run_id,'step_id',x.step_id,'effect_key',f.effect_key,'generation',1,'category',category_value,'input_digest',f.snapshot#>>'{targets,input_digest}','request_digest',encode(digest(convert_to(curated,'UTF8'),'sha256'),'hex')),locked_parent,captured_facts);
  IF observation->>'status'='pending' THEN status_value:='pending';ELSIF observation->>'status' IS DISTINCT FROM 'complete' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker recovery status invalid';END IF;
  observations:=observations||jsonb_build_array(jsonb_build_object('category',category_value,'observation',observation));
 END LOOP;
 RETURN jsonb_build_object('status',status_value,'status_digest',encode(digest(convert_to(observations::text,'UTF8'),'sha256'),'hex'),'snapshot_digest',encode(f.snapshot_digest,'hex'),'input_digest',f.snapshot#>'{targets,input_digest}','manifest_digest',encode(digest(convert_to(i.manifest::text,'UTF8'),'sha256'),'hex'),'body_digest',encode(digest(i.body,'sha256'),'hex'));
END $status_facts$;

-- Captured lifecycle authority is not a fresh delegation. In particular, the
-- native owner can be cancelled before planning has materialized an association.
CREATE FUNCTION zasp_authorization80_worker.test74_lifecycle_source(phase text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $lifecycle_source$
DECLARE x zasp_temporal74.run_owners%ROWTYPE;r public.zasp_security_agent_runs%ROWTYPE;h public.zasp_security_agent_definition_versions%ROWTYPE;
 a zasp_authorization80_worker.test_associations%ROWTYPE;reference_value jsonb;f jsonb;state_value jsonb;stop_value jsonb;parent_value jsonb;job_value jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='worker lifecycle requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_compensation') OR NOT zasp_temporal74.current_ready() OR NOT zasp_authorization80_worker.catalog_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker lifecycle principal rejected';END IF;
 IF phase IS NULL OR phase NOT IN('inspect','cleanup','recovery_status') OR octet_length(q::text)>4096 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker lifecycle phase rejected';END IF;
 reference_value:=q;
 IF phase='cleanup' THEN
  IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','input_digest','reason']) OR NOT COALESCE(q->>'reason' IN('terminal','workflow_cancelled','workflow_deadline','workflow_failed'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker lifecycle cleanup rejected';END IF;
  reference_value:=q-'reason';
 END IF;
 x:=zasp_temporal74.start_identity(reference_value);
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||x.organization_id,0));
 SELECT * INTO STRICT r FROM public.zasp_security_agent_runs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id) FOR UPDATE;
 SELECT * INTO STRICT h FROM public.zasp_security_agent_definition_versions WHERE(organization_id,workspace_id,environment_id,definition_id,version)=(x.organization_id,x.workspace_id,x.environment_id,x.definition_id,x.definition_version) FOR SHARE;
 IF (r.definition_id,r.definition_version) IS DISTINCT FROM(x.definition_id,x.definition_version)
 OR x.source_kind NOT IN('manual65','automatic73') OR x.action_key NOT IN('run_test','rerun_test')
 OR h.definition_digest IS DISTINCT FROM digest(convert_to(h.definition::text,'UTF8'),'sha256')
 OR h.definition->'allowed_actions' IS DISTINCT FROM jsonb_build_array(x.action_key)
 OR x.step_id IS DISTINCT FROM public.zasp_discovery_canonical_id(x.organization_id,x.workspace_id,x.environment_id,'security_agent_step',x.run_id||chr(31)||'0')
 OR x.test_run_id IS DISTINCT FROM public.zasp_discovery_canonical_id(x.organization_id,x.workspace_id,x.environment_id,'security_agent_test_run',x.run_id||chr(31)||x.step_id||chr(31)||x.action_key)
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker lifecycle ancestry changed';END IF;
 SELECT * INTO a FROM zasp_authorization80_worker.test_associations WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
 IF a.run_id IS NULL THEN
  IF NOT zasp_temporal74.queued_absent(x.organization_id,x.workspace_id,x.environment_id,x.run_id) OR r.state NOT IN('queued','cancelled') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker lifecycle capture absent';END IF;
  f:=jsonb_build_object('organization_id',x.organization_id,'workspace_id',x.workspace_id,'environment_id',x.environment_id,'run_id',x.run_id,'definition_id',x.definition_id,'definition_version',x.definition_version,'definition_digest',encode(h.definition_digest,'hex'),'source_digest',encode(digest(convert_to((to_jsonb(x)-'transferred_at')::text,'UTF8'),'sha256'),'hex'),'checks','[]'::jsonb,'session_user',session_user);
 ELSE
  f:=zasp_authorization80_worker.test74_native_facts(true,reference_value,true);
  IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.test_state s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.definition_id,s.definition_version,s.state,s.run_version,s.present)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.definition_id,x.definition_version,r.state,r.version,true)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker lifecycle capture changed';END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM zasp_temporal74.stops WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)) THEN stop_value:=zasp_authorization80_worker.test74_stop_evidence(x.organization_id,x.workspace_id,x.environment_id,x.run_id);END IF;
 IF EXISTS(SELECT 1 FROM zasp_temporal74.parent_receipts WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)) THEN parent_value:=zasp_temporal74.parent_evidence(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id);END IF;
 SELECT to_jsonb(zasp_authorization80_worker.planner_job_digest(to_jsonb(j))) INTO job_value FROM zasp_temporal74.planning_jobs j WHERE(j.organization_id,j.workspace_id,j.environment_id,j.run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id) FOR SHARE;
 SELECT jsonb_build_object('state',v.state,'generation',v.generation,'effect_key',v.effect_key,'input_digest',encode(v.input_digest,'hex'),'snapshot_digest',encode(v.snapshot_digest,'hex')) INTO state_value FROM zasp_temporal74.effects v WHERE(v.organization_id,v.workspace_id,v.environment_id,v.run_id,v.step_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id) FOR SHARE;
 IF phase='recovery_status' THEN f:=f||jsonb_build_object('recovery',zasp_authorization80_worker.test74_recovery_status_facts(reference_value,to_jsonb(r),f));END IF;
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_compensation') OR NOT zasp_temporal74.current_ready() OR NOT zasp_authorization80_worker.catalog_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker lifecycle authority changed';END IF;
 RETURN f||jsonb_build_object('lifecycle_phase',phase,'request_digest',encode(digest(convert_to(q::text,'UTF8'),'sha256'),'hex'),'run_state',r.state,'run_version',r.version,'step_id',x.step_id,'child_run_id',x.test_run_id,'action_key',x.action_key,'job_digest',job_value,'effect',state_value,'stop_digest',encode(digest(convert_to(stop_value::text,'UTF8'),'sha256'),'hex'),'parent_digest',encode(digest(convert_to(parent_value::text,'UTF8'),'sha256'),'hex'));
END $lifecycle_source$;

DO $lifecycle_boundaries$ DECLARE d text;needle text;p record;BEGIN
 d:=pg_get_functiondef('zasp_authorization80_worker.require_test74_completion(text,jsonb)'::regprocedure);
 d:=replace(replace(replace(d,'require_test74_completion','require_test74_lifecycle'),'test74_completion_source','test74_lifecycle_source'),'test74.adapter.','test74.lifecycle.');
 needle:=$old$('complete')$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker lifecycle proof predecessor changed';END IF;
 d:=replace(d,needle,$new$('inspect','cleanup','recovery_status')$new$);
 needle:='RETURNS void';
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker lifecycle return predecessor changed';END IF;
 d:=replace(d,needle,'RETURNS jsonb');
 -- The inherited source is computed once under locks. Its fresh-clock fence
 -- precedes equality and this return, including every recovery-status path.
 needle:=$old$IF proof->'facts' IS DISTINCT FROM source_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker planning source changed';END IF;$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker lifecycle source predecessor changed';END IF;
 EXECUTE replace(d,needle,needle||'RETURN source_value;');
 FOR p IN SELECT * FROM zasp_authorization80_worker.predecessor_functions WHERE signature IN('zasp_temporal74.inspect(jsonb)','zasp_temporal74.cleanup(jsonb)') LOOP
  d:=p.definition;needle:=E'BEGIN\n PERFORM pg_advisory_xact_lock_shared(hashtextextended(''zasp-schema-migrations'',0));\n';
  IF p.owner_name<>'zasp_discovery_authority' OR(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker lifecycle native predecessor changed';END IF;
  IF p.signature='zasp_temporal74.inspect(jsonb)' THEN
   EXECUTE replace(d,'FUNCTION zasp_temporal74.inspect(q jsonb)','FUNCTION zasp_authorization80_worker.test74_inspect(q jsonb)');
   d:=replace(d,needle,needle||$fence$ PERFORM zasp_authorization80_worker.require_test74_lifecycle('inspect',q);$fence$||E'\n');
  ELSE
   d:=replace(d,needle,needle||$fence$ PERFORM zasp_authorization80_worker.require_test74_lifecycle('cleanup',q);$fence$||E'\n');
   needle:='PERFORM zasp_temporal74.plan(request_value)';
   IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker lifecycle planning recovery changed';END IF;
   d:=replace(d,needle,'PERFORM zasp_temporal74.recover_plan(request_value)');
   needle:='PERFORM zasp_temporal74.effect(request_value)';
   IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker lifecycle captured effect changed';END IF;
   d:=replace(d,needle,'PERFORM zasp_authorization80_worker.test74_effect(request_value)');
  END IF;
  EXECUTE d;
 END LOOP;
END $lifecycle_boundaries$;

CREATE FUNCTION zasp_authorization80_worker.test74_recovery_status(q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $status$
DECLARE f jsonb;BEGIN
 f:=zasp_authorization80_worker.require_test74_lifecycle('recovery_status',q);
 RETURN jsonb_build_object('status',f#>'{recovery,status}');
END $status$;

-- Native admissions are provenance, never a cached provider allow. Captures
-- contain no connector configuration, credential reference, or provider body.
INSERT INTO zasp_authorization80_worker.predecessor_functions
 SELECT oid::regprocedure::text,pg_get_functiondef(oid),proowner::regrole::text,COALESCE(proacl::text,'') FROM pg_proc
 WHERE pronamespace='zasp_temporal72'::regnamespace AND proname IN('prepare_page','guard_page_effect','prepare_apply','commit_apply','record_page','settle','finish','scheduled_admit','public_request_sync','public_put_schedule','public_delete_schedule');
INSERT INTO zasp_authorization80_worker.predecessor_functions
 SELECT oid::regprocedure::text,pg_get_functiondef(oid),proowner::regrole::text,COALESCE(proacl::text,'') FROM pg_proc
 WHERE oid IN('zasp_authorization80_temporal.projected72()'::regprocedure,'public.zasp_execution_record_public_mutation(text,text,text,text,text,text,jsonb,jsonb,text,text,bigint,text,text,text)'::regprocedure,'zasp_authorization79.capture()'::regprocedure);
CREATE TABLE zasp_authorization80_worker.discovery_schedule_grants(
 organization_id text NOT NULL,workspace_id text NOT NULL,environment_id text NOT NULL,schedule_id text NOT NULL,version bigint NOT NULL,
 grantor_id text NOT NULL,identity jsonb NOT NULL,provenance jsonb NOT NULL,
 PRIMARY KEY(organization_id,workspace_id,environment_id,schedule_id,version));
CREATE TABLE zasp_authorization80_worker.discovery_associations(
 organization_id text NOT NULL,workspace_id text NOT NULL,environment_id text NOT NULL,job_id text NOT NULL,sync_id text NOT NULL,integration_id text NOT NULL,
 principal_id text NOT NULL,grantor_id text NOT NULL,source_kind text NOT NULL CHECK(source_kind IN('manual','schedule')),
 schedule_id text,schedule_version bigint,admission jsonb NOT NULL,provenance jsonb NOT NULL,deadline timestamptz NOT NULL,credential_facts jsonb NOT NULL,authority_until timestamptz NOT NULL,
 PRIMARY KEY(organization_id,workspace_id,environment_id,job_id),UNIQUE(organization_id,workspace_id,environment_id,sync_id),CHECK((schedule_id IS NULL)=(schedule_version IS NULL)));
CREATE TABLE zasp_authorization80_worker.discovery_state(
 organization_id text NOT NULL,workspace_id text NOT NULL,environment_id text NOT NULL,job_id text NOT NULL,state text NOT NULL,
 present boolean NOT NULL,current_source boolean NOT NULL,deadline timestamptz NOT NULL,authority_until timestamptz NOT NULL,
 PRIMARY KEY(organization_id,workspace_id,environment_id,job_id),
 FOREIGN KEY(organization_id,workspace_id,environment_id,job_id) REFERENCES zasp_authorization80_worker.discovery_associations);
DO $tables$ DECLARE n text;BEGIN
 FOREACH n IN ARRAY ARRAY['discovery_schedule_grants','discovery_associations','discovery_state'] LOOP
  EXECUTE format('ALTER TABLE zasp_authorization80_worker.%I OWNER TO zasp_discovery_authority',n);
  EXECUTE format('ALTER TABLE zasp_authorization80_worker.%I ENABLE ROW LEVEL SECURITY',n);
  EXECUTE format('ALTER TABLE zasp_authorization80_worker.%I FORCE ROW LEVEL SECURITY',n);
  EXECUTE format('CREATE POLICY authority ON zasp_authorization80_worker.%I TO zasp_discovery_authority USING(true) WITH CHECK(true)',n);
  IF n<>'discovery_state' THEN EXECUTE format('CREATE TRIGGER immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON zasp_authorization80_worker.%I FOR EACH STATEMENT EXECUTE FUNCTION zasp_temporal67.immutable()',n);
  ELSE EXECUTE format('CREATE TRIGGER no_truncate BEFORE TRUNCATE ON zasp_authorization80_worker.%I FOR EACH STATEMENT EXECUTE FUNCTION zasp_temporal67.immutable()',n);END IF;
 END LOOP;
END $tables$;
CREATE FUNCTION zasp_authorization80_worker.discovery72_capture_revision() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $revision$
BEGIN
 IF TG_OP<>'UPDATE' OR (OLD.present,OLD.current_source,OLD.deadline,OLD.authority_until,OLD.state IN('admitted','collecting','partial','retryable','complete','applying')) IS DISTINCT FROM (NEW.present,NEW.current_source,NEW.deadline,NEW.authority_until,NEW.state IN('admitted','collecting','partial','retryable','complete','applying')) THEN
  PERFORM zasp_authorization79.touch(CASE WHEN TG_OP='DELETE' THEN OLD.organization_id ELSE NEW.organization_id END);
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $revision$;
CREATE TRIGGER worker_revision BEFORE INSERT OR UPDATE OR DELETE ON zasp_authorization80_worker.discovery_state FOR EACH ROW EXECUTE FUNCTION zasp_authorization80_worker.discovery72_capture_revision();

CREATE FUNCTION zasp_authorization80_worker.discovery72_schedule_identity(s zasp_temporal72.schedules) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public AS $identity$
 SELECT jsonb_build_object('organization_id',s.organization_id,'workspace_id',s.workspace_id,'environment_id',s.environment_id,'schedule_id',s.id,'integration_id',s.integration_id,'cadence_seconds',s.cadence_seconds,'state',s.state,'version',s.version,'anchor_us',floor(extract(epoch FROM s.anchor)*1000000)::bigint,'created_us',floor(extract(epoch FROM s.created_at)*1000000)::bigint,'updated_us',floor(extract(epoch FROM s.updated_at)*1000000)::bigint,'parser_version',s.parser_version,'tool_version',s.tool_version)
$identity$;
CREATE FUNCTION zasp_authorization80_worker.discovery72_admission_identity(r zasp_temporal72.runs) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public AS $identity$
 SELECT jsonb_build_object('organization_id',r.organization_id,'workspace_id',r.workspace_id,'environment_id',r.environment_id,'job_id',r.job_id,'sync_id',r.sync_id,'integration_id',r.integration_id,'schedule_id',r.schedule_id,'scheduled_for_us',floor(extract(epoch FROM r.scheduled_for)*1000000)::bigint,'request_digest',encode(r.request_digest,'hex'),'outbox_id',r.outbox_id,'connection_id',r.connection_id,'provider',r.provider,'integration_version',r.integration_version,'connection_version',r.connection_version,'configuration_digest',encode(r.configuration_digest,'hex'),'credential_digest',encode(digest(convert_to(r.credential_reference,'UTF8'),'sha256'),'hex'),'subject_kind',r.subject_kind,'subject_id',r.subject_id,'admitted_us',floor(extract(epoch FROM r.admitted_at)*1000000)::bigint,'deadline_us',floor(extract(epoch FROM r.deadline)*1000000)::bigint)
$identity$;

CREATE FUNCTION zasp_authorization80_worker.discovery72_credentials(r zasp_temporal72.runs) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $credentials$
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',c.id,'class',c.credential_class,'version',c.version,'status',c.status,'metadata',c.metadata,'rotated_from_id',c.rotated_from_id,'expires_us',floor(extract(epoch FROM c.expires_at)*1000000)::bigint) ORDER BY c.id),'[]'::jsonb) FROM public.zasp_connector_credentials c WHERE(c.organization_id,c.workspace_id,c.environment_id,c.integration_id,c.provider,c.credential_reference)=(r.organization_id,r.workspace_id,r.environment_id,r.integration_id,r.provider,r.credential_reference)
$credentials$;
CREATE FUNCTION zasp_authorization80_worker.discovery72_store_association(r zasp_temporal72.runs,principal text,grantor text,kind text,schedule_version bigint,provenance jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $capture$
DECLARE a zasp_authorization80_worker.discovery_associations%ROWTYPE;credentials jsonb;until_value timestamptz;BEGIN
 IF r.job_id IS NULL OR NOT public.zasp_valid_product_id(principal) OR NOT public.zasp_valid_product_id(grantor) OR provenance IS NULL OR kind NOT IN('manual','schedule')
 OR NOT EXISTS(SELECT 1 FROM public.zasp_discovery_syncs s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.id,s.integration_id,s.request_digest,s.trigger_kind)=(r.organization_id,r.workspace_id,r.environment_id,r.sync_id,r.integration_id,r.request_digest,kind)
 AND s.principal_id=CASE kind WHEN 'manual' THEN grantor ELSE principal END)
 OR NOT EXISTS(SELECT 1 FROM public.zasp_discovery_outbox b WHERE(b.organization_id,b.workspace_id,b.environment_id,b.id,b.topic)=(r.organization_id,r.workspace_id,r.environment_id,r.outbox_id,'discovery-jobs') AND b.payload=jsonb_build_object('organization_id',r.organization_id,'workspace_id',r.workspace_id,'environment_id',r.environment_id,'job_id',r.job_id,'sync_id',r.sync_id,'integration_id',r.integration_id,'request_digest',encode(r.request_digest,'hex')) AND b.payload_digest=digest(convert_to(b.payload::text,'UTF8'),'sha256'))
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery admission provenance rejected';END IF;
 credentials:=zasp_authorization80_worker.discovery72_credentials(r);
 SELECT LEAST(r.deadline,min(c.expires_at)) INTO until_value FROM public.zasp_connector_credentials c WHERE(c.organization_id,c.workspace_id,c.environment_id,c.integration_id,c.provider,c.credential_reference)=(r.organization_id,r.workspace_id,r.environment_id,r.integration_id,r.provider,r.credential_reference);
 a:=(r.organization_id,r.workspace_id,r.environment_id,r.job_id,r.sync_id,r.integration_id,principal,grantor,kind,r.schedule_id,schedule_version,zasp_authorization80_worker.discovery72_admission_identity(r),provenance,r.deadline,credentials,until_value);
 INSERT INTO zasp_authorization80_worker.discovery_associations SELECT a.* ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.discovery_associations old WHERE old=a) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='discovery captured admission changed';END IF;
 INSERT INTO zasp_authorization80_worker.discovery_state VALUES(r.organization_id,r.workspace_id,r.environment_id,r.job_id,r.state,true,true,r.deadline,until_value) ON CONFLICT DO NOTHING;
END $capture$;

CREATE FUNCTION zasp_authorization80_worker.discovery72_capture_mutation(v public.zasp_workflow_idempotency) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $mutation$
DECLARE audit public.zasp_workflow_audit%ROWTYPE;s zasp_temporal72.schedules%ROWTYPE;r zasp_temporal72.runs%ROWTYPE;body jsonb;proof jsonb;g zasp_authorization80_worker.discovery_schedule_grants%ROWTYPE;BEGIN
 IF v.operation NOT IN('syncIntegration','putIntegrationSchedule') THEN RETURN;END IF;
 SELECT * INTO STRICT audit FROM public.zasp_workflow_audit a WHERE(a.organization_id,a.workspace_id,a.environment_id,a.audit_id,a.correlation_id,a.principal_id,a.operation)=(v.organization_id,v.workspace_id,v.environment_id,v.response->>'audit_id',v.response->>'correlation_id',v.principal_id,v.operation);
 body:=v.response->'body';
 IF body IS NULL OR jsonb_typeof(body)<>'object' OR audit.resource_version IS DISTINCT FROM(v.response->>'version')::bigint THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery mutation receipt rejected';END IF;
 proof:=jsonb_build_object('audit_id',audit.audit_id,'audit_digest',encode(digest(convert_to(jsonb_build_array(audit.organization_id,audit.workspace_id,audit.environment_id,audit.audit_id,audit.correlation_id,audit.principal_id,audit.operation,audit.resource_kind,audit.resource_id,audit.resource_version)::text,'UTF8'),'sha256'),'hex'),'idempotency_key',v.idempotency_key,'request_digest',encode(v.request_digest,'hex'),'response_digest',encode(digest(convert_to(v.response::text,'UTF8'),'sha256'),'hex'));
 IF v.operation='putIntegrationSchedule' THEN
  SELECT * INTO STRICT s FROM zasp_temporal72.schedules WHERE(organization_id,workspace_id,environment_id,integration_id)=(v.organization_id,v.workspace_id,v.environment_id,audit.resource_id);
  IF audit.resource_kind<>'integration_schedule' OR body->>'integration_id' IS DISTINCT FROM s.integration_id OR(body->>'version')::bigint IS DISTINCT FROM s.version OR(body->>'cadence_seconds')::integer IS DISTINCT FROM s.cadence_seconds OR body->>'state' IS DISTINCT FROM s.state OR(body->>'created_at')::timestamptz IS DISTINCT FROM s.created_at OR(body->>'updated_at')::timestamptz IS DISTINCT FROM s.updated_at OR s.state='enabled' AND(body->>'next_run_at')::timestamptz IS DISTINCT FROM s.anchor THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery schedule provenance prerequisite';END IF;
  g:=(s.organization_id,s.workspace_id,s.environment_id,s.id,s.version,v.principal_id,zasp_authorization80_worker.discovery72_schedule_identity(s),proof);
  INSERT INTO zasp_authorization80_worker.discovery_schedule_grants SELECT g.* ON CONFLICT DO NOTHING;
  IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.discovery_schedule_grants old WHERE old=g) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='discovery schedule provenance changed';END IF;
 ELSE
  SELECT * INTO STRICT r FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,sync_id)=(v.organization_id,v.workspace_id,v.environment_id,audit.resource_id);
  IF audit.resource_kind<>'integration_sync' OR body->>'id' IS DISTINCT FROM r.sync_id OR body->>'integration_id' IS DISTINCT FROM r.integration_id OR r.schedule_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public.zasp_discovery_syncs y WHERE(y.organization_id,y.workspace_id,y.environment_id,y.id,y.principal_id,y.idempotency_key,y.trigger_kind)=(r.organization_id,r.workspace_id,r.environment_id,r.sync_id,v.principal_id,v.idempotency_key,'manual')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery manual provenance prerequisite';END IF;
  PERFORM zasp_authorization80_worker.discovery72_store_association(r,public.zasp_discovery_canonical_id(r.organization_id,r.workspace_id,r.environment_id,'discovery_sync_service',r.sync_id),v.principal_id,'manual',NULL,proof);
 END IF;
END $mutation$;
CREATE FUNCTION zasp_authorization80_worker.discovery72_mutation_capture() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $trigger$
BEGIN
 IF NEW.operation NOT IN('syncIntegration','putIntegrationSchedule') THEN RETURN NULL;END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_temporal72.principals WHERE principal_name=session_user AND authority_role='zasp_discovery_api') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery provenance API session rejected';END IF;
 PERFORM zasp_authorization80_worker.discovery72_human_capture(NEW);
 PERFORM zasp_authorization80_worker.discovery72_capture_mutation(NEW);RETURN NULL;
END $trigger$;
CREATE TRIGGER zasp_authorization80_worker_discovery_admission AFTER INSERT ON public.zasp_workflow_idempotency FOR EACH ROW EXECUTE FUNCTION zasp_authorization80_worker.discovery72_mutation_capture();

CREATE FUNCTION zasp_authorization80_worker.discovery72_capture_scheduled(o text,w text,e text,j text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $scheduled$
DECLARE r zasp_temporal72.runs%ROWTYPE;s zasp_temporal72.schedules%ROWTYPE;g zasp_authorization80_worker.discovery_schedule_grants%ROWTYPE;BEGIN
 SELECT * INTO STRICT r FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j);
 SELECT * INTO STRICT s FROM zasp_temporal72.schedules WHERE(organization_id,workspace_id,environment_id,id,integration_id)=(o,w,e,r.schedule_id,r.integration_id);
 SELECT * INTO STRICT g FROM zasp_authorization80_worker.discovery_schedule_grants WHERE(organization_id,workspace_id,environment_id,schedule_id,version)=(o,w,e,s.id,s.version);
 IF s.state<>'enabled' OR s.updated_at>r.admitted_at OR r.scheduled_for<s.anchor OR g.identity IS DISTINCT FROM zasp_authorization80_worker.discovery72_schedule_identity(s) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery scheduled provenance prerequisite';END IF;
 PERFORM zasp_authorization80_worker.discovery72_store_association(r,s.id,g.grantor_id,'schedule',s.version,g.provenance);
END $scheduled$;

CREATE FUNCTION zasp_authorization80_worker.discovery72_capture_source() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $capture_source$
DECLARE old_value jsonb:=to_jsonb(OLD);new_value jsonb:=CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW) END;keys text[];BEGIN
 IF TG_TABLE_SCHEMA='zasp_temporal72' AND TG_TABLE_NAME='runs' THEN
  IF TG_OP='DELETE' THEN UPDATE zasp_authorization80_worker.discovery_state SET present=false WHERE(organization_id,workspace_id,environment_id,job_id)=(OLD.organization_id,OLD.workspace_id,OLD.environment_id,OLD.job_id);
  ELSE UPDATE zasp_authorization80_worker.discovery_state SET state=NEW.state,current_source=current_source AND zasp_authorization80_worker.discovery72_admission_identity(OLD)=zasp_authorization80_worker.discovery72_admission_identity(NEW) WHERE(organization_id,workspace_id,environment_id,job_id)=(OLD.organization_id,OLD.workspace_id,OLD.environment_id,OLD.job_id);END IF;
 ELSIF TG_TABLE_SCHEMA='zasp_temporal72' AND TG_TABLE_NAME='schedules' THEN
  IF TG_OP='DELETE' OR zasp_authorization80_worker.discovery72_schedule_identity(OLD) IS DISTINCT FROM zasp_authorization80_worker.discovery72_schedule_identity(NEW) THEN
   UPDATE zasp_authorization80_worker.discovery_state st SET current_source=false FROM zasp_authorization80_worker.discovery_associations a WHERE(st.organization_id,st.workspace_id,st.environment_id,st.job_id)=(a.organization_id,a.workspace_id,a.environment_id,a.job_id) AND(a.organization_id,a.workspace_id,a.environment_id,a.schedule_id)=(OLD.organization_id,OLD.workspace_id,OLD.environment_id,OLD.id);
  END IF;
 ELSE
  keys:=CASE TG_TABLE_NAME WHEN 'zasp_integrations' THEN ARRAY['organization_id','workspace_id','environment_id','id','kind','version','configuration','state','deleted_at'] WHEN 'zasp_integration_connections' THEN ARRAY['organization_id','workspace_id','environment_id','integration_id','id','provider','version','connection_reference','state','revoked_at'] WHEN 'zasp_discovery_connection_subjects' THEN ARRAY['organization_id','workspace_id','environment_id','integration_id','connection_id','provider','subject_kind','subject_id','connection_version','configuration_digest'] ELSE ARRAY['organization_id','workspace_id','environment_id','integration_id','id','provider','version','credential_class','credential_reference','status','metadata','expires_at','rotated_from_id'] END;
  IF TG_OP='DELETE' OR EXISTS(SELECT 1 FROM unnest(keys) k WHERE old_value->k IS DISTINCT FROM new_value->k) THEN
   UPDATE zasp_authorization80_worker.discovery_state st SET current_source=false FROM zasp_authorization80_worker.discovery_associations a WHERE(st.organization_id,st.workspace_id,st.environment_id,st.job_id)=(a.organization_id,a.workspace_id,a.environment_id,a.job_id) AND(a.organization_id,a.workspace_id,a.environment_id,a.integration_id)=(old_value->>'organization_id',old_value->>'workspace_id',old_value->>'environment_id',CASE WHEN TG_TABLE_NAME='zasp_integrations' THEN old_value->>'id' ELSE old_value->>'integration_id' END);
  END IF;
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $capture_source$;
DO $triggers$ DECLARE relation regclass;BEGIN
 FOREACH relation IN ARRAY ARRAY['zasp_temporal72.runs'::regclass,'zasp_temporal72.schedules'::regclass,'public.zasp_integrations'::regclass,'public.zasp_integration_connections'::regclass,'public.zasp_discovery_connection_subjects'::regclass,'public.zasp_connector_credentials'::regclass] LOOP
  EXECUTE format('CREATE TRIGGER zasp_authorization80_worker_discovery_source BEFORE UPDATE OR DELETE ON %s FOR EACH ROW EXECUTE FUNCTION zasp_authorization80_worker.discovery72_capture_source()',relation);
  EXECUTE format('CREATE TRIGGER zasp_authorization80_worker_discovery_no_truncate BEFORE TRUNCATE ON %s FOR EACH STATEMENT EXECUTE FUNCTION zasp_temporal67.immutable()',relation);
 END LOOP;
END $triggers$;

CREATE FUNCTION zasp_authorization80_worker.expire_discovery72(o text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $expiry$
BEGIN
 IF NOT zasp_authorization79.worker() OR NOT zasp_authorization79.locked(o) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery expiry session rejected';END IF;
 UPDATE zasp_authorization80_worker.discovery_state SET current_source=false WHERE organization_id=o AND current_source AND authority_until<=clock_timestamp();
END $expiry$;

-- Backfill only exact retained native evidence. No fabricated owner/delegation.
DO $backfill$ DECLARE v public.zasp_workflow_idempotency%ROWTYPE;s zasp_temporal72.schedules%ROWTYPE;r zasp_temporal72.runs%ROWTYPE;count_value integer;BEGIN
 FOR s IN SELECT * FROM zasp_temporal72.schedules WHERE state='enabled' LOOP
  SELECT count(*) INTO count_value FROM public.zasp_workflow_idempotency i JOIN public.zasp_workflow_audit a ON(a.organization_id,a.audit_id)=(i.organization_id,i.response->>'audit_id') WHERE(i.organization_id,i.workspace_id,i.environment_id,i.operation,a.resource_id,a.resource_version)=(s.organization_id,s.workspace_id,s.environment_id,'putIntegrationSchedule',s.integration_id,s.version);
  IF count_value<>1 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery schedule provenance prerequisite';END IF;
  SELECT i.* INTO STRICT v FROM public.zasp_workflow_idempotency i JOIN public.zasp_workflow_audit a ON(a.organization_id,a.audit_id)=(i.organization_id,i.response->>'audit_id') WHERE(i.organization_id,i.workspace_id,i.environment_id,i.operation,a.resource_id,a.resource_version)=(s.organization_id,s.workspace_id,s.environment_id,'putIntegrationSchedule',s.integration_id,s.version);
  PERFORM zasp_authorization80_worker.discovery72_capture_mutation(v);
 END LOOP;
 -- Terminal native runs also need immutable provenance for retained Activity
 -- receipt/cleanup retries. Missing proof is an installation gate, not a
 -- silent loss of recovery; active_discovery never delegates terminal work.
 FOR r IN SELECT * FROM zasp_temporal72.runs LOOP
  IF r.schedule_id IS NOT NULL THEN PERFORM zasp_authorization80_worker.discovery72_capture_scheduled(r.organization_id,r.workspace_id,r.environment_id,r.job_id);
  ELSE
   SELECT i.* INTO STRICT v FROM public.zasp_workflow_idempotency i JOIN public.zasp_workflow_audit a ON(a.organization_id,a.audit_id)=(i.organization_id,i.response->>'audit_id') WHERE(i.organization_id,i.workspace_id,i.environment_id,i.operation,a.resource_id)=(r.organization_id,r.workspace_id,r.environment_id,'syncIntegration',r.sync_id);
   PERFORM zasp_authorization80_worker.discovery72_capture_mutation(v);
  END IF;
 END LOOP;
END $backfill$;

CREATE VIEW zasp_authorization80_worker.active_discovery AS
 SELECT a.* FROM zasp_authorization80_worker.discovery_associations a JOIN zasp_authorization80_worker.discovery_state s USING(organization_id,workspace_id,environment_id,job_id)
 JOIN public.zasp_identity_memberships m ON(m.organization_id,m.principal_id)=(a.organization_id,a.grantor_id)
 WHERE m.active AND s.present AND s.current_source AND s.authority_until>clock_timestamp() AND s.state IN('admitted','collecting','partial','retryable','complete','applying');
ALTER VIEW zasp_authorization80_worker.active_discovery OWNER TO zasp_discovery_authority;
DO $views$ DECLARE d text;BEGIN
 SELECT pg_get_viewdef('zasp_authorization79.members'::regclass) INTO d;
 EXECUTE 'CREATE OR REPLACE VIEW zasp_authorization79.members AS '||rtrim(d,E';\n ')||' UNION SELECT organization_id,''service''::text,principal_id,''''::text FROM zasp_authorization80_worker.active_discovery';
 SELECT pg_get_viewdef('zasp_authorization79.current_grants'::regclass) INTO d;
 EXECUTE 'CREATE OR REPLACE VIEW zasp_authorization79.current_grants AS SELECT g.* FROM ('||rtrim(d,E';\n ')||$grants$) g WHERE NOT(g.principal_kind='service' AND EXISTS(SELECT 1 FROM zasp_authorization80_worker.discovery_associations a WHERE(a.organization_id,a.workspace_id,a.environment_id,a.sync_id)=(g.organization_id,g.workspace_id,g.environment_id,g.task_id)))
 UNION SELECT a.organization_id,a.workspace_id,a.environment_id,'integration'::text,a.integration_id,'service'::text,a.principal_id,p.permission,a.sync_id FROM zasp_authorization80_worker.active_discovery a CROSS JOIN(VALUES('manage_workflows'::text),('view'::text)) p(permission)$grants$;
END $views$;

-- The current human proof is checked before entering retained native mutation.
-- The private marker authenticates only this transaction's exact invocation,
-- not arbitrary caller-selected revision increases or later raw DML.
CREATE FUNCTION zasp_authorization80_worker.discovery72_human_clear() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $clear$
BEGIN
 PERFORM set_config('zasp.discovery72_human','',true);PERFORM set_config('zasp.discovery72_human_seal','',true);
END $clear$;
CREATE FUNCTION zasp_authorization80_worker.discovery72_human_marker() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $marker$
DECLARE m jsonb;p jsonb;seal text;expected_seal text;BEGIN
 m:=NULLIF(current_setting('zasp.discovery72_human',true),'')::jsonb;p:=zasp_authorization80.context();
 seal:=NULLIF(current_setting('zasp.discovery72_human_seal',true),'');expected_seal:=zasp_authorization80.context_seal(m);
 IF m IS NULL OR p IS NULL OR m->>'domain' IS DISTINCT FROM 'discovery72-human-v1'
 OR seal IS NULL OR expected_seal IS NULL OR seal IS DISTINCT FROM expected_seal
 OR m->>'proof_digest' IS DISTINCT FROM encode(digest(convert_to(p::text,'UTF8'),'sha256'),'hex')
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery human invocation rejected';END IF;
 RETURN m;
EXCEPTION WHEN data_exception THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery human invocation rejected';
END $marker$;
CREATE FUNCTION zasp_authorization80_worker.discovery72_human_save(m jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $save$
BEGIN
 PERFORM set_config('zasp.discovery72_human',m::text,true);PERFORM set_config('zasp.discovery72_human_seal',zasp_authorization80.context_seal(m),true);
END $save$;
CREATE FUNCTION zasp_authorization80_worker.discovery72_human_check(m jsonb,delta bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $check$
DECLARE p jsonb:=zasp_authorization80.context();target_version bigint;BEGIN
 IF current_setting('transaction_isolation')<>'read committed' OR NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal72.current_ready()
 OR p IS NULL OR NOT EXISTS(SELECT 1 FROM zasp_temporal72.principals WHERE authority_role='zasp_discovery_api' AND principal_name=session_user)
 OR NOT COALESCE(zasp_authorization80.read_request(m->>'organization_id',m->>'workspace_id',m->>'environment_id',ARRAY[m->>'operation'],'manage_workflows',false,m->>'actor')
 AND NOT(p->>'collection')::boolean AND p#>>'{path_parameters,id}'=m->>'integration_id'
 AND zasp_authorization80.allowed(m->>'organization_id',m->>'workspace_id',m->>'environment_id','integration',m->>'integration_id'),false)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery current human authority required';END IF;
 -- The initial fence owns this revision row. Every later check admits only
 -- the measured local mutation delta, with all other pins unchanged.
 PERFORM 1 FROM zasp_authorization79.organizations x WHERE x.organization_id=m->>'organization_id'
 AND(x.desired,x.applied,x.generation,x.store_id,x.model_id)=((p#>>'{revision,desired}')::bigint+delta,(p#>>'{revision,applied}')::bigint,(p#>>'{revision,generation}')::bigint,p#>>'{revision,store_id}',p#>>'{revision,model_id}') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='discovery human revision changed';END IF;
 SELECT version INTO target_version FROM public.zasp_integrations WHERE(organization_id,workspace_id,environment_id,id)=(m->>'organization_id',m->>'workspace_id',m->>'environment_id',m->>'integration_id') AND deleted_at IS NULL AND state<>'deleted' FOR SHARE;
 IF target_version IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'targets') t WHERE(t->>'organization_id',t->>'workspace_id',t->>'environment_id',t->>'kind',COALESCE(NULLIF(t->>'source_id',''),t->>'id'),(t->>'version')::bigint)=(m->>'organization_id',m->>'workspace_id',m->>'environment_id','integration',m->>'integration_id',target_version)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='discovery human target changed';END IF;
 PERFORM zasp_authorization80.identity_fence(p);
 IF zasp_authorization80.context() IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery human proof expired';END IF;
END $check$;
CREATE FUNCTION zasp_authorization80_worker.discovery72_human_replay() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $replay$
DECLARE m jsonb:=zasp_authorization80_worker.discovery72_human_marker();BEGIN
 IF m->>'stage' IS DISTINCT FROM 'entry' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery replay invocation rejected';END IF;
 PERFORM zasp_authorization80_worker.discovery72_human_check(m,0);
 PERFORM zasp_authorization80_worker.discovery72_human_clear();
END $replay$;
CREATE FUNCTION zasp_authorization80_worker.discovery72_human_begin(op text,o text,w text,e text,actor text,i text,k text,a text,c text,receipt text,request jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $begin$
DECLARE p jsonb:=zasp_authorization80.context();m jsonb;delta bigint:=0;s record;BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF op NOT IN('syncIntegration','putIntegrationSchedule','deleteIntegrationSchedule') OR p IS NULL OR NULLIF(current_setting('zasp.discovery72_human',true),'') IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery human entry rejected';END IF;
 m:=jsonb_build_object('domain','discovery72-human-v1','stage','entry','key_version',p->>'key_version','proof_digest',encode(digest(convert_to(p::text,'UTF8'),'sha256'),'hex'),'organization_id',o,'workspace_id',w,'environment_id',e,'actor',actor,'integration_id',i,'operation',op,'idempotency_key',k,'audit_id',a,'correlation_id',c,'receipt_id',receipt,'request',request);
 PERFORM zasp_authorization80_worker.discovery72_human_check(m,0);
 IF op='syncIntegration' THEN delta:=1;
 ELSE
  -- Prelock every affected capture under the held org revision. Already-false
  -- rows remain false and capture_revision does not touch for those updates.
  FOR s IN SELECT st.* FROM zasp_authorization80_worker.discovery_state st JOIN zasp_authorization80_worker.discovery_associations x USING(organization_id,workspace_id,environment_id,job_id)
   JOIN zasp_temporal72.schedules n ON(n.organization_id,n.workspace_id,n.environment_id,n.id)=(x.organization_id,x.workspace_id,x.environment_id,x.schedule_id)
   WHERE(n.organization_id,n.workspace_id,n.environment_id,n.integration_id)=(o,w,e,i) ORDER BY st.job_id FOR UPDATE OF st LOOP
   IF s.current_source THEN delta:=delta+1;END IF;
  END LOOP;
 END IF;
 PERFORM zasp_authorization80_worker.discovery72_human_check(m,0);
 PERFORM zasp_authorization80_worker.discovery72_human_save(m||jsonb_build_object('mutation_delta',delta));
END $begin$;
CREATE FUNCTION zasp_authorization80_worker.discovery72_human_capture(v public.zasp_workflow_idempotency) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $capture$
DECLARE m jsonb:=zasp_authorization80_worker.discovery72_human_marker();BEGIN
 IF m->>'stage' IS DISTINCT FROM 'recording' OR(v.organization_id,v.workspace_id,v.environment_id,v.principal_id,v.operation,v.idempotency_key) IS DISTINCT FROM(m->>'organization_id',m->>'workspace_id',m->>'environment_id',m->>'actor',m->>'operation',m->>'idempotency_key')
 OR encode(v.request_digest,'hex') IS DISTINCT FROM m->>'intent_digest' OR encode(digest(convert_to(v.response::text,'UTF8'),'sha256'),'hex') IS DISTINCT FROM m->>'response_digest'
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery live capture invocation rejected';END IF;
 PERFORM zasp_authorization80_worker.discovery72_human_check(m,(m->>'mutation_delta')::bigint);
END $capture$;
CREATE FUNCTION zasp_authorization80_worker.discovery72_record_public_mutation(o text,w text,e text,actor text,op text,k text,intent jsonb,body jsonb,kind text,id text,version_value bigint,a text,c text,receipt text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $record$
DECLARE m jsonb:=zasp_authorization80_worker.discovery72_human_marker();result jsonb;response jsonb;delta bigint;BEGIN
 IF m->>'stage' IS DISTINCT FROM 'entry' OR(o,w,e,actor,op,k,a,c,receipt) IS DISTINCT FROM(m->>'organization_id',m->>'workspace_id',m->>'environment_id',m->>'actor',m->>'operation',m->>'idempotency_key',m->>'audit_id',m->>'correlation_id',m->>'receipt_id')
 OR intent->'scope' IS DISTINCT FROM jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e)
 OR(intent->>'integration_id',intent->>'idempotency_key',intent->'expected_version') IS DISTINCT FROM(m->>'integration_id',k,m#>'{request,expected}')
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery mutation invocation rejected';END IF;
 IF op='syncIntegration' THEN
  IF kind<>'integration_sync' OR id IS DISTINCT FROM m#>>'{request,sync_id}' OR body->>'id' IS DISTINCT FROM id OR intent->'body' IS DISTINCT FROM '{}'::jsonb
  OR NOT EXISTS(SELECT 1 FROM zasp_temporal72.runs r WHERE(r.organization_id,r.workspace_id,r.environment_id,r.job_id,r.sync_id,r.integration_id,r.outbox_id,encode(r.request_digest,'hex'))=(o,w,e,m#>>'{request,job_id}',id,m->>'integration_id',m#>>'{request,outbox_id}',m#>>'{request,request_digest}')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery manual invocation changed';END IF;
 ELSE
  IF kind<>'integration_schedule' OR id IS DISTINCT FROM m->>'integration_id' OR body->>'integration_id' IS DISTINCT FROM id OR version_value IS DISTINCT FROM(m#>>'{request,expected}')::bigint+1
  OR(op='putIntegrationSchedule' AND intent->'body' IS DISTINCT FROM jsonb_build_object('cadence_seconds',m#>'{request,cadence}','state',m#>'{request,state}')) OR(op='deleteIntegrationSchedule' AND intent->'body' IS DISTINCT FROM '{}'::jsonb)
  THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery schedule invocation changed';END IF;
 END IF;
 delta:=(m->>'mutation_delta')::bigint;PERFORM zasp_authorization80_worker.discovery72_human_check(m,delta);
 response:=jsonb_build_object('body',body,'version',version_value,'audit_id',a,'correlation_id',c,'receipt_id',receipt);
 m:=m||jsonb_build_object('stage','recording','intent_digest',encode(digest(convert_to(intent::text,'UTF8'),'sha256'),'hex'),'response_digest',encode(digest(convert_to(response::text,'UTF8'),'sha256'),'hex'));
 PERFORM zasp_authorization80_worker.discovery72_human_save(m);
 result:=public.zasp_execution_record_public_mutation(o,w,e,actor,op,k,intent,body,kind,id,version_value,a,c,receipt);
 PERFORM zasp_authorization80_worker.discovery72_human_check(m,delta+CASE WHEN op='syncIntegration' THEN 1 ELSE 0 END);
 IF result-'replayed' IS DISTINCT FROM response OR result->'replayed' IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery mutation receipt changed';END IF;
 PERFORM zasp_authorization80_worker.discovery72_human_clear();RETURN result;
END $record$;

-- Discovery roles are distinct from executor/adapter roles. Capture recovery
-- uses only the already registered compensation session and purpose.
CREATE FUNCTION zasp_authorization80_worker.discovery72_role(compensation boolean) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $role$
BEGIN
 IF compensation IS NULL OR current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='discovery worker isolation rejected';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal72.current_ready() THEN RETURN false;END IF;
 RETURN CASE WHEN compensation THEN zasp_temporal68.principal_ready('zasp_temporal_compensation') ELSE EXISTS(SELECT 1 FROM zasp_temporal72.principals WHERE principal_name=session_user AND authority_role='zasp_discovery_worker') END;
END $role$;
CREATE FUNCTION zasp_authorization80_worker.discovery72_key_ready(p text,v text) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $key$
 SELECT COALESCE(p IN('worker-forward','captured-compensation') AND zasp_authorization80_worker.discovery72_role(p='captured-compensation') AND EXISTS(SELECT 1 FROM zasp_authorization80_worker.verifiers WHERE purpose=p AND version=v),false)
$key$;
CREATE FUNCTION zasp_authorization80_worker.discovery72_revision(o text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $revision$
BEGIN
 IF NOT zasp_authorization80_worker.discovery72_role(false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery revision session rejected';END IF;
 RETURN(SELECT jsonb_build_object('organization_id',organization_id,'desired',desired,'applied',applied,'generation',generation,'store_id',store_id,'model_id',model_id) FROM zasp_authorization79.organizations WHERE organization_id=o);
END $revision$;

-- The native wrapper and typed adapter share this canonical request shape.
-- Time is integer microseconds so a session timezone cannot alter a proof.
CREATE FUNCTION zasp_authorization80_worker.discovery72_request(phase text,o text,w text,e text,j text,extra jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $request$
DECLARE a zasp_authorization80_worker.discovery_associations%ROWTYPE;BEGIN
 SELECT * INTO STRICT a FROM zasp_authorization80_worker.discovery_associations WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j);
 RETURN jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'job_id',j,'integration_id',a.integration_id,'input_digest',a.admission->>'request_digest','operation',phase)||extra;
END $request$;
CREATE FUNCTION zasp_authorization80_worker.discovery72_source(phase text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $source$
DECLARE a zasp_authorization80_worker.discovery_associations%ROWTYPE;r zasp_temporal72.runs%ROWTYPE;s zasp_authorization80_worker.discovery_state%ROWTYPE;extra text[];page_value jsonb;apply_value jsonb;wait_value jsonb;compensation boolean:=phase IN('record_page','settle','finish','replay_page','replay_apply');checks jsonb:='[]'::jsonb;BEGIN
 IF phase IS NULL OR phase NOT IN('prepare_page','guard_page','prepare_apply','commit_apply','record_page','settle','finish','replay_page','replay_apply') OR NOT zasp_authorization80_worker.discovery72_role(compensation) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery worker phase/session rejected';END IF;
 extra:=CASE phase WHEN 'prepare_page' THEN ARRAY['budget_us','expected','expected_digest'] WHEN 'replay_page' THEN ARRAY['budget_us','expected','expected_digest'] WHEN 'guard_page' THEN ARRAY['effect_id','budget_us'] WHEN 'prepare_apply' THEN ARRAY['budget_us','complete_receipt'] WHEN 'replay_apply' THEN ARRAY['budget_us','complete_receipt'] WHEN 'commit_apply' THEN ARRAY['effect_id','budget_us'] WHEN 'record_page' THEN ARRAY['effect_id','details'] WHEN 'settle' THEN ARRAY['budget_us','reason','receipt'] WHEN 'finish' THEN ARRAY['outcome','receipt'] END;
 IF q->>'operation' IS DISTINCT FROM phase OR octet_length(q::text)>(CASE WHEN phase='record_page' THEN 67174400 ELSE 4096 END) OR NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','job_id','integration_id','input_digest','operation']||extra) OR EXISTS(SELECT 1 FROM jsonb_each(q) WHERE value='null'::jsonb) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='discovery request rejected';END IF;
 SELECT * INTO a FROM zasp_authorization80_worker.discovery_associations WHERE(organization_id,workspace_id,environment_id,job_id,integration_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'job_id',q->>'integration_id');
 SELECT * INTO r FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,job_id)=(a.organization_id,a.workspace_id,a.environment_id,a.job_id) FOR SHARE;
 SELECT * INTO s FROM zasp_authorization80_worker.discovery_state WHERE(organization_id,workspace_id,environment_id,job_id)=(a.organization_id,a.workspace_id,a.environment_id,a.job_id) FOR SHARE;
 IF a.job_id IS NULL OR r.job_id IS NULL OR s.job_id IS NULL OR NOT s.present OR a.admission IS DISTINCT FROM zasp_authorization80_worker.discovery72_admission_identity(r) OR a.admission->>'request_digest' IS DISTINCT FROM q->>'input_digest' OR s.state IS DISTINCT FROM r.state OR a.deadline IS DISTINCT FROM r.deadline OR q ? 'budget_us' AND q->'budget_us' IS DISTINCT FROM to_jsonb(floor(extract(epoch FROM r.deadline)*1000000)::bigint) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery captured source rejected';END IF;
 IF NOT compensation THEN
  IF NOT s.current_source OR a.authority_until<=clock_timestamp() OR s.authority_until IS DISTINCT FROM a.authority_until OR a.credential_facts IS DISTINCT FROM zasp_authorization80_worker.discovery72_credentials(r) OR r.state NOT IN('admitted','collecting','partial','retryable','complete','applying') OR NOT EXISTS(SELECT 1 FROM public.zasp_identity_memberships WHERE(organization_id,principal_id,active)=(a.organization_id,a.grantor_id,true)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery delegation revoked';END IF;
  PERFORM zasp_temporal72.require_current_run(r,r.deadline);
  IF a.schedule_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM zasp_temporal72.schedules n JOIN zasp_authorization80_worker.discovery_schedule_grants g ON(g.organization_id,g.workspace_id,g.environment_id,g.schedule_id,g.version)=(n.organization_id,n.workspace_id,n.environment_id,n.id,n.version) WHERE(n.organization_id,n.workspace_id,n.environment_id,n.id,n.version,n.state)=(a.organization_id,a.workspace_id,a.environment_id,a.schedule_id,a.schedule_version,'enabled') AND g.identity=zasp_authorization80_worker.discovery72_schedule_identity(n) AND g.provenance=a.provenance) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery schedule delegation changed';END IF;
  checks:=jsonb_build_array(jsonb_build_object('kind','integration','id',a.integration_id,'permission','manage_workflows'),jsonb_build_object('kind','integration','id',a.integration_id,'permission','view'));
 END IF;
 IF phase IN('prepare_page','replay_page') AND(q->>'expected' !~ '^[0-9]+$' OR(q->>'expected')::bigint NOT BETWEEN 0 AND 9999 OR jsonb_typeof(q->'expected_digest') IS DISTINCT FROM 'string') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='discovery checkpoint shape rejected';END IF;
 SELECT jsonb_build_object('effect_id',p.effect_id,'expected',p.expected_version,'expected_digest',p.expected_digest,'record_digest',p.record_digest,'result',p.result) INTO page_value FROM zasp_temporal72.page_effects p WHERE(p.organization_id,p.workspace_id,p.environment_id,p.job_id)=(a.organization_id,a.workspace_id,a.environment_id,a.job_id) AND(CASE WHEN phase IN('prepare_page','replay_page') THEN p.expected_version=(q->>'expected')::bigint ELSE p.effect_id=q->>'effect_id' END) FOR SHARE;
 SELECT jsonb_build_object('effect_id',v.effect_id,'complete_digest',v.complete_digest,'result',v.result) INTO apply_value FROM zasp_temporal72.apply_effects v WHERE(v.organization_id,v.workspace_id,v.environment_id,v.job_id)=(a.organization_id,a.workspace_id,a.environment_id,a.job_id) FOR SHARE;
 IF phase IN('prepare_page','replay_page') THEN SELECT jsonb_build_object('expected',v.expected_version,'expected_digest',v.expected_digest,'result',v.result) INTO wait_value FROM zasp_temporal72.page_waits v WHERE(v.organization_id,v.workspace_id,v.environment_id,v.job_id,v.expected_version)=(a.organization_id,a.workspace_id,a.environment_id,a.job_id,(q->>'expected')::bigint) FOR SHARE;END IF;
 IF phase IN('guard_page','record_page') AND page_value IS NULL OR phase='commit_apply' AND(apply_value IS NULL OR apply_value->>'effect_id' IS DISTINCT FROM q->>'effect_id') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery prepared effect absent';END IF;
 -- Native entries are independently callable, so their single fence must
 -- refresh authority after every source lock, not rely on the dispatcher.
 IF NOT compensation AND a.authority_until<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery authority expired after source locks';END IF;
 RETURN jsonb_build_object('organization_id',a.organization_id,'workspace_id',a.workspace_id,'environment_id',a.environment_id,'run_id',a.job_id,'task_id',a.sync_id,'principal_id',a.principal_id,'grantor_id',a.grantor_id,'trigger_kind',a.source_kind,'target_kind','integration','target_id',a.integration_id,'session_user',session_user,'checks',checks,'admission',a.admission,'provenance',a.provenance,'state',r.state,'checkpoint_version',r.checkpoint_version,'checkpoint_digest',r.checkpoint_digest,'page',page_value,'apply',apply_value,'wait',wait_value,'request_digest',encode(digest(convert_to(q::text,'UTF8'),'sha256'),'hex'));
END $source$;
CREATE FUNCTION zasp_authorization80_worker.prepare_discovery72(q jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $prepare$
BEGIN
 -- Capture belongs to the API/admission transaction, never a worker-selected
 -- grantor. This verifies the existing exact capture without issuing input.
 PERFORM zasp_authorization80_worker.discovery72_source(q->>'operation',q);
 IF q->>'operation' NOT IN('prepare_page','prepare_apply') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery preparation phase rejected';END IF;
END $prepare$;

DO $proof$ DECLARE d text;needle text;BEGIN
 SELECT pg_get_functiondef('zasp_authorization80_worker.require_planning78(text,jsonb)'::regprocedure) INTO d;
 d:=replace(replace(replace(d,'require_planning78','require_discovery72'),'planning78_source','discovery72_source'),'finding.planning.','discovery72.');
 needle:=$old$('state','load','prepare','start','result','settle','artifacts','admit','reconcile','late_usage','recovery')$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='discovery proof phases changed';END IF;
 d:=replace(d,needle,$new$('prepare_page','guard_page','prepare_apply','commit_apply','record_page','settle','finish','replay_page','replay_apply')$new$);
 needle:=$old$('reconcile','late_usage','recovery')$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='discovery proof purpose changed';END IF;
 d:=replace(d,needle,$new$('record_page','settle','finish','replay_page','replay_apply')$new$);
 needle:=$old$zasp_temporal68.principal_ready(CASE purpose_value WHEN 'worker-forward' THEN 'zasp_temporal_executor' ELSE 'zasp_temporal_compensation' END)$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='discovery proof principal changed';END IF;
 d:=replace(d,needle,$new$zasp_authorization80_worker.discovery72_role(purpose_value='captured-compensation')$new$);
 -- The shared fence now gives forward and captured calls the same org-first
 -- lock order, then materializes source and rechecks time before equality.
 needle:=$old$ SELECT * INTO revision_value FROM zasp_authorization79.organizations WHERE organization_id=q->>'organization_id' FOR UPDATE;$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 OR strpos(d,needle)>strpos(d,$old$ IF purpose_value='worker-forward' THEN$old$) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='discovery proof organization lock changed';END IF;
 needle:=$old$ source_value:=zasp_authorization80_worker.discovery72_source(phase,q);
 now_ms:=floor(extract(epoch FROM clock_timestamp())*1000)::bigint;
 IF NOT COALESCE((proof->>'issued_at')::bigint<=now_ms+5000 AND(proof->>'expires_at')::bigint>now_ms AND(proof->>'expires_at')::bigint-(proof->>'issued_at')::bigint BETWEEN 1 AND 60000,false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker proof expired after source locks';END IF;
 IF proof->'facts' IS DISTINCT FROM source_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker planning source changed';END IF;$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='discovery proof final source fence changed';END IF;
 EXECUTE d;
END $proof$;

CREATE FUNCTION zasp_authorization80_worker.discovery72_execute(q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $execute$
DECLARE phase text:=q->>'operation';o text:=q->>'organization_id';w text:=q->>'workspace_id';e text:=q->>'environment_id';j text:=q->>'job_id';i text:=q->>'integration_id';d text:=q->>'input_digest';budget timestamptz:=CASE WHEN q ? 'budget_us' THEN timestamptz 'epoch'+(q->>'budget_us')::bigint*interval '1 microsecond' END;p zasp_temporal72.page_effects%ROWTYPE;v zasp_temporal72.page_waits%ROWTYPE;a zasp_temporal72.apply_effects%ROWTYPE;BEGIN
 PERFORM zasp_authorization80_worker.require_discovery72(phase,q);
 CASE phase
 WHEN 'prepare_page' THEN RETURN zasp_temporal72.prepare_page(o,w,e,j,i,d,budget,(q->>'expected')::bigint,q->>'expected_digest');
 WHEN 'guard_page' THEN RETURN to_jsonb(zasp_temporal72.guard_page_effect(o,w,e,j,q->>'effect_id',budget));
 WHEN 'prepare_apply' THEN RETURN zasp_temporal72.prepare_apply(o,w,e,j,i,d,budget,q->>'complete_receipt');
 WHEN 'commit_apply' THEN RETURN zasp_temporal72.commit_apply(o,w,e,j,q->>'effect_id',budget);
 WHEN 'record_page' THEN RETURN zasp_authorization80_worker.discovery72_record_page(o,w,e,j,q->>'effect_id',q->'details');
 WHEN 'settle' THEN RETURN zasp_authorization80_worker.discovery72_settle(o,w,e,j,i,d,budget,q->>'reason',q->>'receipt');
 WHEN 'finish' THEN RETURN zasp_authorization80_worker.discovery72_finish(o,w,e,j,i,d,q->>'outcome',q->>'receipt');
 WHEN 'replay_page' THEN
  SELECT * INTO v FROM zasp_temporal72.page_waits WHERE(organization_id,workspace_id,environment_id,job_id,expected_version)=(o,w,e,j,(q->>'expected')::bigint);
  IF FOUND THEN IF v.expected_digest IS DISTINCT FROM q->>'expected_digest' THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='discovery wait replay conflict';END IF;RETURN jsonb_build_object('found',true,'value',jsonb_build_object('page',v.result));END IF;
  SELECT * INTO p FROM zasp_temporal72.page_effects WHERE(organization_id,workspace_id,environment_id,job_id,expected_version)=(o,w,e,j,(q->>'expected')::bigint);
  IF FOUND THEN IF p.expected_digest IS DISTINCT FROM q->>'expected_digest' THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='discovery page replay conflict';END IF;RETURN jsonb_build_object('found',true,'value',jsonb_build_object('page',COALESCE(p.result,jsonb_build_object('outcome','outcome_unknown'))));END IF;
 WHEN 'replay_apply' THEN
  SELECT * INTO a FROM zasp_temporal72.apply_effects WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j);
  IF FOUND THEN IF a.complete_digest IS DISTINCT FROM q->>'complete_receipt' THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='discovery apply replay conflict';END IF;RETURN jsonb_build_object('found',true,'value',jsonb_build_object('result',COALESCE(a.result,jsonb_build_object('outcome','outcome_unknown'))));END IF;
 ELSE RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery phase closed';
 END CASE;
 RETURN jsonb_build_object('found',false);
END $execute$;

-- Ordered delegation is derived from retained66/65 admission and native61
-- context. Only identifiers, immutable hashes, and an expiry leave this reader.
CREATE TABLE zasp_authorization80_worker.ordered_associations(
 organization_id text NOT NULL,workspace_id text NOT NULL,environment_id text NOT NULL,run_id text NOT NULL,
 principal_id text NOT NULL,grantor_id text NOT NULL,definition_id text NOT NULL,definition_version bigint NOT NULL,
 definition_digest text NOT NULL,source_digest text NOT NULL,test_id text NOT NULL,test_version bigint NOT NULL,
 target_id text NOT NULL,target_kind text NOT NULL CHECK(target_kind IN('agent','tool')),target_digest text NOT NULL,
 trigger_kind text NOT NULL CHECK(trigger_kind IN('finding','attack_path')),trigger_id text NOT NULL,credential_binding_id text NOT NULL,
 snapshot_id text NOT NULL,evidence_id text NOT NULL,integration_id text NOT NULL,source text NOT NULL,
 PRIMARY KEY(organization_id,workspace_id,environment_id,run_id));
CREATE TABLE zasp_authorization80_worker.ordered_state(
 organization_id text NOT NULL,workspace_id text NOT NULL,environment_id text NOT NULL,run_id text NOT NULL,
 definition_id text NOT NULL,definition_version bigint NOT NULL,state text NOT NULL,run_version bigint NOT NULL,present boolean NOT NULL,
 target_current boolean NOT NULL,fresh_until timestamptz NOT NULL,
 PRIMARY KEY(organization_id,workspace_id,environment_id,run_id),
 FOREIGN KEY(organization_id,workspace_id,environment_id,run_id) REFERENCES zasp_authorization80_worker.ordered_associations);
DO $ordered_tables$ DECLARE n text;BEGIN
 FOREACH n IN ARRAY ARRAY['ordered_associations','ordered_state'] LOOP
  EXECUTE format('ALTER TABLE zasp_authorization80_worker.%I OWNER TO zasp_discovery_authority',n);
  EXECUTE format('ALTER TABLE zasp_authorization80_worker.%I ENABLE ROW LEVEL SECURITY',n);
  EXECUTE format('ALTER TABLE zasp_authorization80_worker.%I FORCE ROW LEVEL SECURITY',n);
  EXECUTE format('CREATE POLICY authority ON zasp_authorization80_worker.%I TO zasp_discovery_authority USING(true) WITH CHECK(true)',n);
 END LOOP;
END $ordered_tables$;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON zasp_authorization80_worker.ordered_associations FOR EACH STATEMENT EXECUTE FUNCTION zasp_temporal67.immutable();
CREATE TRIGGER no_truncate BEFORE TRUNCATE ON zasp_authorization80_worker.ordered_state FOR EACH STATEMENT EXECUTE FUNCTION zasp_temporal67.immutable();
CREATE TRIGGER worker_revision AFTER INSERT ON zasp_authorization80_worker.ordered_associations FOR EACH ROW EXECUTE FUNCTION zasp_authorization79.capture('organization_id','organization_id,workspace_id,environment_id,run_id');
CREATE TRIGGER worker_revision AFTER INSERT OR UPDATE OR DELETE ON zasp_authorization80_worker.ordered_state FOR EACH ROW EXECUTE FUNCTION zasp_authorization79.capture('organization_id','organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,state,run_version,present,target_current,fresh_until');

CREATE FUNCTION zasp_authorization80_worker.ordered68_facts(compensation boolean,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public SET timezone='UTC' AS $ordered_facts$
DECLARE x zasp_temporal66.run_owners%ROWTYPE;r public.zasp_security_agent_runs%ROWTYPE;c zasp_temporal65.commands%ROWTYPE;
 tr public.zasp_security_agent_trigger_receipts%ROWTYPE;h public.zasp_security_agent_definition_versions%ROWTYPE;a zasp_authorization80_worker.ordered_associations%ROWTYPE;
 cv jsonb;resolution jsonb;metadata jsonb;checks jsonb;source_hash text;target_hash text;product text;expires timestamptz;k text;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='ordered source requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF compensation IS NULL OR NOT zasp_temporal68.current_ready() OR NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.principal_ready(CASE WHEN compensation THEN 'zasp_temporal_compensation' ELSE 'zasp_temporal_executor' END) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered source principal rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','input_digest']) OR octet_length(q::text)>4096
  OR jsonb_typeof(q->'definition_version') IS DISTINCT FROM 'number' OR NOT COALESCE(q->>'definition_version'~'^([1-9][0-9]{0,5}|1000000)$',false)
  OR jsonb_typeof(q->'input_digest') IS DISTINCT FROM 'string' OR NOT COALESCE(q->>'input_digest'~'^[a-f0-9]{64}$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered start rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered source scope rejected';END IF;
 END LOOP;
 SELECT * INTO x FROM zasp_temporal66.run_owners WHERE(organization_id,workspace_id,environment_id,run_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id') FOR SHARE;
 IF x.run_id IS NULL OR x.execution_owner<>'temporal' OR to_jsonb(x.definition_version) IS DISTINCT FROM q->'definition_version' OR x.input_digest IS DISTINCT FROM q->>'input_digest' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered owner changed';END IF;
 SELECT * INTO r FROM public.zasp_security_agent_runs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id) FOR SHARE;
 IF r.run_id IS NULL OR r.definition_version<>x.definition_version OR r.lease_owner IS NOT NULL OR r.lease_token IS NOT NULL OR r.lease_expires_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered parent changed';END IF;
 SELECT * INTO c FROM zasp_temporal65.commands WHERE(organization_id,workspace_id,environment_id,run_id,kind)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,'start') FOR SHARE;
 SELECT * INTO tr FROM public.zasp_security_agent_trigger_receipts WHERE(organization_id,workspace_id,environment_id,run_id,definition_id,trigger_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,r.definition_id,r.trigger_id) FOR SHARE;
 IF c.run_id IS NULL OR c.execution_owner<>'temporal' OR(c.definition_version,c.input_digest) IS DISTINCT FROM(x.definition_version,x.input_digest)
  OR tr.run_id IS NULL OR encode(tr.trigger_digest,'hex') IS DISTINCT FROM x.input_digest OR tr.trigger_kind NOT IN('finding','attack_path')
  OR r.run_id IS DISTINCT FROM public.zasp_discovery_canonical_id(x.organization_id,x.workspace_id,x.environment_id,'security_agent_run',r.definition_id||chr(31)||r.trigger_id||chr(31)||tr.trigger_version::text) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered retained start changed';END IF;
 SELECT * INTO h FROM public.zasp_security_agent_definition_versions WHERE(organization_id,workspace_id,environment_id,definition_id,version)=(r.organization_id,r.workspace_id,r.environment_id,r.definition_id,r.definition_version) FOR SHARE;
 IF h.definition_id IS NULL OR h.definition_digest IS DISTINCT FROM digest(convert_to(h.definition::text,'UTF8'),'sha256') OR h.definition->'allowed_actions' IS DISTINCT FROM '["create_temporary_policy","run_test"]'::jsonb THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered historical definition changed';END IF;
 source_hash:=encode(digest(convert_to(jsonb_build_array(x.execution_owner,r.definition_id,x.definition_version,x.input_digest,c.event_id,tr.trigger_kind,tr.trigger_id,tr.trigger_version,encode(h.definition_digest,'hex'))::text,'UTF8'),'sha256'),'hex');
 SELECT * INTO a FROM zasp_authorization80_worker.ordered_associations WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
 IF compensation THEN
  IF a.run_id IS NULL OR(a.definition_id,a.definition_version,a.definition_digest,a.source_digest) IS DISTINCT FROM(r.definition_id,r.definition_version,encode(h.definition_digest,'hex'),source_hash)
   OR NOT EXISTS(SELECT 1 FROM zasp_temporal68.planning_jobs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered captured planning absent';END IF;
  metadata:=to_jsonb(a);checks:='[]'::jsonb;
 ELSE
  IF r.state NOT IN('queued','planning','waiting_approval') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered task inactive';END IF;
  cv:=zasp_sa_multistep_prior.context(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
  IF cv->'definition' IS DISTINCT FROM h.definition THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered definition binding changed';END IF;
  resolution:=zasp_temporal68.test_target(x.organization_id,x.workspace_id,x.environment_id,cv->'test'->>'target_id',cv->'test'->>'target_kind',cv->'test'->>'definition_id',(cv->'test'->>'version')::bigint);
  SELECT i.product_kind,least(i.fresh_until,b.valid_until) INTO STRICT product,expires FROM public.zasp_inventory_entities i JOIN public.zasp_attack_lab_credential_bindings b ON(b.organization_id,b.workspace_id,b.environment_id,b.binding_id)=(i.organization_id,i.workspace_id,i.environment_id,resolution#>>'{comparison,credential_binding_id}') WHERE(i.organization_id,i.workspace_id,i.environment_id,i.id)=(x.organization_id,x.workspace_id,x.environment_id,cv->'test'->>'target_id') FOR SHARE OF i,b;
  IF product IS NULL OR product NOT IN('agent','tool') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered target kind rejected';END IF;
  IF expires IS NULL OR expires<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered target expired';END IF;
  target_hash:=encode(digest(convert_to(resolution::text,'UTF8'),'sha256'),'hex');
  metadata:=jsonb_build_object('organization_id',x.organization_id,'workspace_id',x.workspace_id,'environment_id',x.environment_id,'run_id',x.run_id,
   'principal_id',public.zasp_discovery_canonical_id(x.organization_id,x.workspace_id,x.environment_id,'security_agent_definition_service',r.definition_id),'grantor_id',r.requested_by,
   'definition_id',r.definition_id,'definition_version',r.definition_version,'definition_digest',encode(h.definition_digest,'hex'),'source_digest',source_hash,
   'test_id',cv->'test'->>'definition_id','test_version',cv->'test'->'version','target_id',cv->'test'->>'target_id','target_kind',product,'target_digest',target_hash,
   'trigger_kind',tr.trigger_kind,'trigger_id',tr.trigger_id,'credential_binding_id',resolution#>>'{comparison,credential_binding_id}',
   'snapshot_id',resolution#>>'{provenance,snapshot_id}','evidence_id',resolution#>>'{provenance,evidence_id}','integration_id',resolution#>>'{provenance,integration_id}','source',resolution#>>'{provenance,source}');
  checks:=jsonb_build_array(jsonb_build_object('kind','security_agent','id',r.definition_id,'permission','manage_workflows'),jsonb_build_object('kind','security_agent_run','id',r.run_id,'permission','manage_workflows'),jsonb_build_object('kind','test','id',cv->'test'->>'definition_id','permission','view'),jsonb_build_object('kind',product,'id',cv->'test'->>'target_id','permission','view'),jsonb_build_object('kind',tr.trigger_kind,'id',tr.trigger_id,'permission','view'));
 END IF;
 RETURN metadata||jsonb_build_object('run_state',r.state,'run_version',r.version,'checks',checks,'session_user',session_user,'fresh_until_ms',CASE WHEN compensation THEN NULL ELSE floor(extract(epoch FROM expires)*1000)::bigint END);
END $ordered_facts$;

CREATE FUNCTION zasp_authorization80_worker.prepare_ordered68(q jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $prepare_ordered$
DECLARE f jsonb;a zasp_authorization80_worker.ordered_associations%ROWTYPE;BEGIN
 f:=zasp_authorization80_worker.ordered68_facts(false,q);
 a:=jsonb_populate_record(NULL::zasp_authorization80_worker.ordered_associations,f);
 INSERT INTO zasp_authorization80_worker.ordered_associations SELECT a.* ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.ordered_associations s WHERE s=a) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered association changed';END IF;
 INSERT INTO zasp_authorization80_worker.ordered_state VALUES(a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.definition_id,a.definition_version,f->>'run_state',(f->>'run_version')::bigint,true,true,to_timestamp((f->>'fresh_until_ms')::numeric/1000)) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.ordered_state s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.definition_id,s.definition_version,s.state,s.run_version,s.present,s.target_current)=(a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.definition_id,a.definition_version,f->>'run_state',(f->>'run_version')::bigint,true,true) AND s.fresh_until>clock_timestamp()) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered capture changed';END IF;
END $prepare_ordered$;
CREATE FUNCTION zasp_authorization80_worker.ordered68_source(compensation boolean,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $ordered_source$
DECLARE f jsonb;a zasp_authorization80_worker.ordered_associations%ROWTYPE;BEGIN
 f:=zasp_authorization80_worker.ordered68_facts(compensation,q);a:=jsonb_populate_record(NULL::zasp_authorization80_worker.ordered_associations,f);
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.ordered_associations s WHERE s=a) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered association missing';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.ordered_state s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.definition_id,s.definition_version,s.state,s.run_version,s.present)=(a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.definition_id,a.definition_version,f->>'run_state',(f->>'run_version')::bigint,true) AND(compensation OR s.target_current AND s.fresh_until>clock_timestamp())) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered state capture changed';END IF;
 RETURN f;
END $ordered_source$;

-- Existing capture functions remain authoritative for their own families.
-- These exact scoped triggers update only already-derived ordered metadata.
CREATE FUNCTION zasp_authorization80_worker.capture_ordered_run() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $run_capture$
BEGIN
 IF TG_OP='DELETE' OR(OLD.organization_id,OLD.workspace_id,OLD.environment_id,OLD.run_id) IS DISTINCT FROM(NEW.organization_id,NEW.workspace_id,NEW.environment_id,NEW.run_id) THEN
  UPDATE zasp_authorization80_worker.ordered_state SET present=false WHERE(organization_id,workspace_id,environment_id,run_id)=(OLD.organization_id,OLD.workspace_id,OLD.environment_id,OLD.run_id);
 ELSE
  UPDATE zasp_authorization80_worker.ordered_state SET definition_id=NEW.definition_id,definition_version=NEW.definition_version,state=NEW.state,run_version=NEW.version,
   target_current=target_current AND(OLD.definition_id,OLD.definition_version,OLD.requested_by,OLD.trigger_id) IS NOT DISTINCT FROM(NEW.definition_id,NEW.definition_version,NEW.requested_by,NEW.trigger_id)
   WHERE(organization_id,workspace_id,environment_id,run_id)=(OLD.organization_id,OLD.workspace_id,OLD.environment_id,OLD.run_id);
 END IF;RETURN NULL;
END $run_capture$;
CREATE TRIGGER zasp_authorization80_worker_ordered_run AFTER UPDATE OR DELETE ON public.zasp_security_agent_runs FOR EACH ROW EXECUTE FUNCTION zasp_authorization80_worker.capture_ordered_run();
CREATE FUNCTION zasp_authorization80_worker.capture_ordered_target() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $target_capture$
DECLARE v jsonb:=to_jsonb(OLD);BEGIN
 IF TG_OP='UPDATE' AND v=to_jsonb(NEW) THEN RETURN NEW;END IF;
 UPDATE zasp_authorization80_worker.ordered_state s SET target_current=false FROM zasp_authorization80_worker.ordered_associations a
 WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id)=(a.organization_id,a.workspace_id,a.environment_id,a.run_id) AND s.target_current
 AND(a.organization_id,a.workspace_id,a.environment_id)=(v->>'organization_id',v->>'workspace_id',v->>'environment_id') AND CASE TG_TABLE_NAME
  WHEN 'zasp_red_team_definitions' THEN a.test_id=v->>'definition_id'
  WHEN 'zasp_inventory_entities' THEN a.target_id=v->>'id'
  WHEN 'zasp_inventory_evidence' THEN a.evidence_id=v->>'id'
  WHEN 'zasp_discovery_snapshots' THEN a.snapshot_id=v->>'id'
  WHEN 'zasp_inventory_source_observations' THEN(a.target_id,a.integration_id,a.source,a.snapshot_id,a.evidence_id)=(v->>'entity_id',v->>'integration_id',v->>'source',v->>'snapshot_id',v->>'evidence_id')
  WHEN 'zasp_attack_lab_credential_bindings' THEN a.credential_binding_id=v->>'binding_id'
  WHEN 'zasp_risk_findings' THEN a.trigger_kind='finding' AND a.trigger_id=v->>'id'
  WHEN 'zasp_risk_attack_paths' THEN a.trigger_kind='attack_path' AND a.trigger_id=v->>'id'
  ELSE false END;
