CREATE OR REPLACE FUNCTION zasp_temporal76.executor74_fingerprint() RETURNS text LANGUAGE sql STABLE SET search_path=pg_catalog,public AS $test_gate$
 SELECT CASE WHEN EXISTS(SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid='zasp_authorization80_worker.catalog_ready()'::regprocedure AND encode(digest(convert_to(p.prosrc,'UTF8'),'sha256'),'hex')='28bc26660db8eae036fd2f36bc215fcf2e27c1aba6d2c7c42d5d6a58e73c5016' AND p.proowner='zasp_discovery_authority'::regrole AND p.prosecdef AND p.provolatile='s' AND l.lanname='sql' AND p.proconfig=ARRAY['search_path=pg_catalog, public'] AND p.proacl::text='{zasp_discovery_authority=X/zasp_discovery_authority}') AND EXISTS(SELECT 1 FROM zasp_authorization80_worker.registration WHERE checksum='5b129ed0592dde0af626a47bb656a572e009c1cefa182293429a454727af7bf9') AND zasp_authorization80_worker.catalog_ready() THEN zasp_authorization80_worker.projected74() ELSE NULL END
