CREATE FUNCTION zasp_authorization80_worker.require_ordered62_approval(q jsonb,current_value boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $approval$
DECLARE p jsonb:=zasp_authorization80.context();o text:=q->>'organization_id';w text:=q->>'workspace_id';e text:=q->>'environment_id';actor text:=q->>'actor_id';
 id_value text:=CASE WHEN q->>'operation'='classify' THEN q->>'resource_id' ELSE q->>'approval_id' END;approval public.zasp_security_agent_approvals%ROWTYPE;authenticated timestamptz;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' OR current_value IS NULL OR p IS NULL
 OR NOT zasp_authorization80_worker.catalog_ready() OR NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_api'),false)
 OR NOT COALESCE((q->>'operation' IN('decide_resource','decide') OR(q->>'operation'='classify' AND q->>'resource_kind'='approval'))
 AND zasp_authorization80.read_request(o,w,e,ARRAY['decideSecurityAgentApproval'],'manage_workflows',true,actor)
 AND p->'collection'='false'::jsonb AND p->'fresh_auth'='true'::jsonb AND p#>>'{path_parameters,id}'=id_value
 AND jsonb_array_length(p->'targets')=1 AND jsonb_array_length(p->'allowed')=1
 AND zasp_authorization80.allowed(o,w,e,'security_agent_approval',id_value),false)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current ordered approval required';END IF;
 IF current_value THEN
  -- The outer entry takes this before budget/admission/run locks. Rechecks
  -- before transition preserve exact current revision, never a tolerated range.
  PERFORM 1 FROM zasp_authorization79.organizations x WHERE x.organization_id=o
   AND(x.desired,x.applied,x.generation,x.store_id,x.model_id)=((p#>>'{revision,desired}')::bigint,(p#>>'{revision,applied}')::bigint,(p#>>'{revision,generation}')::bigint,p#>>'{revision,store_id}',p#>>'{revision,model_id}') FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered approval revision changed';END IF;
 END IF;
 SELECT * INTO approval FROM public.zasp_security_agent_approvals WHERE(organization_id,workspace_id,environment_id,approval_id)=(o,w,e,id_value) FOR SHARE;
 IF NOT FOUND OR(q->>'operation'='decide' AND q->>'run_id' IS DISTINCT FROM approval.run_id)
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'targets') t WHERE(t->>'organization_id',t->>'workspace_id',t->>'environment_id',t->>'kind',t->>'id',COALESCE(NULLIF(t->>'source_id',''),t->>'id'))=(o,w,e,'security_agent_approval',id_value,id_value)
 AND(NOT current_value OR(t->>'version')::bigint=approval.version))
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered approval target changed';END IF;
 PERFORM zasp_authorization80.identity_fence(p);
 IF q->>'operation'<>'classify' THEN
  SELECT authenticated_at INTO authenticated FROM public.zasp_product_sessions WHERE(session_id,token_digest)=(p->>'credential_id',decode(p->>'credential_digest','hex'));
  IF authenticated IS NULL OR jsonb_typeof(q->'fresh_auth_at') IS DISTINCT FROM 'string' OR(q->>'fresh_auth_at')::timestamptz IS DISTINCT FROM authenticated THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered approval freshness changed';END IF;
 END IF;
 -- Nested transition may wait after the pre-write check. Expiry here rolls
 -- back all local writes; no provider or gateway IO occurs in this transaction.
 IF p IS DISTINCT FROM zasp_authorization80.context() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered approval proof expired';END IF;
END $approval$;

CREATE FUNCTION zasp_authorization80_worker.ordered62_replace(d text,needle text,replacement text) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public AS $replace$
BEGIN
 IF d IS NULL OR needle IS NULL OR length(needle)=0 OR replacement IS NULL OR(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='ordered62 predecessor changed';END IF;
 RETURN replace(d,needle,replacement);
END $replace$;

DO $ordered_human$ DECLARE d text;needle text;guard text;BEGIN
 SELECT definition INTO STRICT d FROM zasp_authorization80_worker.predecessor_functions WHERE signature='zasp_ordered_public62.api(text,text,jsonb)' AND owner_name='zasp_discovery_authority' AND acl='{zasp_discovery_authority=X/zasp_discovery_authority,zasp_security_agent_api=X/zasp_discovery_authority}';
 guard:=$gate$ IF op IN('decide_resource','decide') OR(op='classify' AND q->>'resource_kind'='approval') THEN PERFORM zasp_authorization80_worker.require_ordered62_approval(q,true);END IF;$gate$;
 needle:=$lock$ PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));$lock$;
 d:=zasp_authorization80_worker.ordered62_replace(d,needle,guard||E'\n'||needle);
 needle:=' RETURN result_value;';
 d:=zasp_authorization80_worker.ordered62_replace(d,needle,replace(guard,'(q,true)','(q,false)')||E'\n'||needle);
 EXECUTE d;
 SELECT definition INTO STRICT d FROM zasp_authorization80_worker.predecessor_functions WHERE signature='zasp_ordered_public62.mutate(text,text,jsonb)' AND owner_name='zasp_discovery_authority' AND acl='{zasp_discovery_authority=X/zasp_discovery_authority}';
 guard:=$gate$ IF op='decide' THEN PERFORM zasp_authorization80_worker.require_ordered62_approval(q,true);END IF;$gate$;
 needle:=$admitted$ admitted:=EXISTS(SELECT 1 FROM public.zasp_sa_multistep_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r));$admitted$;
 d:=zasp_authorization80_worker.ordered62_replace(d,needle,guard||E'\n'||needle);
 needle:='   transition_result:=zasp_temporal67.api_transition(';
 d:=zasp_authorization80_worker.ordered62_replace(d,needle,guard||E'\n'||needle);
 needle:=$return$ RETURN result_value||jsonb_build_object('replayed',replayed);$return$;
 d:=zasp_authorization80_worker.ordered62_replace(d,needle,replace(guard,'(q,true)','(q,false)')||E'\n'||needle);
 EXECUTE d;
 SELECT definition INTO STRICT d FROM zasp_authorization80_worker.predecessor_functions WHERE signature='zasp_ordered_public62.fingerprint()' AND owner_name='zasp_discovery_authority' AND acl='{zasp_discovery_authority=X/zasp_discovery_authority}';
 d:=zasp_authorization80_worker.ordered62_replace(d,'FUNCTION zasp_ordered_public62.fingerprint()','FUNCTION zasp_authorization80_worker.projected62()');
 d:=zasp_authorization80_worker.ordered62_replace(d,'pg_get_functiondef(p.oid)',$projection$CASE WHEN p.oid IN('zasp_ordered_public62.api(text,text,jsonb)'::regprocedure,'zasp_ordered_public62.mutate(text,text,jsonb)'::regprocedure,'zasp_ordered_public62.fingerprint()'::regprocedure) THEN(SELECT definition FROM zasp_authorization80_worker.predecessor_functions WHERE signature=p.oid::regprocedure::text) ELSE pg_get_functiondef(p.oid) END$projection$);
 EXECUTE d;
END $ordered_human$;

CREATE OR REPLACE FUNCTION zasp_ordered_public62.fingerprint() RETURNS text LANGUAGE sql STABLE SET search_path=pg_catalog,public AS $fingerprint$
 SELECT CASE WHEN EXISTS(SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid='zasp_authorization80_worker.catalog_ready()'::regprocedure AND encode(digest(convert_to(p.prosrc,'UTF8'),'sha256'),'hex')='28bc26660db8eae036fd2f36bc215fcf2e27c1aba6d2c7c42d5d6a58e73c5016' AND p.proowner='zasp_discovery_authority'::regrole AND p.prosecdef AND p.provolatile='s' AND l.lanname='sql' AND p.proconfig=ARRAY['search_path=pg_catalog, public'] AND p.proacl::text='{zasp_discovery_authority=X/zasp_discovery_authority}') AND EXISTS(SELECT 1 FROM zasp_authorization80_worker.registration WHERE checksum='5b129ed0592dde0af626a47bb656a572e009c1cefa182293429a454727af7bf9') AND zasp_authorization80_worker.catalog_ready() THEN zasp_authorization80_worker.projected62() ELSE NULL END
$fingerprint$;

-- The public decide_resource call retains its complete readiness fences before
-- and after all nested work. These fixed, owner-only decide copies share that
-- bracket; no other caller, operation, mutable cache or skip flag is admitted.
DO $ordered_approval_inner$ DECLARE d text;outer_definition text;mutate_definition text;needle text;expected62 text;p regprocedure;BEGIN
 SELECT pg_get_functiondef(oid) INTO STRICT outer_definition FROM pg_proc
 WHERE oid='zasp_ordered_public62.api(text,text,jsonb)'::regprocedure AND proowner='zasp_discovery_authority'::regrole
 AND proacl::text='{zasp_discovery_authority=X/zasp_discovery_authority,zasp_security_agent_api=X/zasp_discovery_authority}';
 SELECT pg_get_functiondef(oid) INTO STRICT mutate_definition FROM pg_proc
 WHERE oid='zasp_ordered_public62.mutate(text,text,jsonb)'::regprocedure AND proowner='zasp_discovery_authority'::regrole
 AND proacl::text='{zasp_discovery_authority=X/zasp_discovery_authority}';
 -- These are the already fenced bodies created immediately before this module,
 -- not historical bare62 copies. The saved originals stay unchanged for67.
 IF position('zasp_authorization80_worker.require_ordered62_approval(q,true)' IN outer_definition)=0
 OR position('zasp_authorization80_worker.require_ordered62_approval(q,false)' IN outer_definition)=0
 OR position('zasp_authorization80_worker.require_ordered62_approval(q,true)' IN mutate_definition)=0
 OR position('zasp_authorization80_worker.require_ordered62_approval(q,false)' IN mutate_definition)=0
 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='ordered approval fenced predecessor absent';END IF;
 expected62:=zasp_authorization80_worker.projected62();
 IF expected62 IS NULL OR expected62!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='ordered approval projected identity absent';END IF;
 SELECT pg_get_functiondef(oid) INTO STRICT d FROM pg_proc WHERE oid='zasp_ordered_public62.ready(text,text)'::regprocedure
 AND proowner='zasp_discovery_authority'::regrole AND proacl::text='{zasp_discovery_authority=X/zasp_discovery_authority}';
 d:=zasp_authorization80_worker.ordered62_replace(d,'FUNCTION zasp_ordered_public62.ready(','FUNCTION zasp_authorization80_worker.ordered62_inner_ready(');
 -- Native67's effective ready body has compiled62 argument pins and delegates
 -- to67.current_ready. The latter remains at both ends of the public call.
 d:=zasp_authorization80_worker.ordered62_replace(d,' AND zasp_temporal67.current_ready()',
 ' AND zasp_authorization80_worker.catalog_ready() AND (SELECT count(*)=1 FROM zasp_ordered_public62.registration) AND EXISTS(SELECT 1 FROM zasp_ordered_public62.registration WHERE singleton AND checksum=c AND fingerprint=f) AND zasp_authorization80_worker.projected62()='||quote_literal(expected62));
 EXECUTE d;

 d:=zasp_authorization80_worker.ordered62_replace(mutate_definition,'FUNCTION zasp_ordered_public62.mutate(','FUNCTION zasp_authorization80_worker.ordered62_mutate_inner(');
 d:=zasp_authorization80_worker.ordered62_replace(d,E'BEGIN\n',E'BEGIN\n IF q->>''operation'' IS DISTINCT FROM ''decide'' THEN RAISE EXCEPTION USING ERRCODE=''22023'',MESSAGE=''private ordered approval operation rejected'';END IF;\n');
 IF (length(d)-length(replace(d,'zasp_ordered_public62.ready(c,f)','')))/length('zasp_ordered_public62.ready(c,f)')<>2 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='ordered approval mutation readiness count changed';END IF;
 d:=replace(d,'zasp_ordered_public62.ready(c,f)','zasp_authorization80_worker.ordered62_inner_ready(c,f)');
 EXECUTE d;

 d:=zasp_authorization80_worker.ordered62_replace(outer_definition,'FUNCTION zasp_ordered_public62.api(','FUNCTION zasp_authorization80_worker.ordered62_decide_inner(');
 d:=zasp_authorization80_worker.ordered62_replace(d,E'BEGIN\n',E'BEGIN\n IF q->>''operation'' IS DISTINCT FROM ''decide'' THEN RAISE EXCEPTION USING ERRCODE=''22023'',MESSAGE=''private ordered approval operation rejected'';END IF;\n');
 needle:=$entry$ IF NOT COALESCE(zasp_ordered_public62.ready(c,f),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='public ordered release unavailable';END IF;$entry$;
 d:=zasp_authorization80_worker.ordered62_replace(d,needle,replace(needle,'zasp_ordered_public62.ready(c,f)','zasp_authorization80_worker.ordered62_inner_ready(c,f)'));
 needle:=$exit$ IF result_value IS NULL OR octet_length(result_value::text)>65536 OR NOT zasp_ordered_public62.ready(c,f) OR NOT public.zasp_security_agent_principal_ready('zasp_security_agent_api') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered authority changed';END IF;$exit$;
 d:=zasp_authorization80_worker.ordered62_replace(d,needle,replace(needle,'zasp_ordered_public62.ready(c,f)','zasp_authorization80_worker.ordered62_inner_ready(c,f)'));
 needle:=$mutate$ ELSIF op IN('decide','cancel') THEN result_value:=zasp_ordered_public62.mutate(c,f,q);$mutate$;
 d:=zasp_authorization80_worker.ordered62_replace(d,needle,replace(needle,'zasp_ordered_public62.mutate(c,f,q)','zasp_authorization80_worker.ordered62_mutate_inner(c,f,q)'));
 EXECUTE d;

 -- Only this complete branch has already checked the outer resource request;
 -- trigger recursion and public direct decide/cancel remain untouched.
 needle:=$caller$  inner_result:=zasp_ordered_public62.api(c,f,inner_q);
  result_value:=jsonb_build_object('mutation',inner_result,'resource',zasp_ordered_public62.resource_run(o,w,e,approval_row.run_id));$caller$;
 EXECUTE zasp_authorization80_worker.ordered62_replace(outer_definition,needle,replace(needle,'zasp_ordered_public62.api(c,f,inner_q)','zasp_authorization80_worker.ordered62_decide_inner(c,f,inner_q)'));
 FOREACH p IN ARRAY ARRAY['zasp_authorization80_worker.ordered62_inner_ready(text,text)'::regprocedure,'zasp_authorization80_worker.ordered62_mutate_inner(text,text,jsonb)'::regprocedure,'zasp_authorization80_worker.ordered62_decide_inner(text,text,jsonb)'::regprocedure] LOOP
  EXECUTE format('ALTER FUNCTION %s OWNER TO zasp_discovery_authority',p);
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',p);
 END LOOP;
END $ordered_approval_inner$;

-- Extend the effective projections after other installed worker families, not
-- their older saved bodies. Live replacements and these exact triggers remain
-- independently included in the worker fingerprint.
DO $ordered_catalog$ DECLARE d text;needle text;replacement text;BEGIN
 SELECT pg_get_functiondef('zasp_authorization80_worker.projected_domain()'::regprocedure) INTO d;
 needle:='WHERE NOT t.tgisinternal AND NOT(';
 replacement:=$triggers$WHERE NOT t.tgisinternal AND NOT(t.tgrelid IN('public.zasp_inventory_entities'::regclass,'public.zasp_inventory_evidence'::regclass,'public.zasp_discovery_snapshots'::regclass,'public.zasp_inventory_source_observations'::regclass) AND t.tgname IN('zasp_authorization80_worker_ordered_target','zasp_authorization80_worker_ordered_no_truncate')) AND NOT($triggers$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='ordered target catalog predecessor changed';END IF;
 EXECUTE replace(d,needle,replacement);
 SELECT pg_get_functiondef('zasp_authorization79.pending(integer)'::regprocedure) INTO d;
 needle:=' ORDER BY COALESCE(last_attempt_at,pending_since)';
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='ordered expiry queue predecessor changed';END IF;
 EXECUTE replace(d,needle,' OR EXISTS(SELECT 1 FROM zasp_authorization80_worker.ordered_state s WHERE s.organization_id=zasp_authorization79.organizations.organization_id AND s.target_current AND s.fresh_until<=clock_timestamp())'||needle);
 SELECT pg_get_functiondef('zasp_authorization79.snapshot(text)'::regprocedure) INTO d;
 needle:=$old$ IF EXISTS(SELECT 1 FROM public.zasp_environments WHERE organization_id=o GROUP BY id HAVING count(*)>1)$old$;
 IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='ordered expiry snapshot predecessor changed';END IF;
 EXECUTE replace(d,needle,' PERFORM zasp_authorization80_worker.expire_ordered_targets(o);'||E'\n'||needle);
END $ordered_catalog$;

-- Gateway ingestion keeps native credential authentication. Serialize its
-- existing writers before device locks so worker source revocation has one order.
INSERT INTO zasp_authorization80_worker.predecessor_functions
 SELECT oid::regprocedure::text,pg_get_functiondef(oid),proowner::regrole::text,COALESCE(proacl::text,'') FROM pg_proc
 WHERE oid IN('public.zasp_discovery_create_gateway_device(text,text,text,text,text)'::regprocedure,
 'public.zasp_discovery_transition_gateway_device(text,text,text,text,bigint,text)'::regprocedure,
 'public.zasp_runtime_issue_gateway_enrollment(text,text,text,text,text,bigint,bigint,bytea,bytea,bytea,timestamp with time zone)'::regprocedure,
 'public.zasp_runtime_revoke_gateway_enrollment(text,text,text,text,text)'::regprocedure,
 'public.zasp_runtime_authenticate_gateway_enrollment(bytea,bytea,text)'::regprocedure,
 'public.zasp_runtime_gateway_advance_replay(text,bigint,bigint,bytea)'::regprocedure,
 'public.zasp_runtime_gateway_record_event(text,text,bigint,bigint,bytea,bigint,text,text,jsonb,timestamp with time zone)'::regprocedure,
 'public.zasp_runtime_gateway_record_event_v27(text,text,bigint,bigint,bytea,bigint,text,text,jsonb,jsonb,timestamp with time zone)'::regprocedure,
 'public.zasp_runtime_data_plane_live_fingerprint()'::regprocedure,
 'public.zasp_security_agent_live_fingerprint()'::regprocedure,
 'public.zasp_security_agent_budgets_function_identity(oid)'::regprocedure,
 'public.zasp_security_agent_session_isolation_live_fingerprint()'::regprocedure,
 'public.zasp_recovery_execution_live_fingerprint()'::regprocedure);

CREATE FUNCTION zasp_authorization80_worker.gateway_organization_lock(o text) RETURNS void
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $lock$
BEGIN
 IF current_setting('transaction_isolation')<>'read committed'
 OR NOT zasp_authorization80_worker.catalog_ready()
 OR NOT public.zasp_runtime_principal_ready('zasp_gateway_control')
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='gateway writer authority rejected';END IF;
 PERFORM 1 FROM zasp_authorization79.organizations WHERE organization_id=o FOR UPDATE;
 IF NOT FOUND OR NOT zasp_authorization80_worker.catalog_ready()
 OR NOT public.zasp_runtime_principal_ready('zasp_gateway_control')
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='gateway writer organization rejected';END IF;
END $lock$;

-- Device management has a distinct registered API login. This preserves the
-- existing caller contract; it is not a replacement for HTTP/OpenFGA checks.
CREATE FUNCTION zasp_authorization80_worker.gateway_api_organization_lock(o text) RETURNS void
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $lock$
BEGIN
 IF current_setting('transaction_isolation')<>'read committed'
 OR NOT zasp_authorization80_worker.catalog_ready()
 OR NOT public.zasp_discovery_principal_ready('zasp_discovery_api')
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='gateway API writer authority rejected';END IF;
 PERFORM 1 FROM zasp_authorization79.organizations WHERE organization_id=o FOR UPDATE;
 IF NOT FOUND OR NOT zasp_authorization80_worker.catalog_ready()
 OR NOT public.zasp_discovery_principal_ready('zasp_discovery_api')
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='gateway API writer organization rejected';END IF;
END $lock$;

DO $api_writers$ DECLARE p record;d text;needle text;BEGIN
 FOR p IN SELECT * FROM zasp_authorization80_worker.predecessor_functions WHERE signature IN(
 'zasp_discovery_create_gateway_device(text,text,text,text,text)',
 'zasp_discovery_transition_gateway_device(text,text,text,text,bigint,text)') LOOP
  IF p.owner_name<>'zasp_discovery_authority' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='gateway API writer owner changed';END IF;
  d:=p.definition;
  needle:='DECLARE result jsonb;BEGIN ';
  IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='gateway API writer entry changed';END IF;
  d:=replace(d,needle,needle||'PERFORM zasp_authorization80_worker.gateway_api_organization_lock(p_organization_id);');
  IF p.signature='zasp_discovery_create_gateway_device(text,text,text,text,text)' THEN
   needle:='PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),$1,$2,$3,$4),0));';
   IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='gateway API create advisory changed';END IF;
   d:=replace(d,needle,needle||'PERFORM zasp_authorization80_worker.gateway_api_organization_lock(p_organization_id);');
  ELSE
   -- UPDATE can wait on the device row. Keep its FOUND/fallback predicates
   -- intact; a refusal before returning rolls back the entire mutation.
   needle:='RETURN result;';
   IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='gateway API transition return changed';END IF;
   d:=replace(d,needle,'PERFORM zasp_authorization80_worker.gateway_api_organization_lock(p_organization_id);'||needle);
  END IF;
  EXECUTE d;
 END LOOP;
END $api_writers$;

DO $api_enrollment$ DECLARE p record;d text;needle text;replacement text;BEGIN
 FOR p IN SELECT * FROM zasp_authorization80_worker.predecessor_functions WHERE signature IN(
 'zasp_runtime_issue_gateway_enrollment(text,text,text,text,text,bigint,bigint,bytea,bytea,bytea,timestamp with time zone)',
 'zasp_runtime_revoke_gateway_enrollment(text,text,text,text,text)') LOOP
  IF p.owner_name<>'zasp_discovery_authority' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='gateway enrollment API owner changed';END IF;
  d:=p.definition;
  needle:='PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,device_value),0));';
  IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='gateway enrollment API advisory changed';END IF;
  replacement:='PERFORM zasp_authorization80_worker.gateway_api_organization_lock(organization_value);'||E'\n '||needle||E'\n PERFORM zasp_authorization80_worker.gateway_api_organization_lock(organization_value);';
  IF p.signature LIKE 'zasp_runtime_issue_gateway_enrollment(%' THEN
   -- Recheck after both possible waits. The original transaction clock does
   -- not advance while waiting for organization or device serialization.
   replacement:=replacement||E'\n '||$expiry$IF expires_value<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='gateway enrollment expired while waiting';END IF;$expiry$;
  END IF;
  EXECUTE replace(d,needle,replacement);
 END LOOP;
END $api_enrollment$;

CREATE FUNCTION zasp_authorization80_worker.gateway_credential_lock(o text,w text,e text,d text,c text) RETURNS void
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $lock$
DECLARE a jsonb;BEGIN
 PERFORM zasp_authorization80_worker.gateway_organization_lock(o);
 -- The original lookup precedes this possibly blocking lock. Re-evaluate it
 -- afterward, including wall-clock expiry, before acquiring a device lock.
 a:=public.zasp_runtime_gateway_credential_authority(c,'runtime-gateway');
 IF(a->>'organization_id',a->>'workspace_id',a->>'environment_id',a->>'device_id',a->>'credential_id') IS DISTINCT FROM(o,w,e,d,c)
 OR NOT COALESCE((a->>'expires_at')::timestamptz>clock_timestamp(),false)
 THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='gateway writer credential changed';END IF;
END $lock$;

DO $writers$ DECLARE p record;d text;needle text;replacement text;BEGIN
 FOR p IN SELECT * FROM zasp_authorization80_worker.predecessor_functions WHERE signature IN(
 'zasp_runtime_authenticate_gateway_enrollment(bytea,bytea,text)',
 'zasp_runtime_gateway_advance_replay(text,bigint,bigint,bytea)',
 'zasp_runtime_gateway_record_event(text,text,bigint,bigint,bytea,bigint,text,text,jsonb,timestamp with time zone)',
 'zasp_runtime_gateway_record_event_v27(text,text,bigint,bigint,bytea,bigint,text,text,jsonb,jsonb,timestamp with time zone)') LOOP
  IF p.owner_name<>'zasp_discovery_authority' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='gateway writer owner changed';END IF;
  d:=p.definition;
  IF p.signature='zasp_runtime_authenticate_gateway_enrollment(bytea,bytea,text)' THEN
   needle:='PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),candidate_scope.organization_id,candidate_scope.workspace_id,candidate_scope.environment_id,candidate_scope.device_id),0));';
