-- Derived execution grants are separate from the immutable admission and the
-- planner's queued/planning/waiting_approval view. Real effects retain their own
-- immutable native target snapshot; this table is not a compensation resolver.
CREATE TABLE zasp_authorization80_worker.ordered_effect_scope(
 organization_id text NOT NULL,workspace_id text NOT NULL,environment_id text NOT NULL,run_id text NOT NULL,step_id text NOT NULL,
 action_key text NOT NULL CHECK(action_key IN('create_temporary_policy','run_test')),
 device_ids jsonb NOT NULL,destination_digest text,targets_digest text,fresh_until timestamptz NOT NULL,target_current boolean NOT NULL,
 PRIMARY KEY(organization_id,workspace_id,environment_id,run_id,step_id),
 FOREIGN KEY(organization_id,workspace_id,environment_id,run_id) REFERENCES zasp_authorization80_worker.ordered_associations,
 CHECK(jsonb_typeof(device_ids)='array' AND CASE action_key WHEN 'create_temporary_policy' THEN jsonb_array_length(device_ids) BETWEEN 1 AND 100 AND destination_digest IS NOT NULL AND targets_digest IS NOT NULL AND destination_digest~'^[a-f0-9]{64}$' AND targets_digest~'^[a-f0-9]{64}$' ELSE device_ids='[]'::jsonb AND destination_digest IS NULL AND targets_digest IS NULL END));
ALTER TABLE zasp_authorization80_worker.ordered_effect_scope OWNER TO zasp_discovery_authority;
ALTER TABLE zasp_authorization80_worker.ordered_effect_scope ENABLE ROW LEVEL SECURITY;
ALTER TABLE zasp_authorization80_worker.ordered_effect_scope FORCE ROW LEVEL SECURITY;
CREATE POLICY authority ON zasp_authorization80_worker.ordered_effect_scope TO zasp_discovery_authority USING(true) WITH CHECK(true);
CREATE TRIGGER no_truncate BEFORE TRUNCATE ON zasp_authorization80_worker.ordered_effect_scope FOR EACH STATEMENT EXECUTE FUNCTION zasp_temporal67.immutable();
CREATE TRIGGER worker_revision AFTER INSERT OR UPDATE OR DELETE ON zasp_authorization80_worker.ordered_effect_scope FOR EACH ROW EXECUTE FUNCTION zasp_authorization79.capture('organization_id','organization_id,workspace_id,environment_id,run_id,step_id,action_key,device_ids,destination_digest,targets_digest,fresh_until,target_current');

CREATE FUNCTION zasp_authorization80_worker.prepare_ordered68_effect(q jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $prepare_effect$
DECLARE f jsonb;BEGIN
 -- Only a real admitted reserve identity can establish or refresh projection.
 -- The metadata reader holds organization before native budget/run/step locks.
 f:=zasp_authorization80_worker.ordered68_effect_metadata('effect.reserve',q);
 IF f#>>'{step,state}' NOT IN('authorized','executing') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered approved effect absent';END IF;
 IF f->>'ordered_action_key'='create_temporary_policy' THEN
  PERFORM zasp_sa_multistep_prior.application_current(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id');
 ELSE
  PERFORM zasp_sa_multistep_prior.test_current(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id');
 END IF;
 INSERT INTO zasp_authorization80_worker.ordered_effect_scope AS c VALUES(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id',f->>'ordered_action_key',f->'ordered_device_ids',f->>'destination_digest',f->>'ordered_targets_digest',to_timestamp((f->>'fresh_until_ms')::numeric/1000),true)
 ON CONFLICT(organization_id,workspace_id,environment_id,run_id,step_id) DO UPDATE SET device_ids=EXCLUDED.device_ids,destination_digest=EXCLUDED.destination_digest,targets_digest=EXCLUDED.targets_digest,fresh_until=EXCLUDED.fresh_until,target_current=true
 WHERE(c.action_key,c.device_ids,c.destination_digest,c.targets_digest,c.fresh_until,c.target_current) IS DISTINCT FROM(EXCLUDED.action_key,EXCLUDED.device_ids,EXCLUDED.destination_digest,EXCLUDED.targets_digest,EXCLUDED.fresh_until,true);
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.ordered_effect_scope c WHERE(c.organization_id,c.workspace_id,c.environment_id,c.run_id,c.step_id,c.action_key,c.device_ids,c.target_current)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id',f->>'ordered_action_key',f->'ordered_device_ids',true) AND c.fresh_until>clock_timestamp()) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered effect capture changed';END IF;
END $prepare_effect$;

CREATE FUNCTION zasp_authorization80_worker.capture_ordered_gateway() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $capture_gateway$
DECLARE old_value jsonb;new_value jsonb;BEGIN
 IF TG_OP<>'INSERT' THEN old_value:=to_jsonb(OLD);END IF;
 IF TG_OP<>'DELETE' THEN new_value:=to_jsonb(NEW);END IF;
 IF TG_OP='UPDATE' AND old_value=new_value THEN RETURN NEW;END IF;
 IF TG_OP='UPDATE' AND TG_TABLE_NAME='zasp_gateway_devices' AND old_value-ARRAY['replay_floor','version','updated_at']=new_value-ARRAY['replay_floor','version','updated_at'] THEN RETURN NEW;END IF;
 UPDATE zasp_authorization80_worker.ordered_effect_scope c SET target_current=false WHERE c.target_current AND c.action_key='create_temporary_policy'
 AND((c.organization_id,c.workspace_id,c.environment_id)=(old_value->>'organization_id',old_value->>'workspace_id',old_value->>'environment_id') OR(c.organization_id,c.workspace_id,c.environment_id)=(new_value->>'organization_id',new_value->>'workspace_id',new_value->>'environment_id'));
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $capture_gateway$;
DO $gateway_capture$ DECLARE n text;BEGIN
 FOREACH n IN ARRAY ARRAY['zasp_gateway_devices','zasp_gateway_credentials'] LOOP
  EXECUTE format('CREATE TRIGGER zasp_authorization80_worker_ordered_gateway BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION zasp_authorization80_worker.capture_ordered_gateway()',n);
  EXECUTE format('CREATE TRIGGER zasp_authorization80_worker_ordered_no_truncate BEFORE TRUNCATE ON public.%I FOR EACH STATEMENT EXECUTE FUNCTION zasp_temporal67.immutable()',n);
 END LOOP;
END $gateway_capture$;
CREATE FUNCTION zasp_authorization80_worker.expire_ordered_effects(o text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $effect_expiry$
BEGIN
 IF NOT zasp_authorization79.worker() OR NOT zasp_authorization79.locked(o) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered effect expiry session rejected';END IF;
 UPDATE zasp_authorization80_worker.ordered_effect_scope SET target_current=false WHERE organization_id=o AND target_current AND fresh_until<=clock_timestamp();
END $effect_expiry$;

CREATE VIEW zasp_authorization80_worker.active_ordered_effects AS
 SELECT a.*,c.step_id,c.action_key,c.device_ids FROM zasp_authorization80_worker.ordered_associations a
 JOIN zasp_authorization80_worker.ordered_state s USING(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version)
 JOIN zasp_authorization80_worker.ordered_effect_scope c USING(organization_id,workspace_id,environment_id,run_id)
 JOIN public.zasp_security_agent_definitions d ON(d.organization_id,d.workspace_id,d.environment_id,d.definition_id,d.version)=(a.organization_id,a.workspace_id,a.environment_id,a.definition_id,a.definition_version)
 JOIN public.zasp_identity_memberships m ON(m.organization_id,m.principal_id)=(a.organization_id,a.grantor_id)
 WHERE s.present AND s.target_current AND s.fresh_until>clock_timestamp() AND s.state IN('running','verifying') AND c.target_current AND c.fresh_until>clock_timestamp() AND m.active AND d.deleted_at IS NULL AND d.activation='supervised' AND d.body->'enabled'='true'::jsonb;
ALTER VIEW zasp_authorization80_worker.active_ordered_effects OWNER TO zasp_discovery_authority;
DO $effect_views$ DECLARE d text;BEGIN
 SELECT pg_get_viewdef('zasp_authorization79.members'::regclass) INTO d;
 EXECUTE 'CREATE OR REPLACE VIEW zasp_authorization79.members AS '||rtrim(d,E';\n ')||' UNION SELECT organization_id,''service''::text,principal_id,''''::text FROM zasp_authorization80_worker.active_ordered_effects';
 SELECT pg_get_viewdef('zasp_authorization79.current_grants'::regclass) INTO d;
 EXECUTE 'CREATE OR REPLACE VIEW zasp_authorization79.current_grants AS '||rtrim(d,E';\n ')||$grants$
 UNION SELECT a.organization_id,a.workspace_id,a.environment_id,t.kind,t.id,'service'::text,a.principal_id,t.permission,a.run_id FROM zasp_authorization80_worker.active_ordered_effects a
 CROSS JOIN LATERAL(VALUES('security_agent'::text,a.definition_id,'manage_workflows'::text),('security_agent_run',a.run_id,'manage_workflows')) t(kind,id,permission)
 UNION SELECT a.organization_id,a.workspace_id,a.environment_id,'gateway_device'::text,t.id,'service'::text,a.principal_id,'manage_workflows'::text,a.run_id FROM zasp_authorization80_worker.active_ordered_effects a CROSS JOIN LATERAL jsonb_array_elements_text(a.device_ids) t(id) WHERE a.action_key='create_temporary_policy'
 UNION SELECT a.organization_id,a.workspace_id,a.environment_id,t.kind,t.id,'service'::text,a.principal_id,'run_tests'::text,a.run_id FROM zasp_authorization80_worker.active_ordered_effects a CROSS JOIN LATERAL(VALUES('test'::text,a.test_id),(a.target_kind,a.target_id)) t(kind,id) WHERE a.action_key='run_test'$grants$;
END $effect_views$;

-- Canonicalize transient typed rows without changing the calling context of
-- native evidence validators. Already-captured JSON strings remain untouched.
CREATE FUNCTION zasp_authorization80_worker.ordered68_row_json(v anyelement) RETURNS jsonb
 LANGUAGE sql STABLE SET search_path=pg_catalog,public
 SET timezone='UTC' AS $ordered_row_json$ SELECT to_jsonb(v) $ordered_row_json$;

-- Effect authority is separate from planner disclosure. Keep the immutable
-- admission validator, but admit only the native execution states here.
DO $ordered_effect_facts$ DECLARE d text;needle text;BEGIN
 SELECT pg_get_functiondef('zasp_authorization80_worker.ordered68_facts(boolean,jsonb)'::regprocedure) INTO d;
 d:=zasp_authorization80_worker.ordered62_replace(d,'FUNCTION zasp_authorization80_worker.ordered68_facts(', 'FUNCTION zasp_authorization80_worker.ordered68_effect_facts(');
 needle:=$states$r.state NOT IN('queued','planning','waiting_approval')$states$;
 d:=zasp_authorization80_worker.ordered62_replace(d,needle,$states$r.state NOT IN('running','verifying')$states$);
 EXECUTE d;
END $ordered_effect_facts$;

-- Full native68 Block destinations, not runtime event source devices. Caller
-- holds the authorization organization lock before the retained parent locks.
-- Only opaque identities, digests and expiry leave this owner-only reader.
CREATE FUNCTION zasp_authorization80_worker.ordered68_destinations(o text,w text,e text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public SET timezone='UTC' AS $destinations$
DECLARE selected jsonb;locked_value jsonb;row_value record;d public.zasp_gateway_devices%ROWTYPE;c public.zasp_gateway_credentials%ROWTYPE;
 metadata jsonb:='[]'::jsonb;expires timestamptz;BEGIN
 SELECT COALESCE(jsonb_agg(jsonb_build_object('device_id',v.id,'credential_id',k.id) ORDER BY v.id),'[]'::jsonb) INTO selected
 FROM public.zasp_gateway_devices v JOIN LATERAL(SELECT id FROM public.zasp_gateway_credentials WHERE(organization_id,workspace_id,environment_id,device_id)=(o,w,e,v.id) AND revoked_at IS NULL AND expires_at>clock_timestamp() ORDER BY issued_at DESC,id DESC LIMIT 1) k ON true
 WHERE(v.organization_id,v.workspace_id,v.environment_id,v.state)=(o,w,e,'active');
 IF jsonb_array_length(selected) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered destination bound rejected';END IF;
 FOR row_value IN SELECT * FROM jsonb_to_recordset(selected) AS t(device_id text,credential_id text) ORDER BY device_id LOOP
  SELECT * INTO d FROM public.zasp_gateway_devices WHERE(organization_id,workspace_id,environment_id,id,state)=(o,w,e,row_value.device_id,'active') FOR SHARE NOWAIT;
  SELECT * INTO c FROM public.zasp_gateway_credentials WHERE(organization_id,workspace_id,environment_id,device_id,id)=(o,w,e,row_value.device_id,row_value.credential_id) AND revoked_at IS NULL AND expires_at>clock_timestamp() FOR SHARE NOWAIT;
  IF d.id IS NULL OR c.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered destination changed';END IF;
  expires:=CASE WHEN expires IS NULL THEN c.expires_at ELSE least(expires,c.expires_at) END;
  -- Native gateway replay advances version with its floor on ordinary event
  -- traffic. Those bookkeeping fields do not change device authority.
  metadata:=metadata||jsonb_build_array(jsonb_build_array(d.id,encode(digest(convert_to((to_jsonb(d)-ARRAY['replay_floor','version','updated_at'])::text,'UTF8'),'sha256'),'hex'),c.id,encode(digest(convert_to(to_jsonb(c)::text,'UTF8'),'sha256'),'hex')));
 END LOOP;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('device_id',v.id,'credential_id',k.id) ORDER BY v.id),'[]'::jsonb) INTO locked_value
 FROM public.zasp_gateway_devices v JOIN LATERAL(SELECT id FROM public.zasp_gateway_credentials WHERE(organization_id,workspace_id,environment_id,device_id)=(o,w,e,v.id) AND revoked_at IS NULL AND expires_at>clock_timestamp() ORDER BY issued_at DESC,id DESC LIMIT 1) k ON true
 WHERE(v.organization_id,v.workspace_id,v.environment_id,v.state)=(o,w,e,'active');
 IF selected IS DISTINCT FROM locked_value OR expires<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered selected destination changed';END IF;
 RETURN jsonb_build_object('ids',(SELECT jsonb_agg(t->'device_id' ORDER BY t->>'device_id') FROM jsonb_array_elements(selected) t),'targets_digest',encode(digest(convert_to(selected::text,'UTF8'),'sha256'),'hex'),'identity_digest',encode(digest(convert_to(metadata::text,'UTF8'),'sha256'),'hex'),'fresh_until_ms',floor(extract(epoch FROM expires)*1000)::bigint);
END $destinations$;

CREATE FUNCTION zasp_authorization80_worker.ordered68_effect_metadata(phase text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $ordered_effect_source$
DECLARE x zasp_temporal66.run_owners%ROWTYPE;a zasp_authorization80_worker.ordered_associations%ROWTYPE;st public.zasp_security_agent_steps%ROWTYPE;plan_value public.zasp_security_agent_plans%ROWTYPE;
 v zasp_temporal68.effects%ROWTYPE;f jsonb;reference_value jsonb;step_value jsonb;effect_value jsonb;destinations jsonb;checks jsonb;captured_targets jsonb;
 compensation boolean:=phase IN('effect.read','effect.unknown');BEGIN
 IF phase IS NULL OR phase NOT IN('effect.reserve','effect.start','effect.read','effect.unknown') OR octet_length(q::text)>4096
 OR NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload'])
 OR q->'generation' IS DISTINCT FROM '1'::jsonb OR q->'payload' IS DISTINCT FROM '{}'::jsonb OR q->>'operation' IS DISTINCT FROM split_part(phase,'.',2)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered effect request rejected';END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='ordered effect requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.current_ready() OR NOT zasp_temporal68.principal_ready(CASE WHEN compensation THEN 'zasp_temporal_compensation' ELSE 'zasp_temporal_executor' END) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered effect principal rejected';END IF;
 PERFORM 1 FROM zasp_authorization79.organizations WHERE organization_id=q->>'organization_id' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered effect organization absent';END IF;
 PERFORM zasp_sa_multistep_prior.application_lock(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id');
 SELECT * INTO x FROM zasp_temporal66.run_owners WHERE(organization_id,workspace_id,environment_id,run_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id');
 IF x.run_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered effect owner absent';END IF;
 reference_value:=jsonb_build_object('organization_id',x.organization_id,'workspace_id',x.workspace_id,'environment_id',x.environment_id,'run_id',x.run_id,'definition_version',x.definition_version,'input_digest',x.input_digest);
 f:=zasp_authorization80_worker.ordered68_effect_facts(compensation,reference_value);
 a:=jsonb_populate_record(NULL::zasp_authorization80_worker.ordered_associations,f);
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.ordered_associations s WHERE s=a) OR NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.ordered_state s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.definition_id,s.definition_version,s.state,s.run_version,s.present)=(a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.definition_id,a.definition_version,f->>'run_state',(f->>'run_version')::bigint,true) AND(compensation OR s.target_current AND s.fresh_until>clock_timestamp())) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered effect admission changed';END IF;
 SELECT * INTO st FROM public.zasp_security_agent_steps WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,q->>'step_id') FOR SHARE;
 SELECT * INTO plan_value FROM public.zasp_security_agent_plans WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id) FOR SHARE;
 IF st.step_id IS NULL OR plan_value.run_id IS NULL OR st.step_index NOT IN(0,1) OR st.action_key IS DISTINCT FROM (CASE st.step_index WHEN 0 THEN 'create_temporary_policy' ELSE 'run_test' END)
 OR plan_value.plan->'steps'->st.step_index->>'step_id' IS DISTINCT FROM st.step_id THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered effect step changed';END IF;
 PERFORM zasp_temporal68.current_plan(x.organization_id,x.workspace_id,x.environment_id,x.run_id,NOT compensation);
 SELECT * INTO v FROM zasp_temporal68.effects WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,st.step_id,1) FOR SHARE;
 IF v.run_id IS NULL AND phase<>'effect.reserve' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered captured effect absent';END IF;
 IF v.run_id IS NOT NULL THEN
  IF v.effect_key IS DISTINCT FROM zasp_temporal68.effect_identity(x.organization_id,x.workspace_id,x.environment_id,x.run_id,st.step_id,1) OR(v.input_digest,v.plan_hash,v.action_key) IS DISTINCT FROM(st.input_digest,plan_value.plan_hash,st.action_key)
  OR v.snapshot_digest IS DISTINCT FROM digest(convert_to(v.snapshot::text,'UTF8'),'sha256') OR v.snapshot->>'input_digest' IS DISTINCT FROM encode(st.input_digest,'hex') OR v.snapshot->>'plan_hash' IS DISTINCT FROM encode(plan_value.plan_hash,'hex')
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_step_reservations s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.step_id,s.action_key,s.input_digest)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,st.step_id,st.action_key,st.input_digest))
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_effects s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.step_id,s.action_key,s.input_digest)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,st.step_id,st.action_key,st.input_digest) AND s.lease_owner IS NULL AND s.lease_token IS NULL AND s.lease_expires_at IS NULL)
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered captured effect changed';END IF;
  effect_value:=jsonb_build_object('effect_key',v.effect_key,'generation',v.generation,'state',v.state,'snapshot_digest',encode(v.snapshot_digest,'hex'));
 END IF;
 checks:='[]'::jsonb;
 IF NOT compensation THEN
  checks:=jsonb_build_array(jsonb_build_object('kind','security_agent','id',a.definition_id,'permission','manage_workflows'),jsonb_build_object('kind','security_agent_run','id',a.run_id,'permission','manage_workflows'));
  IF st.step_index=0 THEN
   destinations:=zasp_authorization80_worker.ordered68_destinations(x.organization_id,x.workspace_id,x.environment_id);
   IF v.run_id IS NOT NULL THEN
    SELECT jsonb_agg(jsonb_build_object('device_id',t->>'device_id','credential_id',t->>'credential_id') ORDER BY t->>'device_id') INTO captured_targets FROM jsonb_array_elements(v.snapshot->'targets') t;
    IF destinations->>'targets_digest' IS DISTINCT FROM encode(digest(convert_to(captured_targets::text,'UTF8'),'sha256'),'hex') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered captured destinations changed';END IF;
   END IF;
   checks:=checks||(SELECT jsonb_agg(jsonb_build_object('kind','gateway_device','id',id_value,'permission','manage_workflows') ORDER BY id_value) FROM jsonb_array_elements_text(destinations->'ids') id_value);
   f:=jsonb_set(f,'{fresh_until_ms}',to_jsonb(least((f->>'fresh_until_ms')::bigint,(destinations->>'fresh_until_ms')::bigint)));
  ELSE
   checks:=checks||jsonb_build_array(jsonb_build_object('kind','test','id',a.test_id,'permission','run_tests'),jsonb_build_object('kind',a.target_kind,'id',a.target_id,'permission','run_tests'));
  END IF;
 END IF;
 step_value:=jsonb_build_object('step_id',st.step_id,'action_key',st.action_key,'state',st.state,'version',st.version,'input_digest',encode(st.input_digest,'hex'),'plan_hash',encode(plan_value.plan_hash,'hex'));
 RETURN f||jsonb_build_object('ordered_action_key',st.action_key,'ordered_device_ids',CASE WHEN compensation OR st.step_index=1 THEN '[]'::jsonb ELSE destinations->'ids' END,'checks',checks,'execution_phase',phase,'request_digest',encode(digest(convert_to(q::text,'UTF8'),'sha256'),'hex'),'step',step_value,'effect',effect_value,'destination_digest',destinations->'identity_digest','ordered_targets_digest',destinations->'targets_digest');
END $ordered_effect_source$;

CREATE FUNCTION zasp_authorization80_worker.ordered68_effect_source(phase text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $effect_source$
DECLARE f jsonb;c zasp_authorization80_worker.ordered_effect_scope%ROWTYPE;compensation boolean:=phase IN('effect.read','effect.unknown');BEGIN
 f:=zasp_authorization80_worker.ordered68_effect_metadata(phase,q);
 SELECT * INTO c FROM zasp_authorization80_worker.ordered_effect_scope WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id');
 IF c.run_id IS NULL OR c.action_key IS DISTINCT FROM f->>'ordered_action_key'
 OR NOT compensation AND(NOT c.target_current OR c.fresh_until<=clock_timestamp() OR(c.device_ids,c.destination_digest,c.targets_digest) IS DISTINCT FROM(f->'ordered_device_ids',f->>'destination_digest',f->>'ordered_targets_digest')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered effect projection capture changed';END IF;
 RETURN f;
END $effect_source$;

-- Copy only the current worker proof parser. Its organization-before-parent
-- order, complete lifetime check after source locks and32768-byte cap remain.
DO $ordered_effect_proof$ DECLARE d text;BEGIN
 SELECT pg_get_functiondef('zasp_authorization80_worker.require_planning68(text,jsonb)'::regprocedure) INTO d;
 d:=zasp_authorization80_worker.ordered62_replace(d,E'BEGIN\n',E'BEGIN\n PERFORM pg_advisory_xact_lock_shared(hashtextextended(''zasp-schema-migrations'',0));\n');
 d:=replace(replace(replace(d,'require_planning68','require_ordered68_effect'),'planning68_source','ordered68_effect_source'),'ordered68.planning.','ordered68.');
 d:=zasp_authorization80_worker.ordered62_replace(d,$old$('state','load','prepare','start','result','settle','artifacts','admit','reconcile','late_usage','recovery')$old$,$new$('effect.reserve','effect.start','effect.read','effect.unknown')$new$);
 d:=zasp_authorization80_worker.ordered62_replace(d,$old$('reconcile','late_usage','recovery')$old$,$new$('effect.read','effect.unknown')$new$);
 d:=zasp_authorization80_worker.ordered62_replace(d,E' RETURNS void\n',E' RETURNS jsonb\n');
 d:=zasp_authorization80_worker.ordered62_replace(d,'EXCEPTION WHEN data_exception THEN',E' RETURN proof;\nEXCEPTION WHEN data_exception THEN');
 EXECUTE d;
END $ordered_effect_proof$;

INSERT INTO zasp_authorization80_worker.predecessor_functions
 SELECT oid::regprocedure::text,pg_get_functiondef(oid),proowner::regrole::text,COALESCE(proacl::text,'') FROM pg_proc WHERE oid='zasp_temporal68.effect(jsonb)'::regprocedure;
DO $ordered_effect_boundary$ DECLARE d text;original text;needle text;replacement text;BEGIN
 SELECT definition INTO STRICT original FROM zasp_authorization80_worker.predecessor_functions WHERE signature='zasp_temporal68.effect(jsonb)' AND owner_name='zasp_discovery_authority'
 AND acl='{zasp_discovery_authority=X/zasp_discovery_authority,zasp_temporal_executor=X/zasp_discovery_authority,zasp_temporal_compensation=X/zasp_discovery_authority}';
 -- No outer nested call uses this copy until its own exact phase fence lands.
 d:=zasp_authorization80_worker.ordered62_replace(original,'FUNCTION zasp_temporal68.effect(q jsonb)','FUNCTION zasp_authorization80_worker.ordered68_effect_read(q jsonb)');
 d:=zasp_authorization80_worker.ordered62_replace(d,$old$('reserve','start','unknown','read')$old$,$new$('read')$new$);
 EXECUTE d;
 d:=zasp_authorization80_worker.ordered62_replace(original,'DECLARE o text;', 'DECLARE worker_proof jsonb;o text;');
 d:=zasp_authorization80_worker.ordered62_replace(d,E'BEGIN\n',E'BEGIN\n worker_proof:=zasp_authorization80_worker.require_ordered68_effect(''effect.''||(q->>''operation''),q);\n');
 -- Refuse expiry/reselection between source materialization and the original
 -- reserve query. The native set is compared before any destination is added.
 needle:=$old$   FOR device IN SELECT * FROM jsonb_to_recordset(targets) AS t(device_id text,credential_id text) LOOP$old$;
 replacement:=$new$   IF worker_proof#>>'{facts,ordered_targets_digest}' IS DISTINCT FROM encode(digest(convert_to(targets::text,'UTF8'),'sha256'),'hex') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered reserved destinations changed';END IF;
$new$||needle;
 d:=zasp_authorization80_worker.ordered62_replace(d,needle,replacement);
 needle:=$old$ RETURN to_jsonb(f)||jsonb_build_object('send_permit',permit);$old$;
 replacement:=$new$ IF NOT COALESCE((worker_proof->>'issued_at')::bigint<=floor(extract(epoch FROM clock_timestamp())*1000)::bigint+5000 AND(worker_proof->>'expires_at')::bigint>floor(extract(epoch FROM clock_timestamp())*1000)::bigint AND(worker_proof->>'expires_at')::bigint-(worker_proof->>'issued_at')::bigint BETWEEN 1 AND 60000,false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered effect proof expired';END IF;
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.principal_ready(CASE worker_proof->>'purpose' WHEN 'worker-forward' THEN 'zasp_temporal_executor' WHEN 'captured-compensation' THEN 'zasp_temporal_compensation' END) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered effect session changed after wait';END IF;
 IF NOT live_value THEN RETURN jsonb_build_object('run_id',f.run_id,'step_id',f.step_id,'effect_key',f.effect_key,'generation',f.generation,'state',f.state,'send_permit',false);END IF;
$new$||needle;
 d:=zasp_authorization80_worker.ordered62_replace(d,needle,replacement);
 EXECUTE d;
END $ordered_effect_boundary$;

-- Fixed signing protocol. The phase-specific metadata/materializer,
-- proof clone and exact private native copies must land together before this
-- module is installed or any entry is granted. These are not generic signing
-- helpers: callers cannot select SQL or an arbitrary unsigned payload.
-- Authorization metadata contains only actual identities and digests. The
-- compiled bodies are disclosed separately by begin, after the signed fence.
CREATE FUNCTION zasp_authorization80_worker.ordered68_policy_metadata(operation_value text,q jsonb) RETURNS jsonb
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $metadata$
DECLARE compensation boolean;delivery_value boolean;prepare_value boolean;phase_value text;f jsonb;effect_q jsonb;composition_value jsonb;
 checks jsonb:='[]'::jsonb;policy_ids jsonb:='[]'::jsonb;run_ids jsonb:='[]'::jsonb;marker jsonb;fresh_value bigint;
 t public.zasp_security_agent_temporary_policy_targets%ROWTYPE;v zasp_temporal68.deliveries%ROWTYPE;fx zasp_temporal68.effects%ROWTYPE;
 work public.zasp_policy_deployment_work%ROWTYPE;BEGIN
 -- Preparation is an ordinary forward operation, never a signing purpose. Its
 -- composition is captured before a delivery row necessarily exists.
 prepare_value:=operation_value='ordered68.delivery.apply.prepare';
 compensation:=CASE WHEN prepare_value THEN false ELSE zasp_authorization80_worker.ordered68_policy_purpose(operation_value)='captured-compensation' END;
 delivery_value:=prepare_value OR operation_value IN('ordered68.delivery.apply.store','ordered68.delivery.cleanup.store');
 phase_value:=CASE WHEN compensation THEN 'cleanup' ELSE 'apply' END;
 IF NOT COALESCE(octet_length(q::text)<=4096 AND q->'generation'='1'::jsonb
 AND q->>'operation'=CASE WHEN prepare_value THEN 'prepare' WHEN delivery_value THEN 'store' WHEN operation_value='ordered68.cleanup.renew' THEN 'renew' ELSE 'source' END
 AND public.zasp_valid_product_id(q#>>'{payload,device_id}'),false)
 OR NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload'])
 OR NOT zasp_sa_multistep_prior.closed(q->'payload',CASE WHEN delivery_value THEN ARRAY['device_id','phase'] WHEN operation_value='ordered68.cleanup.renew' THEN ARRAY['device_id','source_digest'] ELSE ARRAY['device_id'] END)
 OR delivery_value AND q#>>'{payload,phase}' IS DISTINCT FROM phase_value
 OR operation_value='ordered68.cleanup.renew' AND NOT COALESCE(q#>>'{payload,source_digest}'~'^sha256:[a-f0-9]{64}$',false)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered signing reference rejected';END IF;
 -- Retain the admitted parent, original native effect and complete destination
 -- digest. Compensation chooses only its captured path; no forward resolver.
 effect_q:=q||jsonb_build_object('operation',CASE WHEN compensation THEN 'read' ELSE 'start' END,'payload','{}'::jsonb);
 f:=zasp_authorization80_worker.ordered68_effect_source(CASE WHEN compensation THEN 'effect.read' ELSE 'effect.start' END,effect_q);
 IF f->>'ordered_action_key' IS DISTINCT FROM 'create_temporary_policy' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signing effect rejected';END IF;
 SELECT * INTO STRICT fx FROM zasp_temporal68.effects WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation)
 =(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id',1) FOR SHARE;
 IF fx.state NOT IN('started','unknown','cleanup_pending','cleaned') OR NOT compensation AND NOT delivery_value AND fx.state NOT IN('started','unknown')
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered signing intent unavailable';END IF;
 IF compensation THEN PERFORM zasp_temporal68.cleanup_current(fx.organization_id,fx.workspace_id,fx.environment_id,fx.run_id,fx.step_id);
 ELSE PERFORM zasp_sa_multistep_prior.application_current(fx.organization_id,fx.workspace_id,fx.environment_id,fx.run_id,fx.step_id);END IF;
 SELECT * INTO t FROM public.zasp_security_agent_temporary_policy_targets
 WHERE(organization_id,workspace_id,environment_id,run_id,step_id,device_id,phase)=(fx.organization_id,fx.workspace_id,fx.environment_id,fx.run_id,fx.step_id,q#>>'{payload,device_id}',phase_value) FOR UPDATE;
 IF t.device_id IS NULL OR t.action_key IS DISTINCT FROM 'create_temporary_policy'
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(fx.snapshot->'targets') x WHERE(x->>'device_id',x->>'credential_id')=(t.device_id,t.credential_id))
 OR NOT compensation AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(fx.snapshot->'targets') x WHERE(x->>'device_id',x->'sequence',x->'policy_version')=(t.device_id,to_jsonb(t.sequence),to_jsonb(t.policy_version)))
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered signing captured destination changed';END IF;
 IF compensation THEN marker:=zasp_temporal68.cleanup_marker(t);END IF;
 IF delivery_value THEN
  SELECT * INTO v FROM zasp_temporal68.deliveries
  WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation,device_id,phase)=(fx.organization_id,fx.workspace_id,fx.environment_id,fx.run_id,fx.step_id,1,t.device_id,phase_value) FOR UPDATE;
  SELECT * INTO work FROM public.zasp_policy_deployment_work WHERE(organization_id,workspace_id,environment_id,device_id)=(t.organization_id,t.workspace_id,t.environment_id,t.device_id) FOR SHARE;
  composition_value:=CASE WHEN compensation THEN zasp_temporal68.cleanup_composition(t.organization_id,t.workspace_id,t.environment_id,t.device_id,t.run_id,t.step_id) ELSE zasp_sa_multistep_prior.deployment_composition(t.organization_id,t.workspace_id,t.environment_id,t.device_id) END;
  IF t.state NOT IN('stored','verified') OR t.envelope_digest IS NULL OR t.desired_generation IS NULL
  OR work.device_id IS NULL OR work.state='leased' OR work.lease_token IS NOT NULL OR work.lease_owner IS NOT NULL OR work.lease_expires_at IS NOT NULL
  OR v.run_id IS NULL AND NOT prepare_value OR v.run_id IS NOT NULL AND(v.state NOT IN('prepared','stored','read','acknowledged')
   OR(v.source_sequence,v.source_digest,v.credential_id,v.desired_generation,v.composition) IS DISTINCT FROM(t.sequence,t.envelope_digest,t.credential_id,work.desired_generation,composition_value))
  OR v.run_id IS NULL AND prepare_value AND work.applied_generation>=work.desired_generation
  OR (CASE WHEN compensation THEN work.desired_generation<t.desired_generation ELSE work.desired_generation IS DISTINCT FROM t.desired_generation END)
  OR(compensation AND v.state<>'acknowledged' AND(marker->>'expires_at')::timestamptz<=clock_timestamp())
  OR NOT COALESCE((composition_value->>'expires_at')::timestamptz>clock_timestamp()+interval '1 minute',false)
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered signing composition changed';END IF;
  IF compensation THEN PERFORM zasp_temporal68.delivery_history(t);END IF;
  SELECT COALESCE(jsonb_agg(id ORDER BY id COLLATE "C"),'[]'::jsonb) INTO policy_ids FROM(SELECT value->>'id' id FROM jsonb_array_elements(composition_value->'persistent_sources')) p;
  SELECT COALESCE(jsonb_agg(id ORDER BY id COLLATE "C"),'[]'::jsonb) INTO run_ids FROM(SELECT DISTINCT value->>'run_id' id FROM jsonb_array_elements(composition_value->'temporary_sources')) p;
  IF jsonb_array_length(policy_ids)>100 OR jsonb_array_length(run_ids)>100
   OR NOT compensation AND jsonb_array_length(run_ids)<1
   OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(policy_ids||run_ids) x WHERE NOT COALESCE(public.zasp_valid_product_id(x),false))
   OR(SELECT count(*)<>count(DISTINCT x) FROM jsonb_array_elements_text(policy_ids) x)
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered signing composition identities changed';END IF;
 ELSE
  IF t.state NOT IN('planned','stored','verified') OR operation_value='ordered68.cleanup.renew' AND(t.state<>'stored'
   OR q#>>'{payload,source_digest}' IS DISTINCT FROM 'sha256:'||encode(t.envelope_digest,'hex'))
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered signing source state changed';END IF;
 END IF;
 IF NOT compensation THEN
  checks:=jsonb_build_array(jsonb_build_object('kind','security_agent','id',f->>'definition_id','permission','manage_workflows'),jsonb_build_object('kind','security_agent_run','id',f->>'run_id','permission','manage_workflows'),jsonb_build_object('kind','gateway_device','id',t.device_id,'permission','manage_workflows'))
   ||COALESCE((SELECT jsonb_agg(jsonb_build_object('kind','policy','id',x,'permission','view') ORDER BY x COLLATE "C") FROM jsonb_array_elements_text(policy_ids) x),'[]'::jsonb)
   ||COALESCE((SELECT jsonb_agg(jsonb_build_object('kind','security_agent_run','id',x,'permission','view') ORDER BY x COLLATE "C") FROM jsonb_array_elements_text(run_ids) x),'[]'::jsonb);
  fresh_value:=(f->>'fresh_until_ms')::bigint;
  IF delivery_value THEN fresh_value:=least(fresh_value,floor(extract(epoch FROM(composition_value->>'expires_at')::timestamptz)*1000)::bigint);END IF;
  f:=jsonb_set(f,'{fresh_until_ms}',to_jsonb(fresh_value));
 END IF;
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.current_ready()
 OR NOT zasp_temporal68.principal_ready(CASE WHEN compensation THEN 'zasp_temporal_compensation' ELSE 'zasp_temporal_executor' END)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signing session changed after wait';END IF;
 RETURN f||jsonb_build_object('ordered_device_ids','[]'::jsonb,'ordered_policy_device_id',t.device_id,'ordered_policy_ids',CASE WHEN compensation THEN '[]'::jsonb ELSE policy_ids END,'ordered_source_run_ids',CASE WHEN compensation THEN '[]'::jsonb ELSE run_ids END,
 'checks',checks,'execution_phase',operation_value,'request_digest',encode(digest(convert_to(q::text,'UTF8'),'sha256'),'hex'),
 'signing_target_digest',encode(digest(convert_to(zasp_authorization80_worker.ordered68_row_json(t)::text,'UTF8'),'sha256'),'hex'),
 'signing_delivery_digest',CASE WHEN delivery_value AND v.run_id IS NOT NULL THEN encode(digest(convert_to(zasp_authorization80_worker.ordered68_row_json(v)::text,'UTF8'),'sha256'),'hex') ELSE NULL END,
 'signing_composition_digest',CASE WHEN delivery_value THEN encode(digest(convert_to(composition_value::text,'UTF8'),'sha256'),'hex') ELSE NULL END,
 'signing_marker_digest',CASE WHEN compensation THEN encode(digest(convert_to(marker::text,'UTF8'),'sha256'),'hex') ELSE NULL END);
END $metadata$;

-- These are derived task grants, not a caller-provided policy allowlist. Every
-- refresh comes from an admitted effect and the retained native composition.
CREATE TABLE zasp_authorization80_worker.ordered_policy_scope(
 organization_id text NOT NULL,workspace_id text NOT NULL,environment_id text NOT NULL,run_id text NOT NULL,step_id text NOT NULL,device_id text NOT NULL,
 operation text NOT NULL CHECK(operation IN('ordered68.application.source','ordered68.delivery.apply.prepare','ordered68.delivery.apply.store')),
 policy_ids jsonb NOT NULL,source_run_ids jsonb NOT NULL,target_digest text NOT NULL,delivery_digest text,composition_digest text,
 fresh_until timestamptz NOT NULL,target_current boolean NOT NULL,
 PRIMARY KEY(organization_id,workspace_id,environment_id,run_id,step_id,device_id,operation),
 FOREIGN KEY(organization_id,workspace_id,environment_id,run_id,step_id) REFERENCES zasp_authorization80_worker.ordered_effect_scope,
 CHECK(jsonb_typeof(policy_ids)='array' AND jsonb_array_length(policy_ids)<=100 AND jsonb_typeof(source_run_ids)='array' AND jsonb_array_length(source_run_ids)<=100
 AND target_digest~'^[a-f0-9]{64}$' AND CASE operation WHEN 'ordered68.application.source' THEN policy_ids='[]'::jsonb AND source_run_ids='[]'::jsonb AND delivery_digest IS NULL AND composition_digest IS NULL
 ELSE jsonb_array_length(source_run_ids)>0 AND(operation='ordered68.delivery.apply.prepare' AND delivery_digest IS NULL OR delivery_digest IS NOT NULL AND delivery_digest~'^[a-f0-9]{64}$') AND composition_digest IS NOT NULL AND composition_digest~'^[a-f0-9]{64}$' END));
ALTER TABLE zasp_authorization80_worker.ordered_policy_scope OWNER TO zasp_discovery_authority;
ALTER TABLE zasp_authorization80_worker.ordered_policy_scope ENABLE ROW LEVEL SECURITY;
ALTER TABLE zasp_authorization80_worker.ordered_policy_scope FORCE ROW LEVEL SECURITY;
CREATE POLICY authority ON zasp_authorization80_worker.ordered_policy_scope TO zasp_discovery_authority USING(true) WITH CHECK(true);
CREATE TRIGGER no_truncate BEFORE TRUNCATE ON zasp_authorization80_worker.ordered_policy_scope FOR EACH STATEMENT EXECUTE FUNCTION zasp_temporal67.immutable();
CREATE TRIGGER worker_revision AFTER INSERT OR UPDATE OR DELETE ON zasp_authorization80_worker.ordered_policy_scope FOR EACH ROW EXECUTE FUNCTION zasp_authorization79.capture('organization_id','organization_id,workspace_id,environment_id,run_id,step_id,device_id,operation,policy_ids,source_run_ids,target_digest,delivery_digest,composition_digest,fresh_until,target_current');

CREATE FUNCTION zasp_authorization80_worker.prepare_ordered68_policy(operation_value text,q jsonb) RETURNS void
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $prepare_policy$
DECLARE f jsonb;BEGIN
 IF operation_value IS NULL OR operation_value NOT IN('ordered68.application.source','ordered68.delivery.apply.prepare','ordered68.delivery.apply.store')
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered forward policy projection operation rejected';END IF;
 f:=zasp_authorization80_worker.ordered68_policy_metadata(operation_value,q);
 INSERT INTO zasp_authorization80_worker.ordered_policy_scope AS c VALUES(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id',f->>'ordered_policy_device_id',operation_value,
 f->'ordered_policy_ids',f->'ordered_source_run_ids',f->>'signing_target_digest',f->>'signing_delivery_digest',f->>'signing_composition_digest',to_timestamp((f->>'fresh_until_ms')::numeric/1000),true)
 ON CONFLICT(organization_id,workspace_id,environment_id,run_id,step_id,device_id,operation) DO UPDATE SET
 policy_ids=EXCLUDED.policy_ids,source_run_ids=EXCLUDED.source_run_ids,target_digest=EXCLUDED.target_digest,delivery_digest=EXCLUDED.delivery_digest,composition_digest=EXCLUDED.composition_digest,fresh_until=EXCLUDED.fresh_until,target_current=true
 WHERE(c.policy_ids,c.source_run_ids,c.target_digest,c.delivery_digest,c.composition_digest,c.fresh_until,c.target_current)
 IS DISTINCT FROM(EXCLUDED.policy_ids,EXCLUDED.source_run_ids,EXCLUDED.target_digest,EXCLUDED.delivery_digest,EXCLUDED.composition_digest,EXCLUDED.fresh_until,true);
END $prepare_policy$;

CREATE FUNCTION zasp_authorization80_worker.ordered68_policy_source(operation_value text,q jsonb) RETURNS jsonb
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $policy_source$
DECLARE f jsonb;c zasp_authorization80_worker.ordered_policy_scope%ROWTYPE;BEGIN
 f:=zasp_authorization80_worker.ordered68_policy_metadata(operation_value,q);
 IF (CASE WHEN operation_value='ordered68.delivery.apply.prepare' THEN true ELSE zasp_authorization80_worker.ordered68_policy_purpose(operation_value)='worker-forward' END) THEN
  SELECT * INTO c FROM zasp_authorization80_worker.ordered_policy_scope WHERE(organization_id,workspace_id,environment_id,run_id,step_id,device_id,operation)
   =(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id',f->>'ordered_policy_device_id',operation_value) FOR SHARE;
  IF c.run_id IS NULL OR NOT c.target_current OR c.fresh_until<=clock_timestamp()
  OR(c.policy_ids,c.source_run_ids,c.target_digest,c.delivery_digest,c.composition_digest)
  IS DISTINCT FROM(f->'ordered_policy_ids',f->'ordered_source_run_ids',f->>'signing_target_digest',f->>'signing_delivery_digest',f->>'signing_composition_digest')
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered signing projection capture changed';END IF;
 END IF;
 RETURN f;
END $policy_source$;

CREATE FUNCTION zasp_authorization80_worker.capture_ordered_policy() RETURNS trigger
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $capture_policy$
DECLARE a jsonb;b jsonb;BEGIN
 IF TG_OP<>'INSERT' THEN a:=to_jsonb(OLD);END IF;
 IF TG_OP<>'DELETE' THEN b:=to_jsonb(NEW);END IF;
 IF TG_OP='UPDATE' AND a=b THEN RETURN NEW;END IF;
 IF TG_TABLE_NAME='zasp_workflow_records' AND COALESCE(a->>'kind','')<>'policy' AND COALESCE(b->>'kind','')<>'policy' THEN
  IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
 END IF;
 UPDATE zasp_authorization80_worker.ordered_policy_scope c SET target_current=false WHERE c.target_current
 AND((c.organization_id,c.workspace_id,c.environment_id)=(a->>'organization_id',a->>'workspace_id',a->>'environment_id')
 OR(c.organization_id,c.workspace_id,c.environment_id)=(b->>'organization_id',b->>'workspace_id',b->>'environment_id'))
 AND(TG_TABLE_NAME='zasp_workflow_records' AND c.operation IN('ordered68.delivery.apply.prepare','ordered68.delivery.apply.store')
 OR TG_TABLE_NAME<>'zasp_workflow_records' AND(c.device_id=a->>'device_id' OR c.device_id=b->>'device_id'));
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $capture_policy$;
DO $policy_capture$ DECLARE n text;BEGIN
 FOREACH n IN ARRAY ARRAY['zasp_workflow_records','zasp_security_agent_temporary_policy_targets'] LOOP
  EXECUTE format('CREATE TRIGGER zasp_authorization80_worker_ordered_policy BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION zasp_authorization80_worker.capture_ordered_policy()',n);
  EXECUTE format('CREATE TRIGGER zasp_authorization80_worker_ordered_policy_no_truncate BEFORE TRUNCATE ON public.%I FOR EACH STATEMENT EXECUTE FUNCTION zasp_temporal67.immutable()',n);
 END LOOP;
 CREATE TRIGGER ordered_policy_capture BEFORE INSERT OR UPDATE OR DELETE ON zasp_temporal68.deliveries FOR EACH ROW EXECUTE FUNCTION zasp_authorization80_worker.capture_ordered_policy();
 CREATE TRIGGER ordered_policy_no_truncate BEFORE TRUNCATE ON zasp_temporal68.deliveries FOR EACH STATEMENT EXECUTE FUNCTION zasp_temporal67.immutable();
END $policy_capture$;

CREATE FUNCTION zasp_authorization80_worker.expire_ordered_policies(o text) RETURNS void
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $policy_expiry$
BEGIN
 IF NOT zasp_authorization79.worker() OR NOT zasp_authorization79.locked(o) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered policy expiry session rejected';END IF;
 UPDATE zasp_authorization80_worker.ordered_policy_scope SET target_current=false WHERE organization_id=o AND target_current AND fresh_until<=clock_timestamp();
END $policy_expiry$;

CREATE VIEW zasp_authorization80_worker.active_ordered_policies AS
 SELECT a.*,c.device_id,c.operation,c.policy_ids,c.source_run_ids FROM zasp_authorization80_worker.active_ordered_effects a
 JOIN zasp_authorization80_worker.ordered_policy_scope c USING(organization_id,workspace_id,environment_id,run_id,step_id)
 WHERE a.action_key='create_temporary_policy' AND c.target_current AND c.fresh_until>clock_timestamp();
ALTER VIEW zasp_authorization80_worker.active_ordered_policies OWNER TO zasp_discovery_authority;
DO $policy_views$ DECLARE d text;BEGIN
 SELECT pg_get_viewdef('zasp_authorization79.current_grants'::regclass) INTO d;
 EXECUTE 'CREATE OR REPLACE VIEW zasp_authorization79.current_grants AS '||rtrim(d,E';\n ')||$grants$
 UNION SELECT a.organization_id,a.workspace_id,a.environment_id,'policy'::text,t.id,'service'::text,a.principal_id,'view'::text,a.run_id FROM zasp_authorization80_worker.active_ordered_policies a CROSS JOIN LATERAL jsonb_array_elements_text(a.policy_ids) t(id)
 UNION SELECT a.organization_id,a.workspace_id,a.environment_id,'security_agent_run'::text,t.id,'service'::text,a.principal_id,'view'::text,a.run_id FROM zasp_authorization80_worker.active_ordered_policies a CROSS JOIN LATERAL jsonb_array_elements_text(a.source_run_ids) t(id)$grants$;
END $policy_views$;

INSERT INTO zasp_authorization80_worker.predecessor_functions
 SELECT oid::regprocedure::text,pg_get_functiondef(oid),proowner::regrole::text,COALESCE(proacl::text,'') FROM pg_proc
 WHERE oid IN('zasp_temporal68.application(jsonb)'::regprocedure,'zasp_temporal68.cleanup(jsonb)'::regprocedure,'zasp_temporal68.delivery(jsonb)'::regprocedure);

-- Each copy keeps the exact native predicates and mutations but restricts the
-- request operation itself. No grant exposes these copies, and no live outer
-- function is replaced by this staging block.
DO $private_signing_bodies$ DECLARE p record;d text;old_set text;new_set text;copy_name text;expected_acl text;BEGIN
 FOR p IN SELECT * FROM zasp_authorization80_worker.predecessor_functions
 WHERE signature IN('zasp_temporal68.application(jsonb)','zasp_temporal68.cleanup(jsonb)','zasp_temporal68.delivery(jsonb)') LOOP
  IF p.signature='zasp_temporal68.application(jsonb)' THEN
   copy_name:='ordered68_application_source';old_set:=$ops$('read','source','complete')$ops$;new_set:=$ops$('source')$ops$;
   expected_acl:='{zasp_discovery_authority=X/zasp_discovery_authority,zasp_temporal_executor=X/zasp_discovery_authority}';
  ELSIF p.signature='zasp_temporal68.cleanup(jsonb)' THEN
   copy_name:='ordered68_cleanup_source';old_set:=$ops$('prepare','read','source','renew','unknown','complete')$ops$;new_set:=$ops$('source','renew')$ops$;
   expected_acl:='{zasp_discovery_authority=X/zasp_discovery_authority,zasp_temporal_executor=X/zasp_discovery_authority,zasp_temporal_compensation=X/zasp_discovery_authority}';
  ELSE
   copy_name:='ordered68_delivery_store';old_set:=$ops$('prepare','store','read','ack')$ops$;new_set:=$ops$('store')$ops$;
   expected_acl:='{zasp_discovery_authority=X/zasp_discovery_authority,zasp_temporal_executor=X/zasp_discovery_authority,zasp_temporal_compensation=X/zasp_discovery_authority}';
  END IF;
  IF p.owner_name<>'zasp_discovery_authority' OR p.acl<>expected_acl THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='ordered private signing identity changed';END IF;
  d:=zasp_authorization80_worker.ordered62_replace(p.definition,'FUNCTION '||replace(p.signature,'jsonb','q jsonb'),'FUNCTION zasp_authorization80_worker.'||copy_name||'(q jsonb)');
  d:=zasp_authorization80_worker.ordered62_replace(d,old_set,new_set);
  d:=zasp_authorization80_worker.ordered62_replace(d,$read$zasp_temporal68.effect(q||jsonb_build_object('operation','read','payload','{}'::jsonb))$read$,$read$zasp_authorization80_worker.ordered68_effect_read(q||jsonb_build_object('operation','read','payload','{}'::jsonb))$read$);
  EXECUTE d;
  EXECUTE format('ALTER FUNCTION zasp_authorization80_worker.%I(jsonb) OWNER TO zasp_discovery_authority',copy_name);
  EXECUTE format('REVOKE ALL ON FUNCTION zasp_authorization80_worker.%I(jsonb) FROM PUBLIC',copy_name);
 END LOOP;
END $private_signing_bodies$;

DO $policy_proof$ DECLARE d text;BEGIN
 SELECT pg_get_functiondef('zasp_authorization80_worker.require_planning68(text,jsonb)'::regprocedure) INTO d;
 d:=zasp_authorization80_worker.ordered62_replace(d,E'BEGIN\n',E'BEGIN\n PERFORM pg_advisory_xact_lock_shared(hashtextextended(''zasp-schema-migrations'',0));\n');
 d:=replace(replace(d,'require_planning68','require_ordered68_policy'),'planning68_source','ordered68_policy_source');
 d:=zasp_authorization80_worker.ordered62_replace(d,$old$('state','load','prepare','start','result','settle','artifacts','admit','reconcile','late_usage','recovery')$old$,$new$('ordered68.application.source','ordered68.delivery.apply.store','ordered68.cleanup.source','ordered68.cleanup.renew','ordered68.delivery.cleanup.store')$new$);
 d:=zasp_authorization80_worker.ordered62_replace(d,$old$('reconcile','late_usage','recovery')$old$,$new$('ordered68.cleanup.source','ordered68.cleanup.renew','ordered68.delivery.cleanup.store')$new$);
 d:=zasp_authorization80_worker.ordered62_replace(d,$old$proof->>'operation'='ordered68.planning.'||phase$old$,$new$proof->>'operation'=phase$new$);
 d:=zasp_authorization80_worker.ordered62_replace(d,E' RETURNS void\n',E' RETURNS jsonb\n');
 d:=zasp_authorization80_worker.ordered62_replace(d,'EXCEPTION WHEN data_exception THEN',E' RETURN proof;\nEXCEPTION WHEN data_exception THEN');
 EXECUTE d;
END $policy_proof$;

CREATE FUNCTION zasp_authorization80_worker.ordered68_policy_purpose(operation_value text) RETURNS text
 LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public AS $purpose$
BEGIN
 CASE operation_value
 WHEN 'ordered68.application.source','ordered68.delivery.apply.store' THEN RETURN 'worker-forward';
 WHEN 'ordered68.cleanup.source','ordered68.cleanup.renew','ordered68.delivery.cleanup.store' THEN RETURN 'captured-compensation';
 ELSE RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signing operation rejected';
 END CASE;
END $purpose$;

CREATE FUNCTION zasp_authorization80_worker.ordered68_policy_proof_time(proof jsonb) RETURNS void
 LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog,public AS $time$
DECLARE now_ms bigint:=floor(extract(epoch FROM clock_timestamp())*1000)::bigint;BEGIN
 IF NOT COALESCE((proof->>'issued_at')::bigint<=now_ms+5000 AND(proof->>'expires_at')::bigint>now_ms
 AND(proof->>'expires_at')::bigint-(proof->>'issued_at')::bigint BETWEEN 1 AND 60000,false)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signing proof expired after wait';END IF;
END $time$;

-- This private materializer consumes the same validated compact metadata as
-- the proof source, then rereads its actual native rows. No endpoint, secret or
-- fresh resolver is accepted from the caller; only the native compiled set is
-- disclosed to the local signer after begin's proof check.
CREATE FUNCTION zasp_authorization80_worker.ordered68_policy_input(operation_value text,q jsonb,key_id_value text,issued_value bigint,verified_facts jsonb) RETURNS jsonb
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $input$
DECLARE phase_value text;policies_value jsonb;sequence_value bigint;version_value bigint;expires_value bigint;ttl integer;old_envelope jsonb;marker jsonb;
 t public.zasp_security_agent_temporary_policy_targets%ROWTYPE;v zasp_temporal68.deliveries%ROWTYPE;BEGIN
 -- Only begin/store call this owner-only helper, with the source equality
 -- already checked by their local proof parser. No facts cross native calls.
 phase_value:=CASE WHEN zasp_authorization80_worker.ordered68_policy_purpose(operation_value)='worker-forward' THEN 'apply' ELSE 'cleanup' END;
 SELECT * INTO STRICT t FROM public.zasp_security_agent_temporary_policy_targets
 WHERE(organization_id,workspace_id,environment_id,run_id,step_id,device_id,phase)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id',q#>>'{payload,device_id}',phase_value) FOR UPDATE;
 IF verified_facts->>'signing_target_digest' IS DISTINCT FROM encode(digest(convert_to(zasp_authorization80_worker.ordered68_row_json(t)::text,'UTF8'),'sha256'),'hex')
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered native signing target changed';END IF;
 IF operation_value IN('ordered68.delivery.apply.store','ordered68.delivery.cleanup.store') THEN
  SELECT * INTO STRICT v FROM zasp_temporal68.deliveries
  WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation,phase,device_id)=(t.organization_id,t.workspace_id,t.environment_id,t.run_id,t.step_id,1,phase_value,t.device_id) FOR UPDATE;
  IF verified_facts->>'signing_delivery_digest' IS DISTINCT FROM encode(digest(convert_to(zasp_authorization80_worker.ordered68_row_json(v)::text,'UTF8'),'sha256'),'hex')
  OR v.state NOT IN('prepared','stored','read','acknowledged')
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered native signing delivery changed';END IF;
  sequence_value:=v.sequence;version_value:=v.sequence;policies_value:=v.composition->'policies';
  expires_value:=floor(extract(epoch FROM(v.composition->>'expires_at')::timestamptz))::bigint;
  IF v.state<>'prepared' THEN old_envelope:=v.envelope;END IF;
 ELSE
  sequence_value:=t.sequence;version_value:=t.policy_version;
  IF phase_value='apply' THEN
   SELECT(plan->'steps'->0->>'ttl_seconds')::integer INTO STRICT ttl FROM public.zasp_security_agent_plans
   WHERE(organization_id,workspace_id,environment_id,run_id)=(t.organization_id,t.workspace_id,t.environment_id,t.run_id);
   IF ttl NOT BETWEEN 60 AND 3600 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered native signing ttl changed';END IF;
   policies_value:=zasp_sa_multistep_prior.application_policies();
  ELSE ttl:=300;policies_value:='[]'::jsonb;END IF;
  expires_value:=issued_value+ttl;
  IF operation_value='ordered68.cleanup.renew' THEN
   marker:=zasp_temporal68.cleanup_marker(t);
   IF t.state<>'stored' OR q#>>'{payload,source_digest}' IS DISTINCT FROM 'sha256:'||encode(t.envelope_digest,'hex')
    OR verified_facts->>'signing_marker_digest' IS DISTINCT FROM encode(digest(convert_to(marker::text,'UTF8'),'sha256'),'hex')
   THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered captured renewal changed';END IF;
   IF(marker->>'expires_at')::timestamptz>clock_timestamp() THEN
    -- A completed renewal replays its exact signed input. The original marker
    -- has only timestamps and is not an existing renewal to replay.
    IF marker->>'key_id' IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered renewal window not reached';END IF;
    old_envelope:=marker;
   ELSIF to_timestamp(issued_value)<(marker->>'expires_at')::timestamptz THEN
    RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered renewal precedes captured marker';
   END IF;
  ELSIF t.state<>'planned' THEN
   IF t.state NOT IN('stored','verified') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered source state changed';END IF;
   old_envelope:=jsonb_build_object('key_id',t.key_id,'issued_at',t.issued_at,'expires_at',t.expires_at,'policies',t.policies);
  END IF;
 END IF;
 IF old_envelope IS NOT NULL THEN
  IF old_envelope->>'key_id' IS DISTINCT FROM key_id_value OR old_envelope->'policies' IS DISTINCT FROM policies_value
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered signing replay identity changed';END IF;
  issued_value:=floor(extract(epoch FROM(old_envelope->>'issued_at')::timestamptz))::bigint;
  expires_value:=floor(extract(epoch FROM(old_envelope->>'expires_at')::timestamptz))::bigint;
 END IF;
 IF NOT COALESCE(sequence_value>0 AND version_value>0 AND issued_value<=floor(extract(epoch FROM clock_timestamp()))::bigint+5
 AND expires_value>floor(extract(epoch FROM clock_timestamp()))::bigint AND expires_value-issued_value BETWEEN 1 AND 86400
 AND jsonb_typeof(policies_value)='array' AND jsonb_array_length(policies_value)<=100,false)
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered native signing input expired';END IF;
 RETURN jsonb_build_object('contract_version',1,'operation',operation_value,'decision_digest',encode(digest(convert_to(current_setting('zasp.worker_proof'),'UTF8'),'sha256'),'hex'),
 'key_id',key_id_value,'organization_id',t.organization_id,'workspace_id',t.workspace_id,'environment_id',t.environment_id,'device_id',t.device_id,
 'sequence',sequence_value,'policy_version',version_value,'issued_at',issued_value,'expires_at',expires_value,'failure_mode','closed','policies',policies_value);
END $input$;

CREATE FUNCTION zasp_authorization80_worker.ordered68_policy_begin(operation_value text,q jsonb,key_id_value text) RETURNS bytea
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $begin$
DECLARE proof jsonb;input_value jsonb;result bytea;BEGIN
 PERFORM zasp_authorization80_worker.ordered68_policy_purpose(operation_value);
 IF NOT COALESCE(key_id_value~'^[a-z][a-z0-9_-]{7,63}$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered signing key rejected';END IF;
 -- The shared proof clone validates the exact original q and database session,
 -- takes organization before parent/target locks, and rechecks after its source.
 proof:=zasp_authorization80_worker.require_ordered68_policy(operation_value,q);
 input_value:=zasp_authorization80_worker.ordered68_policy_input(operation_value,q,key_id_value,floor(extract(epoch FROM clock_timestamp()))::bigint,proof->'facts');
 PERFORM zasp_authorization80_worker.ordered68_policy_proof_time(proof);
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.current_ready() OR NOT zasp_temporal68.principal_ready(CASE proof->>'purpose' WHEN 'worker-forward' THEN 'zasp_temporal_executor' WHEN 'captured-compensation' THEN 'zasp_temporal_compensation' END) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signing session changed';END IF;
 result:=convert_to(zasp_sa_multistep_prior.deployment_json(input_value),'UTF8');
 IF octet_length(result) NOT BETWEEN 1 AND 1048576 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered signing input bound';END IF;
 RETURN result;
END $begin$;

CREATE FUNCTION zasp_authorization80_worker.ordered68_policy_store(operation_value text,q jsonb,key_id_value text,input_bytes bytea,envelope_bytes bytea,mac_value text) RETURNS jsonb
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $store$
DECLARE proof jsonb;purpose_value text;k bytea;input_json json;envelope_json json;input_value jsonb;expected jsonb;env jsonb;payload jsonb;native_q jsonb;result jsonb;
 t public.zasp_security_agent_temporary_policy_targets%ROWTYPE;message_bytes bytea;zero_byte bytea:=decode('00','hex');digest_value text;BEGIN
 purpose_value:=zasp_authorization80_worker.ordered68_policy_purpose(operation_value);
 proof:=zasp_authorization80_worker.require_ordered68_policy(operation_value,q);
 IF NOT COALESCE(octet_length(input_bytes) BETWEEN 1 AND 1048576 AND octet_length(envelope_bytes) BETWEEN 1 AND 1048576
 AND mac_value~'^[a-f0-9]{64}$' AND key_id_value~'^[a-z][a-z0-9_-]{7,63}$',false)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signed store bound rejected';END IF;
 input_json:=convert_from(input_bytes,'UTF8')::json;envelope_json:=convert_from(envelope_bytes,'UTF8')::json;
 IF NOT zasp_authorization80.unique_json(input_json) OR NOT zasp_authorization80.unique_json(envelope_json)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signed store duplicate fields';END IF;
 input_value:=input_json::jsonb;env:=envelope_json::jsonb;
 IF NOT zasp_sa_multistep_prior.closed(input_value,ARRAY['contract_version','operation','decision_digest','key_id','organization_id','workspace_id','environment_id','device_id','sequence','policy_version','issued_at','expires_at','failure_mode','policies'])
 OR NOT zasp_sa_multistep_prior.closed(env,ARRAY['contract_version','key_id','algorithm','audience','organization_id','workspace_id','environment_id','device_id','sequence','policy_version','issued_at','expires_at','failure_mode','payload_digest','policies','signature'])
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signed store shape rejected';END IF;
 -- Recompute with the original issue time, not a newly sampled signing input.
 -- This reader retains actual source/sequence/composition and current/captured
 -- authority under the same transaction's locks. It performs no fresh lookup
 -- of forward credentials for captured compensation.
 expected:=zasp_authorization80_worker.ordered68_policy_input(operation_value,q,key_id_value,(input_value->>'issued_at')::bigint,proof->'facts');
 IF input_bytes IS DISTINCT FROM convert_to(zasp_sa_multistep_prior.deployment_json(expected),'UTF8')
 OR input_value->>'decision_digest' IS DISTINCT FROM encode(digest(convert_to(current_setting('zasp.worker_proof'),'UTF8'),'sha256'),'hex')
 OR env->'contract_version' IS DISTINCT FROM '1'::jsonb OR env->>'algorithm' IS DISTINCT FROM 'Ed25519' OR env->>'audience' IS DISTINCT FROM 'runtime-gateway-policy'
 OR(env->>'key_id',env->>'organization_id',env->>'workspace_id',env->>'environment_id',env->>'device_id',env->'sequence',env->'policy_version',env->>'failure_mode',env->'policies')
 IS DISTINCT FROM(key_id_value,input_value->>'organization_id',input_value->>'workspace_id',input_value->>'environment_id',input_value->>'device_id',input_value->'sequence',input_value->'policy_version',input_value->>'failure_mode',input_value->'policies')
 OR(env->>'issued_at')::timestamptz IS DISTINCT FROM to_timestamp((input_value->>'issued_at')::bigint)
 OR(env->>'expires_at')::timestamptz IS DISTINCT FROM to_timestamp((input_value->>'expires_at')::bigint)
 OR NOT COALESCE(env->>'payload_digest'~'^[a-f0-9]{64}$' AND env->>'signature'~'^[A-Za-z0-9_-]{86}$',false)
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered signed input changed';END IF;
 SELECT key INTO k FROM zasp_authorization80_worker.verifiers WHERE purpose=purpose_value AND version=proof->>'key_version' FOR SHARE;
 message_bytes:=convert_to('zasp-authorization-ordered68-policy-store-v1','UTF8')||zero_byte||convert_to(purpose_value,'UTF8')||zero_byte
 ||convert_to(encode(digest(convert_to(current_setting('zasp.worker_proof'),'UTF8'),'sha256'),'hex'),'UTF8')||zero_byte
 ||convert_to(encode(digest(input_bytes,'sha256'),'hex'),'UTF8')||zero_byte||convert_to(encode(digest(envelope_bytes,'sha256'),'hex'),'UTF8');
 IF k IS NULL OR mac_value IS DISTINCT FROM encode(hmac(message_bytes,k,'sha256'),'hex')
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signed store verification rejected';END IF;
 PERFORM zasp_authorization80_worker.ordered68_policy_proof_time(proof);
 digest_value:='sha256:'||encode(digest(envelope_bytes,'sha256'),'hex');
 IF operation_value IN('ordered68.delivery.apply.store','ordered68.delivery.cleanup.store') THEN
  payload:=jsonb_build_object('device_id',input_value->>'device_id','phase',CASE WHEN purpose_value='worker-forward' THEN 'apply' ELSE 'cleanup' END,'envelope',env,'digest',digest_value);
  native_q:=q||jsonb_build_object('operation','store','payload',payload);
  result:=zasp_authorization80_worker.ordered68_delivery_store(native_q);
 ELSE
  SELECT * INTO STRICT t FROM public.zasp_security_agent_temporary_policy_targets
   WHERE(organization_id,workspace_id,environment_id,run_id,step_id,device_id,phase)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id',input_value->>'device_id',CASE WHEN purpose_value='worker-forward' THEN 'apply' ELSE 'cleanup' END) FOR UPDATE;
  payload:=jsonb_build_object('device_id',t.device_id,'credential_id',t.credential_id,'sequence',env->'sequence','policy_version',env->'policy_version','key_id',key_id_value,
   'issued_at',env->>'issued_at','expires_at',env->>'expires_at','failure_mode',env->>'failure_mode','payload_digest','sha256:'||(env->>'payload_digest'),'policies',env->'policies',
   'signature',encode(decode(translate(env->>'signature','-_','+/')||'==','base64'),'base64'),'envelope_digest',digest_value);
  IF operation_value='ordered68.application.source' THEN
   result:=zasp_authorization80_worker.ordered68_application_source(q||jsonb_build_object('operation','source','payload',payload));
  ELSIF operation_value='ordered68.cleanup.source' THEN
   result:=zasp_authorization80_worker.ordered68_cleanup_source(q||jsonb_build_object('operation','source','payload',payload));
  ELSE
   result:=zasp_authorization80_worker.ordered68_cleanup_source(q||jsonb_build_object('operation','renew','payload',jsonb_build_object('source_digest',q#>>'{payload,source_digest}','envelope',payload)));
  END IF;
 END IF;
 -- Native writes can legitimately advance their own source/revision. Do not
 -- compare a prewrite revision to those writes; do reject expiry after waits.
 PERFORM zasp_authorization80_worker.ordered68_policy_proof_time(proof);
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.current_ready() OR NOT zasp_temporal68.principal_ready(CASE purpose_value WHEN 'worker-forward' THEN 'zasp_temporal_executor' WHEN 'captured-compensation' THEN 'zasp_temporal_compensation' END) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signed store session changed';END IF;
 RETURN result;
EXCEPTION WHEN data_exception THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signed store rejected';
END $store$;

-- Every external source/begin/store call keeps a complete schema/readiness
-- bracket. Only this fixed private call graph shares that bracket; no cached
-- authority, caller flag, GUC or cross-request result is trusted.
CREATE FUNCTION zasp_authorization80_worker.ordered68_signing_boundary(operation_value text) RETURNS void
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $signing_boundary$
DECLARE purpose_value text;BEGIN
 purpose_value:=CASE WHEN operation_value='ordered68.delivery.apply.prepare' THEN 'worker-forward' ELSE zasp_authorization80_worker.ordered68_policy_purpose(operation_value) END;
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='ordered signing requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.current_ready()
 OR NOT zasp_temporal68.principal_ready(CASE purpose_value WHEN 'worker-forward' THEN 'zasp_temporal_executor' ELSE 'zasp_temporal_compensation' END)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signing boundary unavailable';END IF;
END $signing_boundary$;
ALTER FUNCTION zasp_authorization80_worker.ordered68_signing_boundary(text) OWNER TO zasp_discovery_authority;
REVOKE ALL ON FUNCTION zasp_authorization80_worker.ordered68_signing_boundary(text) FROM PUBLIC;

DO $ordered_signing_inner$ DECLARE p record;d text;needle text;signature_value regprocedure;n text;BEGIN
 -- Copy the already-fenced worker readers bottom-up. All shape, immutable
 -- association, native domain, lock, principal and expiry checks survive.
 FOR p IN SELECT * FROM(VALUES
  ('ordered68_effect_facts','boolean,jsonb','ordered68_signing_facts_inner',1,NULL::text,NULL::text),
  ('ordered68_effect_metadata','text,jsonb','ordered68_signing_effect_metadata_inner',1,'ordered68_effect_facts','ordered68_signing_facts_inner'),
  ('ordered68_effect_source','text,jsonb','ordered68_signing_effect_source_inner',0,'ordered68_effect_metadata','ordered68_signing_effect_metadata_inner'),
  ('ordered68_policy_metadata','text,jsonb','ordered68_signing_metadata_inner',1,'ordered68_effect_source','ordered68_signing_effect_source_inner'),
  ('ordered68_policy_source','text,jsonb','ordered68_signing_source_inner',0,'ordered68_policy_metadata','ordered68_signing_metadata_inner'),
  ('require_ordered68_policy','text,jsonb','ordered68_signing_proof_inner',0,'ordered68_policy_source','ordered68_signing_source_inner'),
  ('ordered68_effect_read','jsonb','ordered68_signing_read_inner',2,NULL::text,NULL::text)
 ) v(old_name,args,new_name,ready_count,old_callee,new_callee) LOOP
  d:=pg_get_functiondef(('zasp_authorization80_worker.'||p.old_name||'('||p.args||')')::regprocedure);
  d:=zasp_authorization80_worker.ordered62_replace(d,'FUNCTION zasp_authorization80_worker.'||p.old_name||'(','FUNCTION zasp_authorization80_worker.'||p.new_name||'(');
  needle:='zasp_temporal68.current_ready()';
  IF(length(d)-length(replace(d,needle,'')))/length(needle)<>p.ready_count THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='ordered signing inner readiness count changed';END IF;
  d:=replace(d,needle,'zasp_authorization80_worker.catalog_ready()');
  IF p.old_callee IS NOT NULL THEN
   d:=zasp_authorization80_worker.ordered62_replace(d,'zasp_authorization80_worker.'||p.old_callee||'(','zasp_authorization80_worker.'||p.new_callee||'(');
  END IF;
  IF p.old_name='ordered68_effect_read' AND position($read$NOT COALESCE(q->>'operation' IN('read'),false)$read$ IN d)=0 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='ordered signing read-only restriction absent';END IF;
  EXECUTE d;
  signature_value:=('zasp_authorization80_worker.'||p.new_name||'('||p.args||')')::regprocedure;
  EXECUTE format('ALTER FUNCTION %s OWNER TO zasp_discovery_authority',signature_value);
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',signature_value);
 END LOOP;

 -- These three existing owner-only copies are called only from the signed
 -- store below. Their fixed operation restrictions and all native mutations
 -- remain unchanged. The shared effect_read used by other families is intact.
 FOREACH n IN ARRAY ARRAY['ordered68_application_source','ordered68_cleanup_source','ordered68_delivery_store'] LOOP
  SELECT pg_get_functiondef(oid) INTO STRICT d FROM pg_proc WHERE oid=('zasp_authorization80_worker.'||n||'(jsonb)')::regprocedure
   AND proowner='zasp_discovery_authority'::regrole AND proacl::text='{zasp_discovery_authority=X/zasp_discovery_authority}';
  d:=zasp_authorization80_worker.ordered62_replace(d,'zasp_temporal68.current_ready()','zasp_authorization80_worker.catalog_ready()');
  d:=zasp_authorization80_worker.ordered62_replace(d,'zasp_authorization80_worker.ordered68_effect_read(','zasp_authorization80_worker.ordered68_signing_read_inner(');
  EXECUTE d;
 END LOOP;

 -- Each begin/store still independently authenticates the original proof,
 -- re-reads its full source, compares revision/facts and rechecks time. Only
 -- nested catalog traversal changes. Existing full exits remain after writes.
 FOREACH n IN ARRAY ARRAY['ordered68_policy_begin(text,jsonb,text)','ordered68_policy_store(text,jsonb,text,bytea,bytea,text)'] LOOP
  d:=pg_get_functiondef(('zasp_authorization80_worker.'||n)::regprocedure);
  needle:='proof:=zasp_authorization80_worker.require_ordered68_policy(operation_value,q);';
  d:=zasp_authorization80_worker.ordered62_replace(d,needle,E'PERFORM zasp_authorization80_worker.ordered68_signing_boundary(operation_value);\n proof:=zasp_authorization80_worker.ordered68_signing_proof_inner(operation_value,q);');
  needle:='NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.current_ready()';
  IF(length(d)-length(replace(d,needle,'')))/length(needle)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='ordered signing outer exit changed';END IF;
  EXECUTE d;
 END LOOP;
END $ordered_signing_inner$;

-- The Go first/second source reads remain separate complete external calls.
-- No metadata survives from one call to another except the existing signed
-- proof, which begin and store each revalidate against fresh native rows.
CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_policy_source(operation_value text,q jsonb) RETURNS jsonb
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $signing_source_outer$
DECLARE result_value jsonb;BEGIN
 PERFORM zasp_authorization80_worker.ordered68_signing_boundary(operation_value);
 result_value:=zasp_authorization80_worker.ordered68_signing_source_inner(operation_value,q);
 PERFORM zasp_authorization80_worker.ordered68_signing_boundary(operation_value);
 RETURN result_value;
END $signing_source_outer$;

-- Ordinary native operations are distinct from signing. A nested
-- effect read does not turn forward application completion into compensation.
CREATE FUNCTION zasp_authorization80_worker.ordered68_operation_source(operation_value text,q jsonb) RETURNS jsonb
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $source$
DECLARE compensation boolean;delivery_value boolean;phase_value text;f jsonb;effect_q jsonb;evidence jsonb;
 t public.zasp_security_agent_temporary_policy_targets%ROWTYPE;v zasp_temporal68.deliveries%ROWTYPE;
 c zasp_temporal68.cleanups%ROWTYPE;BEGIN
 IF operation_value IS NULL OR operation_value NOT IN('ordered68.application.read','ordered68.application.complete',
 'ordered68.cleanup.prepare','ordered68.cleanup.read','ordered68.cleanup.complete',
 'ordered68.delivery.apply.prepare','ordered68.delivery.apply.read','ordered68.delivery.apply.ack',
 'ordered68.delivery.cleanup.prepare','ordered68.delivery.cleanup.read','ordered68.delivery.cleanup.ack')
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered ordinary operation rejected';END IF;
 compensation:=operation_value NOT IN('ordered68.application.read','ordered68.application.complete','ordered68.delivery.apply.prepare');
 delivery_value:=starts_with(operation_value,'ordered68.delivery.');
 phase_value:=CASE WHEN starts_with(operation_value,'ordered68.delivery.cleanup.') THEN 'cleanup' ELSE 'apply' END;
 IF NOT COALESCE(octet_length(q::text)<=32768 AND q->'generation'='1'::jsonb
 AND q->>'operation'=split_part(operation_value,'.',CASE WHEN delivery_value THEN 4 ELSE 3 END),false)
 OR NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload'])
 OR NOT delivery_value AND q->'payload' IS DISTINCT FROM '{}'::jsonb
 OR delivery_value AND(NOT COALESCE(public.zasp_valid_product_id(q#>>'{payload,device_id}') AND q#>>'{payload,phase}'=phase_value,false)
  OR NOT zasp_sa_multistep_prior.closed(q->'payload',CASE WHEN q->>'operation'='prepare' THEN ARRAY['device_id','phase'] ELSE ARRAY['device_id','phase','digest'] END)
  OR q->>'operation'<>'prepare' AND NOT COALESCE(q#>>'{payload,digest}'~'^sha256:[a-f0-9]{64}$',false))
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered ordinary request rejected';END IF;
 IF operation_value='ordered68.delivery.apply.prepare' THEN
  -- Complete native composition capture precedes the creation of a delivery.
  RETURN zasp_authorization80_worker.ordered68_policy_source(operation_value,q);
 END IF;
 effect_q:=q||jsonb_build_object('operation',CASE WHEN compensation THEN 'read' ELSE 'start' END,'payload','{}'::jsonb);
 f:=zasp_authorization80_worker.ordered68_effect_source(CASE WHEN compensation THEN 'effect.read' ELSE 'effect.start' END,effect_q);
 IF f->>'ordered_action_key' IS DISTINCT FROM 'create_temporary_policy' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered ordinary Block intent rejected';END IF;
 IF NOT compensation THEN
  -- First completion and receipt replay both retain all current native gates.
  PERFORM zasp_sa_multistep_prior.application_current(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id');
 END IF;
 IF delivery_value THEN
  SELECT * INTO t FROM public.zasp_security_agent_temporary_policy_targets
  WHERE(organization_id,workspace_id,environment_id,run_id,step_id,phase,device_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id',phase_value,q#>>'{payload,device_id}') FOR UPDATE;
  IF t.device_id IS NULL OR t.state NOT IN('stored','verified') OR t.envelope_digest IS NULL OR t.desired_generation IS NULL
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered captured delivery target absent';END IF;
  SELECT * INTO v FROM zasp_temporal68.deliveries
  WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation,phase,device_id)=(t.organization_id,t.workspace_id,t.environment_id,t.run_id,t.step_id,1,phase_value,t.device_id) FOR UPDATE;
  IF v.run_id IS NULL AND operation_value<>'ordered68.delivery.cleanup.prepare'
   OR v.run_id IS NOT NULL AND(v.source_sequence,v.source_digest,v.credential_id) IS DISTINCT FROM(t.sequence,t.envelope_digest,t.credential_id)
   OR q->>'operation'<>'prepare' AND(v.state NOT IN('stored','read','acknowledged') OR q#>>'{payload,digest}' IS DISTINCT FROM 'sha256:'||encode(v.envelope_digest,'hex'))
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered captured delivery association changed';END IF;
  IF phase_value='cleanup' THEN
   PERFORM zasp_temporal68.cleanup_current(t.organization_id,t.workspace_id,t.environment_id,t.run_id,t.step_id);
  END IF;
  evidence:=jsonb_build_array(zasp_authorization80_worker.ordered68_row_json(t),zasp_authorization80_worker.ordered68_row_json(v));
 ELSIF starts_with(operation_value,'ordered68.cleanup.') THEN
  SELECT * INTO c FROM zasp_temporal68.cleanups WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation)
   =(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id',1) FOR UPDATE;
  IF c.run_id IS NULL THEN
   IF operation_value<>'ordered68.cleanup.prepare' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered captured cleanup absent';END IF;
   evidence:=zasp_temporal68.cleanup_snapshot(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id');
  ELSE
   PERFORM zasp_temporal68.cleanup_current(c.organization_id,c.workspace_id,c.environment_id,c.run_id,c.step_id);
   evidence:=zasp_authorization80_worker.ordered68_row_json(c);
  END IF;
 ELSE
  -- Bind the actual acknowledged delivery/source/receipt association, including
  -- receipt absence on the first completion. No audit or receipt is fabricated.
  SELECT jsonb_build_array(
   (SELECT COALESCE(jsonb_agg(zasp_authorization80_worker.ordered68_row_json(target_evidence) ORDER BY target_evidence.device_id),'[]'::jsonb) FROM public.zasp_security_agent_temporary_policy_targets target_evidence WHERE(target_evidence.organization_id,target_evidence.workspace_id,target_evidence.environment_id,target_evidence.run_id,target_evidence.step_id,target_evidence.phase)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id','apply')),
   (SELECT COALESCE(jsonb_agg(zasp_authorization80_worker.ordered68_row_json(d) ORDER BY device_id),'[]'::jsonb) FROM zasp_temporal68.deliveries d WHERE(d.organization_id,d.workspace_id,d.environment_id,d.run_id,d.step_id,d.generation,d.phase)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id',1,'apply')),
   (SELECT zasp_authorization80_worker.ordered68_row_json(r) FROM public.zasp_sa_multistep_receipts r WHERE(r.organization_id,r.workspace_id,r.environment_id,r.run_id,r.step_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id'))) INTO evidence;
 END IF;
 IF evidence IS NULL OR NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.current_ready()
 OR NOT zasp_temporal68.principal_ready(CASE WHEN compensation THEN 'zasp_temporal_compensation' ELSE 'zasp_temporal_executor' END)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered ordinary session changed after wait';END IF;
 RETURN f||jsonb_build_object('execution_phase',operation_value,'request_digest',encode(digest(convert_to(q::text,'UTF8'),'sha256'),'hex'),
 'operation_evidence_digest',encode(digest(convert_to(evidence::text,'UTF8'),'sha256'),'hex'));
END $source$;

DO $ordinary_proof$ DECLARE d text;BEGIN
 SELECT pg_get_functiondef('zasp_authorization80_worker.require_planning68(text,jsonb)'::regprocedure) INTO d;
 d:=zasp_authorization80_worker.ordered62_replace(d,E'BEGIN\n',E'BEGIN\n PERFORM pg_advisory_xact_lock_shared(hashtextextended(''zasp-schema-migrations'',0));\n');
 d:=replace(replace(d,'require_planning68','require_ordered68_operation'),'planning68_source','ordered68_operation_source');
 d:=zasp_authorization80_worker.ordered62_replace(d,$old$('state','load','prepare','start','result','settle','artifacts','admit','reconcile','late_usage','recovery')$old$,$new$('ordered68.application.read','ordered68.application.complete','ordered68.cleanup.prepare','ordered68.cleanup.read','ordered68.cleanup.complete','ordered68.delivery.apply.prepare','ordered68.delivery.apply.read','ordered68.delivery.apply.ack','ordered68.delivery.cleanup.prepare','ordered68.delivery.cleanup.read','ordered68.delivery.cleanup.ack')$new$);
 d:=zasp_authorization80_worker.ordered62_replace(d,$old$('reconcile','late_usage','recovery')$old$,$new$('ordered68.cleanup.prepare','ordered68.cleanup.read','ordered68.cleanup.complete','ordered68.delivery.apply.read','ordered68.delivery.apply.ack','ordered68.delivery.cleanup.prepare','ordered68.delivery.cleanup.read','ordered68.delivery.cleanup.ack')$new$);
 d:=zasp_authorization80_worker.ordered62_replace(d,$old$proof->>'operation'='ordered68.planning.'||phase$old$,$new$proof->>'operation'=phase$new$);
 d:=zasp_authorization80_worker.ordered62_replace(d,E' RETURNS void\n',E' RETURNS jsonb\n');
 d:=zasp_authorization80_worker.ordered62_replace(d,'EXCEPTION WHEN data_exception THEN',E' RETURN proof;\nEXCEPTION WHEN data_exception THEN');
 EXECUTE d;
END $ordinary_proof$;

CREATE FUNCTION zasp_authorization80_worker.ordered68_operation_session(proof jsonb) RETURNS void
 LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public AS $session$
BEGIN
 PERFORM zasp_authorization80_worker.ordered68_policy_proof_time(proof);
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.current_ready()
 OR proof->>'session_user' IS DISTINCT FROM session_user
 OR NOT zasp_temporal68.principal_ready(CASE proof->>'purpose' WHEN 'worker-forward' THEN 'zasp_temporal_executor' WHEN 'captured-compensation' THEN 'zasp_temporal_compensation' END)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered ordinary session changed';END IF;
END $session$;

-- Replace only saved exact public entries. Signing source/store operations are
-- refused here; the purpose-bound begin/store protocol uses private copies.
DO $ordinary_boundaries$ DECLARE p record;d text;phase text;needle text;BEGIN
 FOR p IN SELECT * FROM zasp_authorization80_worker.predecessor_functions
 WHERE signature IN('zasp_temporal68.application(jsonb)','zasp_temporal68.cleanup(jsonb)','zasp_temporal68.delivery(jsonb)') LOOP
  IF p.owner_name<>'zasp_discovery_authority' OR p.acl IS DISTINCT FROM (CASE WHEN p.signature='zasp_temporal68.application(jsonb)' THEN '{zasp_discovery_authority=X/zasp_discovery_authority,zasp_temporal_executor=X/zasp_discovery_authority}' ELSE '{zasp_discovery_authority=X/zasp_discovery_authority,zasp_temporal_executor=X/zasp_discovery_authority,zasp_temporal_compensation=X/zasp_discovery_authority}' END)
  THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='ordered ordinary predecessor changed';END IF;
  IF p.signature='zasp_temporal68.application(jsonb)' THEN
   phase:=$phase$'ordered68.application.'||(q->>'operation')$phase$;
   needle:=$last$ IF op='complete' THEN RETURN jsonb_build_object('effect_key',intent->>'effect_key','receipt_kind',receipt.receipt_kind,'receipt',receipt.body,'result_digest','sha256:'||encode(receipt.result_digest,'hex'));END IF;$last$;
  ELSIF p.signature='zasp_temporal68.cleanup(jsonb)' THEN
   phase:=$phase$'ordered68.cleanup.'||(q->>'operation')$phase$;
   needle:=$last$ IF op IN('read','source','renew') THEN$last$;
  ELSE
   phase:=$phase$'ordered68.delivery.'||(q#>>'{payload,phase}')||'.'||(q->>'operation')$phase$;
   needle:=$last$ RETURN response_value;$last$;
  END IF;
  d:=zasp_authorization80_worker.ordered62_replace(p.definition,'DECLARE o text;','DECLARE worker_proof jsonb;o text;');
  d:=zasp_authorization80_worker.ordered62_replace(d,E'BEGIN\n',E'BEGIN\n worker_proof:=zasp_authorization80_worker.require_ordered68_operation('||phase||E',q);\n');
  d:=zasp_authorization80_worker.ordered62_replace(d,$read$zasp_temporal68.effect(q||jsonb_build_object('operation','read','payload','{}'::jsonb))$read$,$read$zasp_authorization80_worker.ordered68_effect_read(q||jsonb_build_object('operation','read','payload','{}'::jsonb))$read$);
  d:=zasp_authorization80_worker.ordered62_replace(d,needle,E' PERFORM zasp_authorization80_worker.ordered68_operation_session(worker_proof);\n'||needle);
  EXECUTE d;
 END LOOP;
END $ordinary_boundaries$;

-- Install after ordered planning/effects. These three compensation-only
-- entries consume retained admission, not a newly minted planning grant.
CREATE FUNCTION zasp_authorization80_worker.ordered69_source(phase text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $lifecycle_source$
DECLARE o text;w text;e text;r text;k text;
 x zasp_temporal66.run_owners%ROWTYPE;c zasp_temporal65.commands%ROWTYPE;m zasp_temporal65.commands%ROWTYPE;
 rr public.zasp_security_agent_runs%ROWTYPE;tr public.zasp_security_agent_trigger_receipts%ROWTYPE;
 h public.zasp_security_agent_definition_versions%ROWTYPE;receipt public.zasp_security_agent_request_receipts%ROWTYPE;a public.zasp_security_agent_audit%ROWTYPE;
 start_receipt_digest text;decision_digest text;source_value jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='ordered lifecycle requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal69.current_ready() OR NOT zasp_temporal68.principal_ready('zasp_temporal_compensation') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered lifecycle principal rejected';END IF;
 IF phase IS NULL OR phase NOT IN('inspect','message','stop') OR octet_length(q::text)>4096 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered lifecycle phase rejected';END IF;
 IF phase='message' THEN
  IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','event_id','decision_id','kind']) OR NOT COALESCE(q->>'kind' IN('approval','cancel'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered lifecycle message rejected';END IF;
  FOREACH k IN ARRAY ARRAY['event_id','decision_id'] LOOP
   IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered lifecycle decision rejected';END IF;
  END LOOP;
 ELSE
  IF NOT zasp_sa_multistep_prior.closed(q,CASE WHEN phase='stop' THEN ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','input_digest','reason'] ELSE ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','input_digest'] END)
   OR jsonb_typeof(q->'definition_version') IS DISTINCT FROM 'number' OR NOT COALESCE(q->>'definition_version'~'^([1-9][0-9]{0,5}|1000000)$',false)
   OR jsonb_typeof(q->'input_digest') IS DISTINCT FROM 'string' OR NOT COALESCE(q->>'input_digest'~'^[a-f0-9]{64}$',false)
   OR phase='stop' AND NOT COALESCE(q->>'reason' IN('workflow_cancelled','workflow_deadline','workflow_failed'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered lifecycle start rejected';END IF;
 END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered lifecycle scope rejected';END IF;
 END LOOP;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';
 PERFORM 1 FROM zasp_authorization79.organizations WHERE organization_id=o FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered lifecycle organization absent';END IF;
 -- Match retained68 status exactly before taking any run/owner/command row.
 -- A predecessor reader can hold this advisory lock without an organization
 -- lock; it must never wait on a row already held by this source.
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 PERFORM 1 FROM public.zasp_security_agent_run_budgets WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO x FROM zasp_temporal66.run_owners WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR SHARE;
 SELECT * INTO c FROM zasp_temporal65.commands WHERE(organization_id,workspace_id,environment_id,run_id,kind)=(o,w,e,r,'start') FOR SHARE;
 IF x.run_id IS NULL OR c.run_id IS NULL OR rr.run_id IS NULL OR x.execution_owner<>'temporal' OR c.execution_owner<>'temporal'
  OR(x.definition_version,x.input_digest) IS DISTINCT FROM(c.definition_version,c.input_digest) OR rr.definition_version IS DISTINCT FROM x.definition_version
  OR rr.lease_owner IS NOT NULL OR rr.lease_token IS NOT NULL OR rr.lease_expires_at IS NOT NULL
  OR phase<>'message' AND(q->'definition_version',q->>'input_digest') IS DISTINCT FROM(to_jsonb(x.definition_version),x.input_digest) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered lifecycle retained owner changed';END IF;
 SELECT * INTO tr FROM public.zasp_security_agent_trigger_receipts WHERE(organization_id,workspace_id,environment_id,run_id,definition_id,trigger_id)=(o,w,e,r,rr.definition_id,rr.trigger_id) FOR SHARE;
 SELECT * INTO h FROM public.zasp_security_agent_definition_versions WHERE(organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,rr.definition_id,rr.definition_version) FOR SHARE;
 IF tr.run_id IS NULL OR tr.trigger_kind NOT IN('finding','attack_path') OR encode(tr.trigger_digest,'hex') IS DISTINCT FROM x.input_digest
  OR r IS DISTINCT FROM public.zasp_discovery_canonical_id(o,w,e,'security_agent_run',rr.definition_id||chr(31)||rr.trigger_id||chr(31)||tr.trigger_version::text)
  OR h.definition_id IS NULL OR h.definition_digest IS DISTINCT FROM digest(convert_to(h.definition::text,'UTF8'),'sha256') OR h.definition->'allowed_actions' IS DISTINCT FROM '["create_temporary_policy","run_test"]'::jsonb THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered lifecycle historical admission changed';END IF;
 SELECT * INTO receipt FROM public.zasp_security_agent_request_receipts WHERE(organization_id,workspace_id,environment_id,receipt_id,operation)=(o,w,e,c.event_id,'runSecurityAgent') FOR SHARE;
 SELECT * INTO a FROM public.zasp_security_agent_audit WHERE(organization_id,workspace_id,environment_id,audit_id,run_id)=(o,w,e,receipt.audit_id,r) FOR SHARE;
 IF receipt.receipt_id IS NULL OR a.audit_id IS NULL OR(a.actor_id,receipt.principal_id) IS DISTINCT FROM(rr.requested_by,rr.requested_by)
  OR receipt.intent_digest IS DISTINCT FROM digest(convert_to(receipt.intent::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered lifecycle committed start absent';END IF;
 start_receipt_digest:=encode(digest(convert_to(jsonb_build_array(receipt.receipt_id,receipt.principal_id,receipt.audit_id,encode(receipt.intent_digest,'hex'),encode(a.event_digest,'hex'))::text,'UTF8'),'sha256'),'hex');
 IF phase='message' THEN
  SELECT * INTO m FROM zasp_temporal65.commands WHERE(organization_id,workspace_id,environment_id,run_id,event_id,decision_id,kind,execution_owner)=(o,w,e,r,q->>'event_id',q->>'decision_id',q->>'kind','temporal') FOR SHARE;
  SELECT * INTO receipt FROM public.zasp_security_agent_request_receipts WHERE(organization_id,workspace_id,environment_id,receipt_id,operation)=(o,w,e,m.decision_id,CASE m.kind WHEN 'approval' THEN 'decideSecurityAgentApproval' ELSE 'cancelSecurityAgentRun' END) FOR SHARE;
  SELECT * INTO a FROM public.zasp_security_agent_audit WHERE(organization_id,workspace_id,environment_id,audit_id,run_id)=(o,w,e,receipt.audit_id,r) FOR SHARE;
  IF m.run_id IS NULL OR receipt.receipt_id IS NULL OR a.audit_id IS NULL OR a.actor_id IS DISTINCT FROM receipt.principal_id OR m.definition_version IS DISTINCT FROM c.definition_version
   OR receipt.intent_digest IS DISTINCT FROM digest(convert_to(receipt.intent::text,'UTF8'),'sha256') OR m.input_digest IS DISTINCT FROM encode(receipt.intent_digest,'hex') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered lifecycle committed decision absent';END IF;
  decision_digest:=encode(digest(convert_to(jsonb_build_array(m.event_id,m.decision_id,m.kind,m.definition_version,m.input_digest,receipt.principal_id,receipt.audit_id,encode(a.event_digest,'hex'))::text,'UTF8'),'sha256'),'hex');
 END IF;
 source_value:=jsonb_build_array(x.execution_owner,rr.definition_id,x.definition_version,x.input_digest,c.event_id,tr.trigger_kind,tr.trigger_id,tr.trigger_version,encode(h.definition_digest,'hex'),start_receipt_digest,decision_digest);
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal69.current_ready() OR NOT zasp_temporal68.principal_ready('zasp_temporal_compensation') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered lifecycle authority changed after locks';END IF;
